                    <th className="px-8 py-5 text-right">Avg Efficiency</th>
                  </tr>
              )}
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-slate-700/50">
              {viewMode === 'daily' ? (
                  filteredData.length === 0 ? (
                    <tr>
                      <td colSpan={9} className="px-8 py-20 text-center text-slate-400 font-bold uppercase tracking-widest italic">No matching records found</td>
                    </tr>
                  ) : filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity || 0, entry.planQuantity || 0));
                    const isOff = entry.date && offDays.some(od => od.date === entry.date);
                    return (
                      <tr key={entry.id} className={`hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition-colors ${isOff ? 'bg-amber-50/10 dark:bg-amber-900/5' : ''}`}>
                        <td className="px-8 py-6">
                            <div className="font-black text-slate-800 dark:text-white mb-1 font-mono text-xs">{entry.date || 'N/A'}</div>
                            {isOff ? (
                                <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-amber-600 dark:text-amber-400">
                                    <Palmtree className="w-3 h-3" /> Holiday
                                </span>
                            ) : (
                                <span className="text-[9px] font-black uppercase text-slate-300">Operational</span>
                            )}
                        </td>
                        <td className="px-8 py-6 text-center">
                          <span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-900 text-slate-500 border border-slate-200 dark:border-slate-800">
                            {entry.category}
                          </span>
                        </td>
                        <td className="px-8 py-6">
                            <div className="font-black text-slate-800 dark:text-white">{entry.productName}</div>
                            <div className="flex flex-col gap-0.5 mt-0.5">
                              <span className="text-[10px] font-black uppercase text-indigo-500 tracking-tight">{entry.process}</span>
                              {entry.remark && (
                                <div className="flex items-center gap-1 text-[10px] text-slate-400 italic font-medium">
                                  <MessageSquare className="w-2.5 h-2.5" /> {entry.remark}
                                </div>
                              )}
                            </div>
                        </td>
                        <td className="px-8 py-6 text-right font-black font-mono text-slate-700 dark:text-slate-200">{(entry.planQuantity || 0).toLocaleString()}</td>
                        <td className="px-8 py-6 text-right font-black font-mono text-emerald-500">{(entry.actualQuantity || 0).toLocaleString()}</td>
                        <td className="px-8 py-6 text-center">
                          <span className="text-[10px] font-black text-slate-400">{entry.unit || 'KG'}</span>
                        </td>
                        <td className="px-8 py-6 text-right">
                            <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl border font-black text-[11px] ${
                                eff >= 100 ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 
                                eff >= 80 ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 
                                'bg-rose-50 text-rose-600 border-rose-100'
                            }`}>
                                {eff}%
                            </div>
                        </td>
                        {hasPermission(['admin', 'manager', 'hod']) && (
                            <td className="px-8 py-6 text-center">
                                <button onClick={() => handleDelete(entry.id)} className="text-slate-300 hover:text-rose-500 p-2.5 rounded-xl hover:bg-rose-50 dark:hover:bg-rose-900/20 transition-all">
                                  <Trash2 className="w-4 h-4" />
                                </button>
                            </td>
                        )}
                      </tr>
                    );
                  })
              ) : (
                  monthlyData.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-8 py-20 text-center text-slate-400 font-bold uppercase tracking-widest italic">No summaries available</td>
                    </tr>
                  ) : monthlyData.map(m => (
                      <tr key={m.name} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition">
                          <td className="px-8 py-6 font-black text-slate-800 dark:text-white text-lg">{m.name}</td>
                          <td className="px-8 py-6 text-right font-mono font-black text-slate-700 dark:text-slate-200">{(m.plan || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-mono font-black text-emerald-500">{(m.actual || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-black">
                            <div className={`inline-flex px-4 py-2 rounded-2xl font-black text-base ${m.efficiency >= 85 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                              {m.efficiency.toFixed(1)}%
                            </div>
                          </td>
                      </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { User, Role } from '../../types';
import { X, Trash2, Plus } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

export const UserModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { user: currentUser } = useAuth();
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [newUser, setNewUser] = useState({ name: '', username: '', email: '', password: '', role: 'operator' as Role });

  const inputClasses = "p-2 rounded text-sm border border-slate-200 bg-white text-slate-900 font-bold outline-none focus:ring-2 focus:ring-purple-500/20";

  const handleAdd = (e: React.FormEvent) => {
      e.preventDefault();
      // Basic check for duplicate username
      if (users.some(u => u.username.toLowerCase() === newUser.username.toLowerCase())) {
          alert("Username already exists!");
          return;
      }
      const u: User = { 
          id: Date.now().toString(), 
          name: newUser.name, 
          username: newUser.username,
          email: newUser.email, 
          password: newUser.password, 
          role: newUser.role 
      };
      const updated = [...users, u];
      StorageService.saveUsers(updated);
      setUsers(updated);
      setNewUser({ name: '', username: '', email: '', password: '', role: 'operator' });

      window.dispatchEvent(new CustomEvent('app-notification', { 
          detail: { message: 'New user account created successfully!', type: 'success' } 
      }));
  };

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete user?")) return;
      const updated = users.filter(u => u.id !== id);
      StorageService.saveUsers(updated);
      setUsers(updated);
      window.dispatchEvent(new CustomEvent('app-notification', { 
          detail: { message: 'User account removed', type: 'info' } 
      }));
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-xl shadow-2xl flex flex-col max-h-[85vh] animate-in fade-in zoom-in duration-200">
        <div className="p-4 border-b border-gray-200 dark:border-slate-700 flex justify-between items-center">
            <h3 className="font-bold text-lg text-purple-600 dark:text-purple-400">User Management</h3>
            <button onClick={onClose}><X className="text-gray-400 hover:text-gray-600" /></button>
        </div>

        <div className="p-4 bg-purple-50 dark:bg-purple-900/10">
            <form onSubmit={handleAdd} className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <input type="text" placeholder="Full Name" required value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} className={inputClasses} />
                <input type="text" placeholder="Username" required value={newUser.username} onChange={e => setNewUser({...newUser, username: e.target.value})} className={inputClasses} />
                <input type="email" placeholder="Email" required value={newUser.email} onChange={e => setNewUser({...newUser, email: e.target.value})} className={inputClasses} />
                <input type="text" placeholder="Password" required value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} className={inputClasses} />
                <select value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as Role})} className={inputClasses}>
                    <option value="operator">Operator</option>
                    <option value="planner">Planner</option>
                    <option value="hod">HOD</option>
                    <option value="manager">Manager</option>
                    <option value="admin">Admin</option>
                </select>
                <button type="submit" className="md:col-span-2 bg-purple-600 text-white py-2.5 rounded-lg font-bold hover:bg-purple-700 text-sm shadow-md transition">Add New User</button>
            </form>
        </div>

        <div className="flex-1 overflow-y-auto p-2">
            <table className="w-full text-sm text-left">
                <thead className="bg-gray-100 dark:bg-slate-700 font-bold text-gray-500">
                    <tr><th className="p-3">User Details</th><th className="p-3 text-center">Role</th><th className="p-3 text-right">Action</th></tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                    {users.map(u => (
                        <tr key={u.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/30">
                            <td className="p-3">
                                <div className="font-bold text-slate-700 dark:text-slate-200">{u.name}</div>
                                <div className="text-[10px] flex items-center gap-2 mt-1">
                                    <span className="bg-indigo-50 dark:bg-indigo-900/40 text-indigo-600 dark:text-indigo-300 px-1.5 py-0.5 rounded font-mono">@{u.username}</span>
                                    <span className="text-gray-400">{u.email}</span>
                                </div>
                            </td>
                            <td className="p-3 text-center">
                                <span className="bg-gray-100 dark:bg-slate-700 px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-widest text-gray-600 dark:text-gray-400">
                                    {u.role}
                                </span>
                            </td>
                            <td className="p-3 text-right">
                                {currentUser?.id !== u.id && (
                                    <button onClick={() => handleDelete(u.id)} className="text-red-400 hover:text-red-600 transition p-2 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg">
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                )}
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { GoogleSheetsService } from '../../services/googleSheetsService';
import { useAuth } from '../../contexts/AuthContext';
import { User, Role } from '../../types';
import { Trash2, Plus, Database, ShieldCheck, X, Check } from 'lucide-react';

export const UserManagement: React.FC = () => {
  const { user: currentUser } = useAuth();
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [isAdding, setIsAdding] = useState(false);

  // Use the service to get the active URL (either local or hardcoded)
  // Fix: Ensure the initial state is always a string to avoid 'string | null' type errors
  const [sheetUrl, setSheetUrl] = useState<string>(
    localStorage.getItem('halagel_sheets_api_url') || 
    GoogleSheetsService.getActiveUrl() || 
    ''
  );

  const [newUser, setNewUser] = useState<Omit<User, 'id'>>({
      name: '',
      username: '',
      email: '',
      role: 'operator',
      password: ''
  });

  const handleSaveSheetUrl = () => {
    // Fix: Ensure sheetUrl is a string before saving
    localStorage.setItem('halagel_sheets_api_url', sheetUrl || '');
    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'DATABASE CONFIGURATION UPDATED', type: 'success' } 
    }));
  };

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === newUser.username.toLowerCase())) {
        alert("Username already exists!");
        return;
    }
    const u: User = { ...newUser, id: Date.now().toString() };
    const updated = [...users, u];
    StorageService.saveUsers(updated);
    StorageService.addLog({
      userId: currentUser!.id,
      userName: currentUser!.name,
      action: 'ADD_USER',
      details: `Created new user account: ${u.name} (${u.role})`
    });
    setUsers(updated);
    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: `NEW USER CREATED: ${u.name.toUpperCase()}`, type: 'success' } 
    }));
    setIsAdding(false);
    setNewUser({ name: '', username: '', email: '', role: 'operator', password: '' });
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Delete this user?')) {
        const target = users.find(u => u.id === id);
        const updated = users.filter(u => u.id !== id);
        StorageService.saveUsers(updated);
        StorageService.addLog({
          userId: currentUser!.id,
          userName: currentUser!.name,
          action: 'DELETE_USER',
          details: `Removed user account: ${target?.name} (@${target?.username})`
        });
        setUsers(updated);
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `USER REMOVED: ${target?.name.toUpperCase()}`, type: 'info' } 
        }));
    }
  };

  return (
    <div className="space-y-8">
        {/* DB CONFIG FOR ADMINS */}
        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl border border-indigo-100 dark:border-indigo-900/30 shadow-sm">
            <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-3">
                    <Database className="w-6 h-6 text-indigo-500" />
                    <div>
                        <h3 className="text-lg font-black text-slate-800 dark:text-white leading-none">Database Connection</h3>
                        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Status: {localStorage.getItem('halagel_sheets_api_url') ? 'Manual Override' : 'System Default (Active)'}</p>
                    </div>
                </div>
                <div className="flex items-center gap-2 px-3 py-1 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-100 dark:border-emerald-800 rounded-full">
                    <Check className="w-3 h-3 text-emerald-600" />
                    <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Live Sync Enabled</span>
                </div>
            </div>

            <div className="flex flex-col md:flex-row gap-3">
                <div className="flex-1 relative">
                  <input 
                      type="text"
                      placeholder="Google Apps Script URL"
                      className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-3 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 text-[11px] font-mono text-slate-600 dark:text-slate-300"
                      value={sheetUrl || ''}
                      onChange={(e) => setSheetUrl(e.target.value)}
                  />
                </div>
                <button onClick={handleSaveSheetUrl} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-indigo-700 transition flex items-center justify-center gap-2 shadow-lg shadow-indigo-500/20">
                    <ShieldCheck className="w-4 h-4" /> Save Configuration
                </button>
            </div>
            <p className="mt-4 text-[10px] text-slate-400 font-medium italic">
              Note: This URL links your dashboard to the Google Sheets "Database Bridge". Do not change unless moving to a new spreadsheet.
            </p>
        </div>

        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-black text-gray-800 dark:text-white">Staff Management</h2>
            <button 
                onClick={() => setIsAdding(!isAdding)}
