    { label: 'Input Actual', path: '/actual', icon: ClipboardList, roles: ['admin', 'manager', 'hod', 'operator'] },
    { label: 'Reports', path: '/reports', icon: BarChart3, roles: ['admin', 'manager', 'hod', 'planner'] },
    { label: 'Analytics', path: '/process-analytics', icon: Factory, roles: ['admin', 'manager', 'hod'] },
    { label: 'Activity Log', path: '/logs', icon: History, roles: ['admin', 'manager', 'hod'] },
    { label: 'User Mgmt', path: '/users', icon: Users, roles: ['admin'] },
