                        : 'text-slate-400 hover:text-slate-600'
                    }`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            {hasPermission(['admin', 'manager', 'hod']) && (
              <button 
                onClick={() => setIsOffDayOpen(true)}
                className="hidden lg:flex items-center gap-2 px-4 py-2 bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 rounded-xl border border-rose-100 dark:border-rose-800/50 text-[10px] font-black uppercase tracking-widest hover:bg-rose-100 transition"
