              {filteredNav.map(item => (
                <Link
                  key={item.path}
                  to={item.path}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className={`flex items-center gap-4 px-4 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${
                    location.pathname === item.path ? 'bg-indigo-600 text-white' : 'text-slate-500'
