          >
            <Bell className="w-5 h-5 shrink-0" />
            <span className="text-xs font-black uppercase tracking-wider">{n.message}</span>
          </div>
        ))}
      </div>

      {/* Modals */}
      {isLoginOpen && <LoginModal onClose={() => setIsLoginOpen(false)} />}
      {isInputOpen && <InputModal onClose={() => setIsInputOpen(false)} />}
      {isOffDayOpen && <OffDayModal onClose={() => setIsOffDayOpen(false)} />}
      {isPassOpen && <ChangePasswordModal onClose={() => setIsPassOpen(false)} />}
      {isAvatarOpen && <AvatarModal onClose={() => setIsAvatarOpen(false)} />}
    </div>
  );
};

export type Role = 'admin' | 'manager' | 'hod' | 'planner' | 'operator';

export interface User {
  id: string;
  name: string;
  username: string;
  email: string;
  role: Role;
  password?: string; // In a real app, never store plain text. Used here for simulation.
  // Fix: Added missing avatar property used by the AvatarModal component
  avatar?: string;
}

export type Category = 'Healthcare' | 'Toothpaste' | 'Rocksalt' | 'Cosmetic';

export type ProcessType = 'Mixing' | 'Encapsulation' | 'Filling' | 'Sorting' | 'Packing';

export type UnitType = 'KG' | 'PCS';

export interface ProductionEntry {
  id: string;
  date: string; // YYYY-MM-DD
  category: Category;
  process: ProcessType;
  productName: string;
  planQuantity: number;
  actualQuantity: number;
  unit: UnitType;
  batchNo?: string;
  manpower?: number;
  remark?: string;
  lastUpdatedBy: string;
  updatedAt: string;
}

export interface OffDay {
  id: string;
  date: string; // YYYY-MM-DD
  description: string;
  createdBy: string;
}

export interface ActivityLog {
  id: string;
  timestamp: string;
  userId: string;
  userName: string;
  action: string;
  details: string;
}

export interface DashboardStats {
  totalPlan: number;
  totalActual: number;
  avgEfficiency: number;
  totalManpower: number;
}

