                    {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover" /> : <UserIcon className="w-full h-full p-2 text-indigo-500" />}
                  </div>
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity rounded-xl">
                    <Plus className="w-4 h-4 text-white" />
                  </div>
                </button>
                <div className="flex-1 overflow-hidden">
                  <p className="text-xs font-black text-slate-800 dark:text-white truncate uppercase tracking-tight">{user.name}</p>
                  <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest">{user.role}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-2">
                <button onClick={() => setIsPassOpen(true)} className="flex items-center justify-center p-3 bg-white dark:bg-slate-800 border border-gray-100 dark:border-slate-700 rounded-xl hover:text-indigo-600 transition shadow-sm">
                  <Key className="w-4 h-4" />
                </button>
                <button onClick={logout} className="flex items-center justify-center p-3 bg-white dark:bg-slate-800 border border-gray-100 dark:border-slate-700 rounded-xl hover:text-rose-500 transition shadow-sm">
                  <LogOut className="w-4 h-4" />
                </button>
              </div>
            </div>
          ) : (
            <button
              onClick={() => setIsLoginOpen(true)}
              className="w-full flex items-center justify-center gap-2 py-4 bg-slate-900 dark:bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-indigo-500/10"
            >
              <LogIn className="w-4 h-4" /> Sign In
            </button>
          )}
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0">
        {/* Header - Desktop & Mobile */}
        <header className="h-20 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-gray-100 dark:border-slate-800 sticky top-0 z-30 px-4 md:px-10 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 text-slate-600 dark:text-white">
              <Menu className="w-6 h-6" />
            </button>
            <div className="hidden sm:flex items-center gap-3">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Select Department:</span>
              <div className="flex bg-gray-50 dark:bg-slate-800 p-1 rounded-xl border border-gray-100 dark:border-slate-700">
                {CATEGORIES.map(cat => (
                  <button
                    key={cat}
                    onClick={() => setCategory(cat as any)}
                    className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${
                      category === cat 
                        ? 'bg-white dark:bg-slate-700 text-indigo-600 shadow-sm' 
                        : 'text-slate-400 hover:text-slate-600'
                    }`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            {hasPermission(['admin', 'manager', 'hod']) && (
              <button 
                onClick={() => setIsOffDayOpen(true)}
                className="hidden lg:flex items-center gap-2 px-4 py-2 bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 rounded-xl border border-rose-100 dark:border-rose-800/50 text-[10px] font-black uppercase tracking-widest hover:bg-rose-100 transition"
              >
                <CalendarClock className="w-4 h-4" /> Off Days
              </button>
            )}

            <button
              onClick={toggleDarkMode}
              className="p-2.5 bg-gray-50 dark:bg-slate-800 text-slate-600 dark:text-amber-400 rounded-xl border border-gray-100 dark:border-slate-700 shadow-sm transition hover:scale-105 active:scale-95"
            >
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>

            <button onClick={triggerRefresh} className="p-2.5 bg-gray-50 dark:bg-slate-800 text-indigo-600 rounded-xl border border-gray-100 dark:border-slate-700 shadow-sm transition hover:scale-105">
              <RefreshCw className="w-5 h-5" />
            </button>

            {hasPermission(['admin', 'manager', 'hod', 'planner', 'operator']) && (
              <button onClick={() => setIsInputOpen(true)} className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 text-white rounded-xl font-black text-xs uppercase tracking-widest shadow-lg shadow-indigo-500/20 hover:bg-indigo-700 transition">
                <Plus className="w-4 h-4" /> <span className="hidden sm:inline">New Record</span>
              </button>
            )}
          </div>
        </header>

        {/* Dynamic Main View */}
        <div className="flex-1 p-4 md:p-10">
          {children}
        </div>
      </main>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex justify-start animate-in fade-in duration-300">
          <div className="w-72 bg-white dark:bg-slate-900 h-full p-8 shadow-2xl flex flex-col animate-in slide-in-from-left duration-300">
            <div className="flex justify-between items-center mb-10">
              <h2 className="text-xl font-black text-indigo-600">NEXUS</h2>
              <button onClick={() => setIsMobileMenuOpen(false)} className="p-2 rounded-lg bg-slate-100 dark:bg-slate-800"><X className="w-5 h-5" /></button>
            </div>
            <nav className="space-y-2 flex-1">
              {filteredNav.map(item => (
                <Link
                  key={item.path}
                  to={item.path}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className={`flex items-center gap-4 px-4 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${
                    location.pathname === item.path ? 'bg-indigo-600 text-white' : 'text-slate-500'
                  }`}
                >
                  <item.icon className="w-5 h-5" /> {item.label}
                </Link>
              ))}
            </nav>
            <div className="pt-8 border-t dark:border-slate-800">
              {user && (
                <button onClick={logout} className="w-full flex items-center justify-center gap-3 py-4 bg-rose-50 text-rose-600 rounded-2xl text-xs font-black uppercase tracking-widest">
                  <LogOut className="w-4 h-4" /> Sign Out
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Notifications Portal */}
      <div className="fixed bottom-6 right-6 z-[100] flex flex-col gap-3 pointer-events-none">
        {notifications.map(n => (
          <div 
            key={n.id} 
            className={`pointer-events-auto px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 border-l-8 notification-animate ${
              n.type === 'success' ? 'bg-emerald-50 text-emerald-800 border-emerald-500' : 
              n.type === 'info' ? 'bg-indigo-50 text-indigo-800 border-indigo-500' :
              'bg-amber-50 text-amber-800 border-amber-500'
            }`}
          >
            <Bell className="w-5 h-5 shrink-0" />
            <span className="text-xs font-black uppercase tracking-wider">{n.message}</span>
          </div>
        ))}
      </div>

      {/* Modals */}
      {isLoginOpen && <LoginModal onClose={() => setIsLoginOpen(false)} />}
      {isInputOpen && <InputModal onClose={() => setIsInputOpen(false)} />}
      {isOffDayOpen && <OffDayModal onClose={() => setIsOffDayOpen(false)} />}
      {isPassOpen && <ChangePasswordModal onClose={() => setIsPassOpen(false)} />}
      {isAvatarOpen && <AvatarModal onClose={() => setIsAvatarOpen(false)} />}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, RefreshCw, List, Calendar, 
  Download, Pencil, Trash2, Layers,
  Palmtree, MessageSquare
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);

    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    PROCESSES.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);

        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od && od.date && od.date.trim().startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => {
      if (d.date) dates.add(d.date.trim().substring(0, 10));
    });
    filteredOffDays.forEach(od => {
      if (od.date) dates.add(od.date.trim().substring(0, 10));
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));

    return sortedDates.map(dateKey => {
        const entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);
        const offDayInfo = filteredOffDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Are you sure you want to PERMANENTLY delete this record? This action cannot be undone.")) return;
      const { deletedItem } = StorageService.deleteProductionEntry(id);

      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id,
            userName: user!.name,
            action: 'DELETE_RECORD',
            details: `Admin/Manager/HOD permanently deleted production record: ${deletedItem.productName} (${deletedItem.date})`
          });

          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED SUCCESSFULLY', type: 'info' } 
          }));
      }
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const downloadCSV = () => {
    const headers = ["Date", "Status", "Process", "Product", "Plan", "Actual", "Unit", "Batch No", "Manpower", "Remark"];
    const rows = dailyGroups.flatMap(g => {
        if (g.entries.length === 0) {
            return [[g.date, g.offDayName || 'Off Day', '-', '-', 0, 0, '-', '-', 0, '-']];
        }
        return g.entries.map(d => [
            d.date, g.isOffDay ? `Holiday (${g.offDayName})` : 'Normal', d.process, d.productName, d.planQuantity, d.actualQuantity, d.unit || 'KG', d.batchNo, d.manpower, (d.remark || '').replace(/,/g, ';')
        ]);
    });
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Halagel_Full_Report_${category}_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();

    StorageService.addLog({
      userId: user!.id,
      userName: user!.name,
      action: 'EXPORT_REPORT',
      details: `Exported full report for ${category} (${selectedMonth})`
    });

    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  return (
    <div className="space-y-8 pb-12">
      {/* MONTHLY PROCESS BREAKDOWN */}
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
            <Layers className="w-4 h-4 text-indigo-500" />
            <h3 className="text-[12px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-800 shadow-sm group hover:border-indigo-500/30 transition-all duration-300">
                        <div className="flex items-center justify-between mb-6">
                          <p className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{item.process}</p>
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse" />
                        </div>

                        <div className="space-y-5">
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-tighter">Planned Output</span>
                                <span className="text-2xl font-black text-slate-800 dark:text-white font-mono leading-none">{(item.Plan || 0).toLocaleString()}</span>
                            </div>

                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-tighter">Actual Result</span>
                                <span className="text-2xl font-black text-emerald-500 font-mono leading-none">{(item.Actual || 0).toLocaleString()}</span>
                            </div>

                            <div className="pt-5 border-t border-gray-50 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Efficiency</span>
                                <span className={`text-xl font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(1)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      {/* Daily Logs */}
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Operational granularity for {selectedMonth}</p>
            </div>

            <div className="flex items-center gap-3">
              <input 
                type="month" 
                value={selectedMonth} 
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none"
              />
              <button onClick={downloadCSV} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white text-xs font-black rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-500/20 uppercase tracking-widest transition">
                <Download className="w-4 h-4" /> Export Report
              </button>
            </div>
        </div>

        <div className="space-y-6">
            {dailyGroups.length === 0 ? (
                <div className="glass-panel p-16 rounded-[2rem] text-center">
                    <div className="flex flex-col items-center gap-4">
                        <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-full text-slate-200">
                            <ClipboardList className="w-12 h-12" />
                        </div>
                        <p className="text-slate-400 font-bold uppercase tracking-widest">No production logs found for the selected month.</p>
                        <p className="text-xs text-slate-400">Try changing the category or month filter.</p>
                    </div>
                </div>
            ) : dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-slate-850 rounded-[2rem] overflow-hidden shadow-sm border ${group.isOffDay ? 'border-amber-400/50' : 'border-gray-100 dark:border-slate-800'}`}>
                      <div className={`p-6 flex justify-between items-center border-b ${group.isOffDay ? 'bg-amber-50 dark:bg-amber-900/10 border-amber-100 dark:border-amber-900/30' : 'border-gray-100 dark:border-slate-800 bg-gray-50/50 dark:bg-slate-800/50'}`}>
                          <div className="flex items-center gap-4">
                              {group.isOffDay ? <Palmtree className="w-6 h-6 text-amber-500" /> : <Calendar className="w-6 h-6 text-slate-400" />}
                              <div className="flex items-center gap-3">
                                <span className={`text-xl font-black ${group.isOffDay ? 'text-amber-700 dark:text-amber-400' : 'text-slate-800 dark:text-white'}`}>{datePart}</span>
                                <span className={`text-xl font-medium uppercase tracking-tight ${group.isOffDay ? 'text-amber-800' : 'text-slate-800 dark:text-slate-200'}`}>
                                  {dayPart}
                                </span>
                              </div>
                              {group.isOffDay && (
                                <span className="px-3 py-1 bg-amber-500 text-white text-[9px] font-black uppercase rounded-full shadow-sm tracking-widest">
                                    {group.offDayName || 'OFF DAY'}
                                </span>
                              )}
                          </div>
                          <div className="px-4 py-1.5 bg-white dark:bg-slate-900 rounded-xl border border-gray-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-black text-[11px] uppercase tracking-widest">
                            Actual: <span className="text-emerald-500 ml-1 font-mono">{(group.totalActualForDate || 0).toLocaleString()}</span>
                          </div>
                      </div>

                      {group.entries.length > 0 ? (
                        <div className="overflow-x-auto no-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-gray-50 dark:border-slate-800 text-[9px] font-black text-slate-400 uppercase tracking-widest bg-gray-50/30 dark:bg-slate-900/30">
                                        <th className="px-8 py-4">Process</th>
                                        <th className="px-8 py-4">Product</th>
                                        <th className="px-8 py-4 text-right">Plan Data</th>
                                        <th className="px-8 py-4 text-right">Actual Data</th>
                                        <th className="px-8 py-4 text-center">Efficiency</th>
                                        <th className="px-8 py-4 text-center">Batch No</th>
                                        <th className="px-8 py-4 text-center">Manpower</th>
                                        {hasPermission(['admin', 'manager', 'hod']) && <th className="px-8 py-4 text-center">Action</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => {
                                        const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                        return (
                                            <tr key={entry.id} className="hover:bg-gray-50/50 dark:hover:bg-slate-800/30 transition-colors">
                                                <td className="px-8 py-5">
                                                    <span className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase bg-indigo-50 dark:bg-indigo-900/30 px-2 py-1 rounded-lg border border-indigo-100 dark:border-indigo-800">{entry.process}</span>
                                                </td>
                                                <td className="px-8 py-5">
                                                    <span className="text-sm font-black text-slate-800 dark:text-white uppercase">{entry.productName}</span>
                                                </td>
                                                <td className="px-8 py-5 text-right">
                                                    <div className="font-black font-mono text-indigo-600/80 dark:text-indigo-400/80 text-sm whitespace-nowrap">
                                                      {(entry.planQuantity || 0).toLocaleString()} 
                                                      <span className="text-[9px] ml-1 opacity-60 text-slate-600 dark:text-slate-400 font-sans tracking-tight">{entry.unit}</span>
                                                    </div>
                                                    {entry.remark && (
                                                      <div className="text-[9px] font-bold text-slate-400 italic mt-1 uppercase max-w-[120px] ml-auto">Note: {entry.remark}</div>
                                                    )}
                                                </td>
                                                <td className="px-8 py-5 text-right">
                                                    <div className="font-black font-mono text-emerald-500 text-sm whitespace-nowrap">
                                                      {(entry.actualQuantity || 0).toLocaleString()} 
                                                      <span className="text-[9px] ml-1 opacity-60 text-slate-600 dark:text-slate-400 font-sans tracking-tight">{entry.unit}</span>
                                                    </div>
                                                    {entry.remark && (
                                                      <div className="text-[9px] font-bold text-slate-400 italic mt-1 uppercase max-w-[120px] ml-auto">Note: {entry.remark}</div>
                                                    )}
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className={`text-sm font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                                        {(eff || 0).toFixed(0)}%
                                                    </span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-[11px] font-bold text-slate-400 uppercase tracking-tighter font-mono">{entry.batchNo || '-'}</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-base font-black text-slate-800 dark:text-white font-mono">{(entry.manpower || 0).toFixed(2)}</span>
                                                </td>
                                                {hasPermission(['admin', 'manager', 'hod']) && (
                                                  <td className="px-8 py-5">
                                                      <div className="flex items-center justify-center gap-2">
                                                          <button onClick={() => handleEdit(entry)} className="p-1.5 text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition">
                                                              <Pencil className="w-4 h-4" />
                                                          </button>
                                                          <button onClick={() => handleDelete(entry.id)} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition">
                                                              <Trash2 className="w-4 h-4" />
                                                          </button>
                                                      </div>
                                                  </td>
                                                )}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                      ) : (
                        <div className="p-10 text-center text-slate-400 text-xs italic font-bold uppercase tracking-widest">
                            No production activity recorded for this date.
                        </div>
                      )}
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree, MessageSquare } from 'lucide-react';
import { getTodayISO, getDbTimestamp } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0.00');
  const [batchNo, setBatchNo] = useState('');
  const [remark, setRemark] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => {
    const inputDate = (date || '').trim().split(' ')[0];
    return offDays.find(od => (od.date || '').trim().split(' ')[0] === inputDate);
  }, [date, offDays]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (currentOffDay && !editEntry) {
      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: `PUBLIC HOLIDAY: ${currentOffDay.description}`, type: 'info' } 
      }));
    }
  }, [currentOffDay, editEntry]);

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');
      const isActualMode = editEntry.actualQuantity > 0;
      setQuantity(isActualMode ? (editEntry.actualQuantity || 0).toString() : (editEntry.planQuantity || 0).toString());
      setManpower(editEntry.manpower?.toFixed(2) || '0.00');
      setBatchNo(editEntry.batchNo || '');
      setRemark(editEntry.remark || '');
      setTab(isActualMode ? 'Actual' : 'Plan'); 
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const normalizedInputDate = (date || '').trim().split(' ')[0];
        const relevant = all.filter(p => (p.date || '').trim().split(' ')[0] === normalizedInputDate);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const normalizedDate = (date || '').trim().split(' ')[0];

    if (!editEntry && currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `ENTRY RESTRICTED: Today is ${currentOffDay.description}`, type: 'info' } 
        }));
        setIsSubmitting(false);
        return;
    }

    const currentData = StorageService.getProductionData();

    try {
        if (editEntry) {
            const changes: string[] = [];
            const newQty = parseInt(quantity || '0');
            const newManpower = parseFloat(manpower || '0');

            if (editEntry.date !== normalizedDate) changes.push(`Date`);
            if (editEntry.productName !== productName) changes.push(`Product`);
            if (editEntry.category !== category) changes.push(`Category`);
            if (editEntry.process !== process) changes.push(`Process`);

            if (tab === 'Plan') {
              if (editEntry.planQuantity !== newQty) changes.push(`Plan Qty`);
            } else {
              if (editEntry.actualQuantity !== newQty) changes.push(`Actual Qty`);
            }

            if ((editEntry.manpower || 0) !== newManpower) changes.push(`Manpower`);

            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? newQty : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? newQty : p.actualQuantity,
                        batchNo, manpower: newManpower, remark,
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    };
                }
                return p;
            });

            StorageService.saveProductionData(updated);
            StorageService.addLog({
              userId: user!.id,
              userName: user!.name,
              action: 'EDIT_RECORD',
              details: `Admin/Manager/HOD updated record for ${productName} (${normalizedDate})`
            });
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, unit,
                    planQuantity: parseInt(quantity || '0'), actualQuantity: 0,
                    remark,
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'CREATE_PLAN',
                  details: `Planned ${newEntry.planQuantity} ${newEntry.unit} for ${newEntry.productName} (${normalizedDate})`
                });
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const targetPlan = currentData.find(p => p.id === selectedPlanId);
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity || '0'), batchNo, manpower: parseFloat(manpower || '0'), remark,
                            lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                        };
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'RECORD_ACTUAL',
                  details: `Recorded actual output of ${quantity} ${targetPlan?.unit || 'KG'} for ${targetPlan?.productName || 'product'}`
                });
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'PRODUCTION RECORD SYNCHRONIZED', type: 'success' } 
        }));
        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: err.message || 'Operation failed', type: 'info' } 
        }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative max-h-[90vh] flex flex-col">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-[60] flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Uploading to Cloud...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700 shrink-0">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'hod', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'hod', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center text-indigo-600 border-b-2 border-indigo-600">
                Updating Record
              </div>
            )}
        </div>

        <div className="p-6 relative overflow-y-auto custom-scrollbar flex-1">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors z-20"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className="mt-3 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-300 dark:border-amber-700 rounded-xl flex items-center gap-3 animate-pulse shadow-sm">
                        <div className="p-2 bg-amber-500 text-white rounded-lg shadow-md">
                          <Palmtree className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className="text-[10px] font-black text-amber-700 dark:text-amber-400 uppercase tracking-widest leading-none mb-1">Public Holiday</p>
                          <p className="text-xs font-black text-slate-900 dark:text-amber-50">{currentOffDay.description || 'OFF DAY'}</p>
                        </div>
                        <AlertTriangle className="w-5 h-5 text-amber-500" />
                      </div>
                    )}
                </div>

                {tab === 'Plan' || editEntry ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input 
                              type="text" 
                              required 
                              value={productName} 
                              onChange={e => setProductName(e.target.value.toUpperCase())} 
                              className={inputClasses} 
                              placeholder="Enter name..." 
                            />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="flex gap-2">
                              <div className="flex-1">
                                  <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Quantity</label>
                                  <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                              </div>
                              <div className="w-24">
                                  <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                  <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                      {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                  </select>
                              </div>
                          </div>
                          {editEntry && (
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                <input type="number" required min="0" step="0.01" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                            </div>
                          )}
                        </div>
                        {editEntry && (
                          <div>
                              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                              <input type="text" value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} />
                          </div>
                        )}
                    </>
                ) : (
                    <>
                        <div className="mb-4">
                             <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Active Job</label>
                             {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans scheduled for this date.</div> : (
                                 <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                     {plans.map(p => (
                                         <div key={p.id} onClick={() => setSelectedPlanId(p.id)}
                                            className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                            <div className="font-black text-sm">{p.productName}</div>
                                            <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-indigo-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity} {p.unit || 'KG'}</div>
                                         </div>
                                     ))}
                                 </div>
                             )}
                        </div>
                        {selectedPlanId && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                        <input type="number" required step="0.01" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                </div>
                            </>
                        )}
                    </>
                )}

                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5">
                      <MessageSquare className="w-3 h-3" /> Remark / Note
                    </label>
                    <textarea 
                        value={remark} 
                        onChange={e => setRemark(e.target.value.toUpperCase())} 
                        className={`${inputClasses} h-20 resize-none font-medium text-xs`}
                        placeholder="ADD ADDITIONAL NOTES HERE..."
                    />
                </div>

                <button 
                    type="submit" 
                    disabled={isSubmitting || (!editEntry && !!currentOffDay)} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-4 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        !!currentOffDay && !editEntry ? 'bg-amber-600' : 
                        tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600 shadow-indigo-500/10' : 
                        'bg-emerald-600 shadow-emerald-500/10'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : (!!currentOffDay && !editEntry ? 'Holiday Entry Locked' : 'Update System')}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { GoogleSheetsService } from '../../services/googleSheetsService';
import { useAuth } from '../../contexts/AuthContext';
import { User, Role } from '../../types';
import { Trash2, Plus, Database, ShieldCheck, X, Check } from 'lucide-react';

export const UserManagement: React.FC = () => {
  const { user: currentUser } = useAuth();
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [isAdding, setIsAdding] = useState(false);

  const [sheetUrl, setSheetUrl] = useState<string>(
    localStorage.getItem('halagel_sheets_api_url') || 
    GoogleSheetsService.getActiveUrl() || 
    ''
  );

  const [newUser, setNewUser] = useState<Omit<User, 'id'>>({
      name: '',
      username: '',
      email: '',
      role: 'operator',
      password: ''
  });

  const handleSaveSheetUrl = () => {
    localStorage.setItem('halagel_sheets_api_url', sheetUrl || '');
    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'DATABASE CONFIGURATION UPDATED', type: 'success' } 
    }));
  };

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === newUser.username.toLowerCase())) {
        alert("Username already exists!");
        return;
    }
    const u: User = { ...newUser, id: Date.now().toString() };
    const updated = [...users, u];
    StorageService.saveUsers(updated);
    StorageService.addLog({
      userId: currentUser!.id,
      userName: currentUser!.name,
      action: 'ADD_USER',
      details: `Created new user account: ${u.name} (${u.role})`
    });
    setUsers(updated);
    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: `NEW USER CREATED: ${u.name.toUpperCase()}`, type: 'success' } 
    }));
    setIsAdding(false);
    setNewUser({ name: '', username: '', email: '', role: 'operator', password: '' });
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Delete this user?')) {
        const target = users.find(u => u.id === id);
        const updated = users.filter(u => u.id !== id);
        StorageService.saveUsers(updated);
        StorageService.addLog({
          userId: currentUser!.id,
          userName: currentUser!.name,
          action: 'DELETE_USER',
          details: `Removed user account: ${target?.name} (@${target?.username})`
        });
        setUsers(updated);
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `USER REMOVED: ${target?.name.toUpperCase()}`, type: 'info' } 
        }));
    }
  };

  return (
    <div className="space-y-8">
        {/* DB CONFIG FOR ADMINS */}
        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl border border-indigo-100 dark:border-indigo-900/30 shadow-sm">
            <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-3">
                    <Database className="w-6 h-6 text-indigo-500" />
                    <div>
                        <h3 className="text-lg font-black text-slate-800 dark:text-white leading-none">Database Connection</h3>
                        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Status: {localStorage.getItem('halagel_sheets_api_url') ? 'Manual Override' : 'System Default (Active)'}</p>
                    </div>
                </div>
                <div className="flex items-center gap-2 px-3 py-1 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-100 dark:border-emerald-800 rounded-full">
                    <Check className="w-3 h-3 text-emerald-600" />
                    <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Live Sync Enabled</span>
                </div>
            </div>

            <div className="flex flex-col md:flex-row gap-3">
                <div className="flex-1 relative">
                  <input 
                      type="text"
                      placeholder="Google Apps Script URL"
                      className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-3 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 text-[11px] font-mono text-slate-600 dark:text-slate-300"
                      value={sheetUrl || ''}
                      onChange={(e) => setSheetUrl(e.target.value)}
                  />
                </div>
                <button onClick={handleSaveSheetUrl} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-indigo-700 transition flex items-center justify-center gap-2 shadow-lg shadow-indigo-500/20">
                    <ShieldCheck className="w-4 h-4" /> Save Configuration
                </button>
            </div>
            <p className="mt-4 text-[10px] text-slate-400 font-medium italic">
              Note: This URL links your dashboard to the Google Sheets "Database Bridge". Do not change unless moving to a new spreadsheet.
            </p>
        </div>

        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-black text-gray-800 dark:text-white">Staff Management</h2>
            <button 
                onClick={() => setIsAdding(!isAdding)}
                className="bg-slate-900 dark:bg-indigo-600 text-white px-5 py-2.5 rounded-xl flex items-center gap-2 hover:opacity-90 transition shadow-lg shadow-indigo-500/20 text-xs font-black uppercase tracking-widest"
            >
                {isAdding ? <X className="w-4 h-4" /> : <Plus className="w-4 h-4" />}
                {isAdding ? 'Cancel' : 'Create Account'}
            </button>
        </div>

        {isAdding && (
            <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-sm border border-indigo-100 dark:border-slate-700 animate-in fade-in slide-in-from-top-4">
                <h3 className="text-lg font-black mb-6 dark:text-white">New User Profile</h3>
                <form onSubmit={handleAddUser} className="grid grid-cols-1 md:grid-cols-2 gap-5">
                    <div className="space-y-1">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Full Name</label>
                        <input type="text" required className="w-full border dark:border-slate-600 dark:bg-slate-900 p-2.5 rounded-xl outline-none dark:text-white font-bold" value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Username</label>
                        <input type="text" required className="w-full border dark:border-slate-600 dark:bg-slate-900 p-2.5 rounded-xl outline-none dark:text-white font-bold" value={newUser.username} onChange={e => setNewUser({...newUser, username: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Email</label>
                        <input type="email" required className="w-full border dark:border-slate-600 dark:bg-slate-900 p-2.5 rounded-xl outline-none dark:text-white font-bold" value={newUser.email} onChange={e => setNewUser({...newUser, email: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Initial Password</label>
                        <input type="text" required className="w-full border dark:border-slate-600 dark:bg-slate-900 p-2.5 rounded-xl outline-none dark:text-white font-bold" value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">System Role</label>
                        <select className="w-full border dark:border-slate-600 dark:bg-slate-900 p-2.5 rounded-xl outline-none dark:text-white font-bold" value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as Role})}>
                            <option value="admin">Administrator</option>
                            <option value="manager">Manager</option>
                            <option value="hod">HOD (Head of Dept)</option>
                            <option value="planner">Planner</option>
                            <option value="operator">Operator</option>
                        </select>
                    </div>
                    <div className="md:col-span-2 pt-4">
                        <button type="submit" className="bg-indigo-600 text-white px-8 py-3 rounded-xl shadow-lg hover:bg-indigo-700 transition font-black text-xs uppercase tracking-widest">Submit Account Details</button>
                    </div>
                </form>
            </div>
        )}

        <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
            <table className="w-full text-left text-sm">
                <thead className="bg-gray-50 dark:bg-slate-900 text-gray-700 dark:text-slate-200 border-b dark:border-slate-700 uppercase font-bold text-[10px] tracking-widest">
                    <tr>
                        <th className="px-8 py-5">Staff Member</th>
                        <th className="px-8 py-5">Email</th>
                        <th className="px-8 py-5 text-center">Permissions</th>
                        <th className="px-8 py-5 text-right">Control</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                    {users.map(u => (
                        <tr key={u.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/30 transition-colors">
                            <td className="px-8 py-6">
                                <div className="font-black text-slate-800 dark:text-white">{u.name}</div>
                                <div className="text-[10px] text-indigo-600 dark:text-indigo-400 font-mono font-bold tracking-tighter">@{u.username}</div>
                            </td>
                            <td className="px-8 py-6 text-slate-500 dark:text-gray-400 font-medium">{u.email}</td>
                            <td className="px-8 py-6 text-center">
                                <span className="bg-indigo-50 dark:bg-indigo-900/30 px-3 py-1.5 rounded-lg text-[9px] uppercase font-black tracking-[0.1em] text-indigo-600 dark:text-indigo-400 border border-indigo-100 dark:border-indigo-900/50">
                                    {u.role}
                                </span>
                            </td>
                            <td className="px-8 py-6 text-right">
                                <button 
                                    onClick={() => handleDelete(u.id)}
                                    className="text-slate-400 hover:text-rose-600 p-2.5 transition-colors hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-xl"
                                    disabled={u.role === 'admin' && users.filter(x => x.role === 'admin').length <= 1}
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    </div>
  );
};

export type Role = 'admin' | 'manager' | 'hod' | 'planner' | 'operator';

