import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType, ProductionStatus, OffDay } from '../../types';
import { X, Loader2, Palmtree, MessageSquare, Ban } from 'lucide-react';
import { getTodayISO, getDbTimestamp } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');
  const [planRemark, setPlanRemark] = useState('');
  const [actualRemark, setActualRemark] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const currentOffDay = useMemo(() => {
    const inputDate = (date || '').trim().split(' ')[0];
    return offDays.find((od: OffDay) => (od.date || '').trim().split(' ')[0] === inputDate);
  }, [date, offDays]);

  const isLocked = !editEntry && !!currentOffDay;

  const availableProcesses = useMemo(() => {
    // Encapsulation, Blister, and Capsules are exclusive to Healthcare
    if (category === 'Healthcare') return [...PROCESSES];
    return PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));
  }, [category]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (!availableProcesses.includes(process)) {
      setProcess(availableProcesses[0]);
    }
  }, [category, availableProcesses, process]);

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');

      if (editEntry.actualQuantity > 0) {
        setTab('Actual');
        setQuantity(editEntry.actualQuantity.toString());
      } else {
        setTab('Plan');
        setQuantity(editEntry.planQuantity.toString());
      }

      setManpower(editEntry.manpower ? Number(editEntry.manpower).toString() : '0');
      setBatchNo(editEntry.batchNo || '');
      setPlanRemark(editEntry.planRemark || '');
      setActualRemark(editEntry.actualRemark || '');
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const normalizedInputDate = (date || '').trim().split(' ')[0];
        const relevant = all.filter((p: ProductionEntry) => (p.date || '').trim().split(' ')[0] === normalizedInputDate);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isLocked) return;

    setIsSubmitting(true);
    const normalizedDate = (date || '').trim().split(' ')[0];
    const currentData = StorageService.getProductionData();
    const determinedStatus: ProductionStatus = tab === 'Actual' ? 'Completed' : 'In Progress';

    try {
        if (editEntry) {
            const updated = currentData.map((p: ProductionEntry) => {
                if (p.id === editEntry.id) {
                    const newQty = parseInt(quantity || '0');
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? newQty : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? newQty : p.actualQuantity,
                        batchNo, manpower: parseFloat(manpower || '0'),
                        planRemark,
                        actualRemark,
                        status: (tab === 'Actual' && newQty > 0 ? 'Completed' : p.status) as ProductionStatus,
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    } as ProductionEntry;
                }
                return p;
            });
            StorageService.saveProductionData(updated);
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, unit,
                    planQuantity: parseInt(quantity || '0'), actualQuantity: 0,
                    planRemark,
                    actualRemark: '',
                    status: 'In Progress',
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const updated = currentData.map((p: ProductionEntry) => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity || '0'), 
                            unit, batchNo, manpower: parseFloat(manpower || '0'),
                            actualRemark, status: 'Completed' as ProductionStatus,
                            lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                        } as ProductionEntry;
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: determinedStatus === 'Completed' ? 'PRODUCTION COMPLETED' : 'PLAN SAVED', type: 'success' } 
        }));
        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Operation failed', type: 'info' } }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative max-h-[90vh] flex flex-col">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-[60] flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Uploading to Cloud...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700 shrink-0">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        1. Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-50 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        2. Record Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 flex overflow-hidden">
                <button onClick={() => setTab('Plan')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600 bg-indigo-50/10' : 'border-transparent text-slate-400'}`}>
                    Plan Details
                </button>
                <button onClick={() => setTab('Actual')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Actual' ? 'border-emerald-50 text-emerald-600 bg-emerald-50/10' : 'border-transparent text-slate-400'}`}>
                    Actual Results
                </button>
              </div>
            )}
        </div>

        <div className="p-6 relative overflow-y-auto custom-scrollbar flex-1">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors z-20"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className={`mt-3 p-3 border rounded-xl flex items-center gap-3 shadow-sm ${
                        currentOffDay.type === 'Public Holiday' ? 'bg-rose-50 dark:bg-rose-900/20 border-rose-200 dark:border-rose-800' :
                        currentOffDay.type === 'Rest Day' ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-200 dark:border-indigo-800' :
                        'bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-800'
                      }`}>
                        <div className={`p-2 rounded-lg text-white ${
                            currentOffDay.type === 'Public Holiday' ? 'bg-rose-500' :
                            currentOffDay.type === 'Rest Day' ? 'bg-indigo-500' :
                            'bg-amber-500'
                        }`}>
                          <Ban className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className={`text-[10px] font-black uppercase tracking-widest leading-none mb-1 ${
                                currentOffDay.type === 'Public Holiday' ? 'text-rose-600 dark:text-rose-400' :
                                currentOffDay.type === 'Rest Day' ? 'text-indigo-600 dark:text-indigo-400' :
                                'text-amber-600 dark:text-amber-400'
                          }`}>{currentOffDay.type}</p>
                          <p className="text-xs font-black text-slate-900 dark:text-white leading-tight">{currentOffDay.description}</p>
                        </div>
                      </div>
                    )}
                </div>

                {tab === 'Plan' ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {availableProcesses.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value.toUpperCase())} className={inputClasses} placeholder="Enter product name..." />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="flex-1">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Target Plan Qty</label>
                                <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                            </div>
                            <div className="w-24">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                    {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5"><MessageSquare className="w-3 h-3" /> Plan Remark</label>
                            <textarea value={planRemark} onChange={e => setPlanRemark(e.target.value.toUpperCase())} className={`${inputClasses} h-20 resize-none font-medium text-xs`} placeholder="ADD PLANNING NOTES..." />
                        </div>
                    </>
                ) : (
                    <>
                        {!editEntry && (
                          <div className="mb-4">
                               <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Pending Job</label>
                               {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans found for this date.</div> : (
                                   <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                       {plans.map(p => (
                                           <div key={p.id} onClick={() => { setSelectedPlanId(p.id); setProductName(p.productName); setProcess(p.process); setCategory(p.category); }}
                                              className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                              <div className="font-black text-sm">{p.productName}</div>
                                              <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-emerald-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity} {p.unit || 'KG'}</div>
                                           </div>
                                       ))}
                                   </div>
                               )}
                          </div>
                        )}
                        {(selectedPlanId || editEntry) && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="flex-1">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Result Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div className="w-24">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                        <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                            {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                        </select>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                  </div>
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower Used</label>
                                    <input type="number" required step="any" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                  </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5"><MessageSquare className="w-3 h-3" /> Actual Remark</label>
                                    <textarea value={actualRemark} onChange={e => setActualRemark(e.target.value.toUpperCase())} className={`${inputClasses} h-20 resize-none font-medium text-xs`} placeholder="ADD ACTUAL NOTES..." />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button 
                    type="submit" 
                    disabled={isSubmitting || isLocked} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-4 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        isLocked ? 'bg-slate-400 dark:bg-slate-700' : tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600' : 'bg-emerald-600'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : isLocked ? 'Locked - Non Working Day' : (tab === 'Actual' ? 'Submit & Mark Completed' : 'Save Plan Entry')}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay, ProductionStatus, OffDayType } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, List, Calendar, 
  Download, Pencil, Trash2, Layers,
  Palmtree, MessageSquare, ArrowUpDown, Clock, CheckCircle, ShieldAlert, Coffee, Ban
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO, getWeeklyOffDayType } from '../../utils/dateUtils';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;
    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    // Restricted processes logic
    const validProcesses = category === 'Healthcare' 
      ? [...PROCESSES] 
      : PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    validProcesses.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);
        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const dates = new Set<string>();

    filteredEntries.forEach(e => {
        if (e.date) dates.add(e.date.trim().substring(0, 10));
    });

    offDays.forEach(od => {
        if (od.date && od.date.trim().startsWith(selectedMonth)) {
            dates.add(od.date.trim().substring(0, 10));
        }
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));
    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    return sortedDates.map(dateKey => {
        let entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);

        if (sortConfig) {
            entriesForDate = [...entriesForDate].sort((a, b) => {
                let aValue: any = a[sortConfig.key];
                let bValue: any = b[sortConfig.key];
                if (sortConfig.key === 'status') {
                    aValue = statusWeight[a.status as ProductionStatus] || 0;
                    bValue = statusWeight[b.status as ProductionStatus] || 0;
                }
                if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });
        }

        let offDayInfo = offDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);

        if (!offDayInfo) {
           const autoType = getWeeklyOffDayType(dateKey);
           if (autoType) {
               offDayInfo = {
                   id: `auto-${dateKey}`,
                   date: dateKey,
                   type: autoType,
                   description: autoType === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off',
                   createdBy: 'System'
               };
           }
        }

        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            offDay: offDayInfo
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth, sortConfig]);

  const handleDelete = (id: string) => {
      if(!window.confirm("PERMANENTLY delete record?")) return;
      const { deletedItem } = StorageService.deleteProductionEntry(id);
      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id, userName: user!.name, action: 'DELETE_RECORD',
            details: `Deleted: ${deletedItem.productName} (${deletedItem.date})`
          });
          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED', type: 'info' } 
          }));
      }
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const getOffDayIcon = (type: string) => {
    switch(type) {
      case 'Public Holiday': return <Palmtree className="w-6 h-6 text-rose-500" />;
      case 'Rest Day': return <Coffee className="w-6 h-6 text-indigo-500" />;
      case 'Off Day': return <Ban className="w-6 h-6 text-amber-500" />;
      default: return <Calendar className="w-6 h-6 text-slate-400" />;
    }
  };

  const getOffDayBadgeStyle = (type: string) => {
    switch(type) {
      case 'Public Holiday': return 'bg-rose-500 text-white shadow-rose-500/20';
      case 'Rest Day': return 'bg-indigo-500 text-white shadow-indigo-500/20';
      case 'Off Day': return 'bg-amber-500 text-white shadow-amber-500/20';
      default: return 'bg-slate-400 text-white';
    }
  };

  const SortHeader = ({ label, sortKey }: { label: string, sortKey: keyof ProductionEntry }) => (
    <th className="px-8 py-4 cursor-pointer group" onClick={() => handleSort(sortKey)}>
        <div className="flex items-center gap-1">
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-40'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-8 pb-12">
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
            <Layers className="w-4 h-4 text-indigo-500" />
            <h3 className="text-[12px] font-black text-slate-400 uppercase tracking-[0.3em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-800 shadow-sm group hover:border-indigo-500/30 transition-all duration-300">
                        <div className="flex items-center justify-between mb-6">
                          <p className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{item.process}</p>
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse" />
                        </div>
                        <div className="space-y-5">
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Plan</span>
                                <span className="text-2xl font-black text-slate-800 dark:text-white font-mono">{(item.Plan || 0).toLocaleString()}</span>
                            </div>
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Actual</span>
                                <span className="text-2xl font-black text-emerald-500 font-mono">{(item.Actual || 0).toLocaleString()}</span>
                            </div>
                            <div className="pt-5 border-t border-gray-50 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Efficiency</span>
                                <span className={`text-xl font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(1)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">{selectedMonth} Operational granularity</p>
            </div>
            <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none" />
        </div>

        <div className="space-y-6">
            {dailyGroups.length === 0 ? (
                <div className="p-20 text-center glass-panel rounded-[2rem]">
                    <div className="inline-flex p-4 rounded-full bg-slate-50 dark:bg-slate-800 mb-4">
                        <ClipboardList className="w-10 h-10 text-slate-300" />
                    </div>
                    <p className="text-sm font-black text-slate-400 uppercase tracking-widest">No scheduled data for this month</p>
                </div>
            ) : dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');
                const isOff = !!group.offDay;

                const allCompleted = group.entries.length > 0 && group.entries.every(e => e.status === 'Completed');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-slate-850 rounded-[2rem] overflow-hidden shadow-sm border ${
                    isOff ? (
                        group.offDay?.type === 'Public Holiday' ? 'border-rose-400/30' :
                        group.offDay?.type === 'Rest Day' ? 'border-indigo-400/30' :
                        'border-amber-400/30'
                    ) : 'border-gray-100 dark:border-slate-800'
                  }`}>
                      <div className={`p-6 flex justify-between items-center border-b ${
                        isOff ? (
                            group.offDay?.type === 'Public Holiday' ? 'bg-rose-50/30 dark:bg-rose-900/10' :
                            group.offDay?.type === 'Rest Day' ? 'bg-indigo-50/30 dark:bg-indigo-900/10' :
                            'bg-amber-50/30 dark:bg-amber-900/10'
                        ) : 'bg-gray-50/50 dark:bg-slate-800/50'
                      }`}>
                          <div className="flex items-center gap-4">
                              {getOffDayIcon(group.offDay?.type || '')}
                              <div className="flex items-center gap-3">
                                <span className={`text-xl font-black text-slate-800 dark:text-white`}>{datePart}</span>
                                <span className="text-xl font-medium uppercase tracking-tight text-slate-400">{dayPart}</span>
                              </div>
                              {isOff && (
                                <div className="flex items-center gap-2">
                                    <span className={`px-3 py-1 text-[9px] font-black uppercase rounded-full shadow-sm tracking-widest ${getOffDayBadgeStyle(group.offDay!.type)}`}>
                                        {group.offDay!.type}
                                    </span>
                                    <span className="text-xs font-bold text-slate-500 dark:text-slate-400 truncate max-w-[150px]">
                                        {group.offDay!.description}
                                    </span>
                                </div>
                              )}
                          </div>

                          <div className="flex flex-col items-end gap-1.5">
                            <div className="px-4 py-1.5 bg-white dark:bg-slate-900 rounded-xl border border-gray-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-black text-[11px] uppercase tracking-widest shadow-sm">
                              Actual: <span className="text-emerald-500 ml-1 font-mono">{(group.totalActualForDate || 0).toLocaleString()}</span>
                            </div>
                            {group.entries.length > 0 && (
                              <div className={`px-2.5 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-tighter border shadow-sm ${
                                allCompleted ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-amber-50 text-amber-600 border-amber-100'
                              }`}>
                                {allCompleted ? 'All Jobs Completed' : 'Production In Progress'}
                              </div>
                            )}
                          </div>
                      </div>

                      {group.entries.length > 0 && (
                        <div className="overflow-x-auto no-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-gray-50 dark:border-slate-800 text-[9px] font-black text-slate-400 uppercase tracking-widest bg-gray-50/30 dark:bg-slate-900/30">
                                        <SortHeader label="Process" sortKey="process" />
                                        <SortHeader label="Product Name" sortKey="productName" />
                                        <th className="px-8 py-4 text-right">Plan Qty</th>
                                        <th className="px-8 py-4 text-right">Actual Qty</th>
                                        <th className="px-8 py-4 text-center">Efficiency</th>
                                        <th className="px-8 py-4 text-center">Batch No</th>
                                        <th className="px-8 py-4 text-center">Manpower</th>
                                        {hasPermission(['admin', 'manager', 'planner']) && <th className="px-8 py-4 text-center">Action</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => {
                                        const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                        return (
                                            <tr key={entry.id} className="hover:bg-gray-50/50 dark:hover:bg-slate-800/30 transition-colors">
                                                <td className="px-8 py-5">
                                                    <span className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase bg-indigo-50 dark:bg-indigo-900/30 px-2 py-1 rounded-lg border border-indigo-100 dark:border-indigo-800">{entry.process}</span>
                                                </td>
                                                <td className="px-8 py-5">
                                                    <span className="text-sm font-black text-slate-800 dark:text-white">{entry.productName}</span>
                                                </td>
                                                <td className="px-8 py-5 text-right font-black font-mono text-indigo-600/80 dark:text-indigo-400/80 text-sm">
                                                    <div>{(entry.planQuantity || 0).toLocaleString()} <span className="text-[9px] ml-1 opacity-60 font-sans">{entry.unit}</span></div>
                                                    {entry.planRemark && <div className="flex items-center justify-end gap-1 mt-1"><MessageSquare className="w-3 h-3 text-slate-300" /><span className="text-[9px] font-medium text-slate-400 italic max-w-[150px] truncate">{entry.planRemark}</span></div>}
                                                </td>
                                                <td className="px-8 py-5 text-right font-black font-mono text-emerald-500 text-sm">
                                                    <div>{(entry.actualQuantity || 0).toLocaleString()} <span className="text-[9px] ml-1 opacity-60 font-sans">{entry.unit}</span></div>
                                                    {entry.actualRemark && <div className="flex items-center justify-end gap-1 mt-1"><MessageSquare className="w-3 h-3 text-emerald-200" /><span className="text-[9px] font-medium text-emerald-400/80 italic max-w-[150px] truncate">{entry.actualRemark}</span></div>}
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className={`text-sm font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>{(eff || 0).toFixed(0)}%</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-[11px] font-bold text-slate-400 uppercase font-mono">{entry.batchNo || '-'}</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-base font-black text-slate-800 dark:text-white font-mono">{Number(entry.manpower || 0)}</span>
                                                </td>
                                                {hasPermission(['admin', 'manager', 'planner']) && (
                                                  <td className="px-8 py-5 text-center">
                                                      <div className="flex items-center justify-center gap-2">
                                                          <button onClick={() => handleEdit(entry)} className="p-1.5 text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition"><Pencil className="w-4 h-4" /></button>
                                                          <button onClick={() => handleDelete(entry.id)} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition"><Trash2 className="w-4 h-4" /></button>
                                                      </div>
                                                  </td>
                                                )}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                      )}
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, 
  ResponsiveContainer, LineChart, Line, AreaChart, Area, ComposedChart,
  Cell
} from 'recharts';
import { 
  BarChart3, Activity, Target, Zap, 
  Filter, Calendar, ChevronRight, Info,
  TrendingUp, ArrowUpRight, ArrowDownRight,
  GripVertical, MousePointer2
} from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const ProcessAnalytics: React.FC = () => {
  const { refreshKey, isDarkMode } = useDashboard();
  const [dateRange, setDateRange] = useState({ 
    start: new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0], 
    end: getTodayISO() 
  });
  const [selectedCategory, setSelectedCategory] = useState('All');

  const productionData = useMemo(() => StorageService.getProductionData(), [refreshKey]);

  const filteredData = useMemo(() => {
    return productionData.filter(d => {
      const matchCat = selectedCategory === 'All' || d.category === selectedCategory;
      const matchStart = !dateRange.start || d.date >= dateRange.start;
      const matchEnd = !dateRange.end || d.date <= dateRange.end;
      return matchCat && matchStart && matchEnd;
    });
  }, [productionData, dateRange, selectedCategory]);

  const processMetrics = useMemo(() => {
    const metrics: Record<string, { process: string, plan: number, actual: number, efficiency: number, count: number }> = {};

    // Encapsulation, Blister, and Capsules are exclusive to Healthcare
    const validProcesses = selectedCategory === 'Healthcare' 
      ? [...PROCESSES] 
      : PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    validProcesses.forEach(p => {
      metrics[p] = { process: p, plan: 0, actual: 0, efficiency: 0, count: 0 };
    });

    filteredData.forEach(d => {
      if (metrics[d.process]) {
        metrics[d.process].plan += (d.planQuantity || 0);
        metrics[d.process].actual += (d.actualQuantity || 0);
        metrics[d.process].count++;
      }
    });

    return Object.values(metrics).map(m => ({
      ...m,
      efficiency: m.plan > 0 ? Number(((m.actual / m.plan) * 100).toFixed(1)) : 0
    })).sort((a, b) => b.efficiency - a.efficiency);
  }, [filteredData, selectedCategory]);

  const aggregateMetrics = useMemo(() => {
    const totalPlan = processMetrics.reduce((s, m) => s + m.plan, 0);
    const totalActual = processMetrics.reduce((s, m) => s + m.actual, 0);
    const avgEff = totalPlan > 0 ? (totalActual / totalPlan) * 100 : 0;
    const peakProcess = processMetrics[0];

    return { totalPlan, totalActual, avgEff, peakProcess };
  }, [processMetrics]);

  const dailyTrendData = useMemo(() => {
    const daily: Record<string, { date: string, efficiency: number, actual: number, count: number }> = {};

    filteredData.forEach(d => {
      if (!daily[d.date]) daily[d.date] = { date: d.date, efficiency: 0, actual: 0, count: 0 };
      const eff = d.planQuantity > 0 ? (d.actualQuantity / d.planQuantity) * 100 : 0;
      daily[d.date].efficiency += eff;
      daily[d.date].actual += d.actualQuantity;
      daily[d.date].count++;
    });

    return Object.values(daily)
      .sort((a, b) => a.date.localeCompare(b.date))
      .map(d => ({
        ...d,
        efficiency: d.count > 0 ? Number((d.efficiency / d.count).toFixed(1)) : 0
      }));
  }, [filteredData]);

  return (
    <div className="space-y-8 pb-20 animate-in fade-in duration-700">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <div className="p-2 bg-indigo-600 rounded-lg shadow-lg shadow-indigo-500/20">
              <BarChart3 className="w-5 h-5 text-white" />
            </div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-600 dark:text-indigo-400">Intelligence Bureau</span>
          </div>
          <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tight">
            Process <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-violet-500">Analytics</span>
          </h2>
        </div>

        <div className="flex flex-wrap items-center gap-3 bg-white dark:bg-slate-800 p-2 rounded-2xl shadow-xl border border-gray-100 dark:border-slate-700 w-full md:w-auto">
          <div className="flex items-center gap-2 bg-gray-50 dark:bg-slate-900 px-4 py-2.5 rounded-xl border border-gray-100 dark:border-slate-700">
            <Filter className="w-4 h-4 text-slate-400" />
            <select 
              value={selectedCategory} 
              onChange={e => setSelectedCategory(e.target.value)}
              className="bg-transparent text-xs font-black text-slate-600 dark:text-slate-200 outline-none uppercase tracking-widest cursor-pointer"
            >
              <option value="All">All Departments</option>
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="flex items-center gap-3 bg-gray-50 dark:bg-slate-900 px-4 py-2.5 rounded-xl border border-gray-100 dark:border-slate-700">
            <Calendar className="w-4 h-4 text-slate-400" />
            <div className="flex items-center gap-2">
                <input 
                  type="date" 
                  value={dateRange.start} 
                  onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))}
                  className="bg-transparent text-[10px] font-black text-slate-600 dark:text-slate-200 outline-none uppercase"
                />
                <span className="text-slate-300 text-[10px] font-black">TO</span>
                <input 
                  type="date" 
                  value={dateRange.end} 
                  onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))}
                  className="bg-transparent text-[10px] font-black text-slate-600 dark:text-slate-200 outline-none uppercase"
                />
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-gray-100 dark:border-slate-700 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform duration-500">
                <TrendingUp className="w-12 h-12 text-indigo-500" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Average Efficiency</p>
            <div className="flex items-baseline gap-2">
                <h3 className="text-4xl font-black text-slate-800 dark:text-white font-mono">{aggregateMetrics.avgEff.toFixed(1)}%</h3>
                <span className="text-[10px] font-bold text-emerald-500 flex items-center gap-0.5">
                    <ArrowUpRight className="w-3 h-3" /> Nominal
                </span>
            </div>
            <div className="mt-4 w-full h-1 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden">
                <div className="h-full bg-indigo-500 rounded-full" style={{ width: `${aggregateMetrics.avgEff}%` }} />
            </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-gray-100 dark:border-slate-700 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform duration-500">
                <Target className="w-12 h-12 text-emerald-500" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Peak Performance</p>
            <div className="flex flex-col">
                <h3 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tighter truncate">{aggregateMetrics.peakProcess?.process || 'N/A'}</h3>
                <span className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest mt-0.5">Top throughput node</span>
            </div>
            <div className="mt-4 flex items-center gap-2">
                <span className="px-3 py-1 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 text-[9px] font-black rounded-full border border-emerald-100 dark:border-emerald-800 uppercase tracking-widest">
                    {aggregateMetrics.peakProcess?.efficiency}% Eff.
                </span>
            </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-gray-100 dark:border-slate-700 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform duration-500">
                <Activity className="w-12 h-12 text-rose-500" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Actual Output</p>
            <div className="flex items-baseline gap-2">
                <h3 className="text-3xl font-black text-slate-800 dark:text-white font-mono">{aggregateMetrics.totalActual.toLocaleString()}</h3>
                <span className="text-[10px] font-black text-slate-400 uppercase">Units</span>
            </div>
            <p className="text-[9px] font-bold text-slate-400 mt-2 uppercase tracking-widest">Against {aggregateMetrics.totalPlan.toLocaleString()} Plan</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-gray-100 dark:border-slate-700 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform duration-500">
                <Zap className="w-12 h-12 text-amber-500" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Process Nodes</p>
            <div className="flex items-baseline gap-2">
                <h3 className="text-4xl font-black text-slate-800 dark:text-white font-mono">{processMetrics.length}</h3>
                <span className="text-[10px] font-black text-slate-400 uppercase">Stages</span>
            </div>
            <p className="text-[9px] font-bold text-slate-400 mt-2 uppercase tracking-widest">Active Manufacturing Steps</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white dark:bg-slate-800 p-8 rounded-[3rem] shadow-xl shadow-slate-200/50 dark:shadow-none border border-gray-100 dark:border-slate-700">
          <div className="flex items-center justify-between mb-10">
            <div>
              <h3 className="text-xl font-black text-slate-900 dark:text-white">Throughput vs Efficiency</h3>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Correlation analysis across manufacturing nodes</p>
            </div>
          </div>

          <div className="h-[400px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={processMetrics} margin={{ top: 0, right: 0, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? '#334155' : '#f1f5f9'} />
                <XAxis 
                  dataKey="process" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 900, fill: '#94a3b8' }} 
                  dy={10} 
                />
                <YAxis 
                  yAxisId="left"
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 900, fill: '#94a3b8' }} 
                />
                <YAxis 
                  yAxisId="right"
                  orientation="right"
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 900, fill: '#94a3b8' }} 
                  domain={[0, 120]}
                />
                <Tooltip 
                  cursor={{ fill: isDarkMode ? '#1e293b' : '#f8fafc', opacity: 0.4 }}
                  contentStyle={{ 
                      backgroundColor: isDarkMode ? '#1e293b' : '#fff', 
                      borderRadius: '24px', 
                      border: 'none', 
                      boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.25)', 
                      fontSize: '12px',
                      padding: '16px',
                      fontWeight: 'bold'
                  }}
                />
                <Bar yAxisId="left" dataKey="actual" name="Actual Production" radius={[8, 8, 0, 0]} barSize={40}>
                    {processMetrics.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.efficiency >= 90 ? '#4f46e5' : '#f43f5e'} />
                    ))}
                </Bar>
                <Line 
                    yAxisId="right" 
                    type="monotone" 
                    dataKey="efficiency" 
                    stroke="#f59e0b" 
                    strokeWidth={4} 
                    dot={{ fill: '#f59e0b', r: 5, strokeWidth: 2, stroke: '#fff' }} 
                    activeDot={{ r: 8 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
            <div className="bg-indigo-600 p-8 rounded-[3rem] text-white shadow-xl shadow-indigo-200">
                <h3 className="text-xl font-black mb-1">Process Nodes</h3>
                <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60">Real-time status monitor</p>

                <div className="mt-8 space-y-6">
                    {processMetrics.slice(0, 5).map((m, idx) => (
                        <div key={m.process} className="flex flex-col gap-2">
                            <div className="flex justify-between items-end">
                                <span className="text-xs font-black uppercase tracking-widest">{m.process}</span>
                                <span className="text-sm font-black font-mono">{m.efficiency}%</span>
                            </div>
                            <div className="w-full h-2 bg-indigo-500/30 rounded-full overflow-hidden">
                                <div className={`h-full rounded-full transition-all duration-1000 ${
                                    m.efficiency >= 95 ? 'bg-emerald-400' : 
                                    m.efficiency >= 85 ? 'bg-white' : 
                                    'bg-rose-400'
                                }`} style={{ width: `${Math.min(m.efficiency, 100)}%` }} />
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] border border-gray-100 dark:border-slate-700">
                <div className="flex items-center gap-3 mb-6">
                    <Zap className="w-5 h-5 text-amber-500" />
                    <h3 className="text-lg font-black text-slate-900 dark:text-white">Process Guard</h3>
                </div>
                <p className="text-sm text-slate-500 dark:text-slate-400 leading-relaxed font-medium">
                    The <span className="font-black text-indigo-600 dark:text-indigo-400">{selectedCategory === 'All' ? 'Manufacturing' : selectedCategory}</span> portfolio is undergoing deep scan. Encapsulation, Blister, and Capsules are currently filtered for quality compliance.
                </p>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay, ProductionStatus, OffDayType } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, List, Calendar, 
  Download, Pencil, Trash2, Layers,
  Palmtree, MessageSquare, ArrowUpDown, Clock, CheckCircle, ShieldAlert, Coffee, Ban
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO, getWeeklyOffDayType } from '../../utils/dateUtils';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;
    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    // Restricted processes logic: Blister and Capsules are exclusive to Healthcare
    const validProcesses = category === 'Healthcare' 
      ? [...PROCESSES] 
      : PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    validProcesses.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);
        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const dates = new Set<string>();

    filteredEntries.forEach(e => {
        if (e.date) dates.add(e.date.trim().substring(0, 10));
    });

    offDays.forEach(od => {
        if (od.date && od.date.trim().startsWith(selectedMonth)) {
            dates.add(od.date.trim().substring(0, 10));
        }
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));
    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    return sortedDates.map(dateKey => {
        let entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);

        if (sortConfig) {
            entriesForDate = [...entriesForDate].sort((a, b) => {
                let aValue: any = a[sortConfig.key];
                let bValue: any = b[sortConfig.key];
                if (sortConfig.key === 'status') {
                    aValue = statusWeight[a.status as ProductionStatus] || 0;
                    bValue = statusWeight[b.status as ProductionStatus] || 0;
                }
                if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });
        }

        let offDayInfo = offDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);

        if (!offDayInfo) {
           const autoType = getWeeklyOffDayType(dateKey);
           if (autoType) {
               offDayInfo = {
                   id: `auto-${dateKey}`,
                   date: dateKey,
                   type: autoType,
                   description: autoType === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off',
                   createdBy: 'System'
               };
           }
        }

        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            offDay: offDayInfo
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth, sortConfig]);

  const handleDelete = (id: string) => {
      if(!window.confirm("PERMANENTLY delete record?")) return;
      const { deletedItem } = StorageService.deleteProductionEntry(id);
      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id, userName: user!.name, action: 'DELETE_RECORD',
            details: `Deleted: ${deletedItem.productName} (${deletedItem.date})`
          });
          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED', type: 'info' } 
          }));
      }
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const getOffDayIcon = (type: string) => {
    switch(type) {
      case 'Public Holiday': return <Palmtree className="w-6 h-6 text-rose-500" />;
      case 'Rest Day': return <Coffee className="w-6 h-6 text-indigo-500" />;
      case 'Off Day': return <Ban className="w-6 h-6 text-amber-500" />;
      default: return <Calendar className="w-6 h-6 text-slate-400" />;
    }
  };

  const getOffDayBadgeStyle = (type: string) => {
    switch(type) {
      case 'Public Holiday': return 'bg-rose-500 text-white shadow-rose-500/20';
      case 'Rest Day': return 'bg-indigo-500 text-white shadow-indigo-500/20';
      case 'Off Day': return 'bg-amber-500 text-white shadow-amber-500/20';
      default: return 'bg-slate-400 text-white';
    }
  };

  const SortHeader = ({ label, sortKey }: { label: string, sortKey: keyof ProductionEntry }) => (
    <th className="px-8 py-4 cursor-pointer group" onClick={() => handleSort(sortKey)}>
        <div className="flex items-center gap-1">
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-8 pb-12">
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
            <Layers className="w-4 h-4 text-indigo-500" />
            <h3 className="text-[12px] font-black text-slate-400 uppercase tracking-[0.3em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-800 shadow-sm group hover:border-indigo-500/30 transition-all duration-300">
                        <div className="flex items-center justify-between mb-6">
                          <p className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{item.process}</p>
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse" />
                        </div>
                        <div className="space-y-5">
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Plan</span>
                                <span className="text-2xl font-black text-slate-800 dark:text-white font-mono">{(item.Plan || 0).toLocaleString()}</span>
                            </div>
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Actual</span>
                                <span className="text-2xl font-black text-emerald-500 font-mono">{(item.Actual || 0).toLocaleString()}</span>
                            </div>
                            <div className="pt-5 border-t border-gray-50 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Efficiency</span>
                                <span className={`text-xl font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(1)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">{selectedMonth} Operational granularity</p>
            </div>
            <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none" />
        </div>

        <div className="space-y-6">
            {dailyGroups.length === 0 ? (
                <div className="p-20 text-center glass-panel rounded-[2rem]">
                    <div className="inline-flex p-4 rounded-full bg-slate-50 dark:bg-slate-800 mb-4">
                        <ClipboardList className="w-10 h-10 text-slate-300" />
                    </div>
                    <p className="text-sm font-black text-slate-400 uppercase tracking-widest">No scheduled data for this month</p>
                </div>
            ) : dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');
                const isOff = !!group.offDay;

                const allCompleted = group.entries.length > 0 && group.entries.every(e => e.status === 'Completed');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-slate-850 rounded-[2rem] overflow-hidden shadow-sm border ${
                    isOff ? (
                        group.offDay?.type === 'Public Holiday' ? 'border-rose-400/30' :
                        group.offDay?.type === 'Rest Day' ? 'border-indigo-400/30' :
                        'border-amber-400/30'
                    ) : 'border-gray-100 dark:border-slate-800'
                  }`}>
                      <div className={`p-6 flex justify-between items-center border-b ${
                        isOff ? (
                            group.offDay?.type === 'Public Holiday' ? 'bg-rose-50/30 dark:bg-rose-900/10' :
                            group.offDay?.type === 'Rest Day' ? 'bg-indigo-50/30 dark:bg-indigo-900/10' :
                            'bg-amber-50/30 dark:bg-amber-900/10'
                        ) : 'bg-gray-50/50 dark:bg-slate-800/50'
                      }`}>
                          <div className="flex items-center gap-4">
                              {getOffDayIcon(group.offDay?.type || '')}
                              <div className="flex items-center gap-3">
                                <span className={`text-xl font-black text-slate-800 dark:text-white`}>{datePart}</span>
                                <span className="text-xl font-medium uppercase tracking-tight text-slate-400">{dayPart}</span>
                              </div>
                              {isOff && (
                                <div className="flex items-center gap-2">
                                    <span className={`px-3 py-1 text-[9px] font-black uppercase rounded-full shadow-sm tracking-widest ${getOffDayBadgeStyle(group.offDay!.type)}`}>
                                        {group.offDay!.type}
                                    </span>
                                    <span className="text-xs font-bold text-slate-500 dark:text-slate-400 truncate max-w-[150px]">
                                        {group.offDay!.description}
                                    </span>
                                </div>
                              )}
                          </div>

                          <div className="flex flex-col items-end gap-1.5">
                            <div className="px-4 py-1.5 bg-white dark:bg-slate-900 rounded-xl border border-gray-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-black text-[11px] uppercase tracking-widest shadow-sm">
                              Actual: <span className="text-emerald-500 ml-1 font-mono">{(group.totalActualForDate || 0).toLocaleString()}</span>
                            </div>
                            {group.entries.length > 0 && (
                              <div className={`px-2.5 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-tighter border shadow-sm ${
                                allCompleted ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-amber-50 text-amber-600 border-amber-100'
                              }`}>
                                {allCompleted ? 'All Jobs Completed' : 'Production In Progress'}
                              </div>
                            )}
                          </div>
                      </div>

                      {group.entries.length > 0 && (
                        <div className="overflow-x-auto no-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-gray-50 dark:border-slate-800 text-[9px] font-black text-slate-400 uppercase tracking-widest bg-gray-50/30 dark:bg-slate-900/30">
                                        <SortHeader label="Process" sortKey="process" />
                                        <SortHeader label="Product Name" sortKey="productName" />
                                        <th className="px-8 py-4 text-right">Plan Data</th>
                                        <th className="px-8 py-4 text-right">Actual Data</th>
                                        <th className="px-8 py-4 text-center">Efficiency</th>
                                        <th className="px-8 py-4 text-center">Batch No</th>
                                        <th className="px-8 py-4 text-center">Manpower</th>
                                        {hasPermission(['admin', 'manager', 'hod']) && <th className="px-8 py-4 text-center">Action</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => {
                                        const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                        return (
                                            <tr key={entry.id} className="hover:bg-gray-50/50 dark:hover:bg-slate-800/30 transition-colors">
                                                <td className="px-8 py-5">
                                                    <span className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase bg-indigo-50 dark:bg-indigo-900/30 px-2 py-1 rounded-lg border border-indigo-100 dark:border-indigo-800">{entry.process}</span>
                                                </td>
                                                <td className="px-8 py-5">
                                                    <span className="text-sm font-black text-slate-800 dark:text-white uppercase">{entry.productName}</span>
                                                </td>
                                                <td className="px-8 py-5 text-right font-black font-mono text-indigo-600/80 dark:text-indigo-400/80 text-sm">
                                                    <div>{(entry.planQuantity || 0).toLocaleString()} <span className="text-[9px] ml-1 opacity-60 font-sans">{entry.unit}</span></div>
                                                    {entry.planRemark && <div className="flex items-center justify-end gap-1 mt-1"><MessageSquare className="w-3 h-3 text-slate-300" /><span className="text-[9px] font-medium text-slate-400 italic max-w-[150px] truncate">{entry.planRemark}</span></div>}
                                                </td>
                                                <td className="px-8 py-5 text-right font-black font-mono text-emerald-500 text-sm">
                                                    <div>{(entry.actualQuantity || 0).toLocaleString()} <span className="text-[9px] ml-1 opacity-60 font-sans">{entry.unit}</span></div>
                                                    {entry.actualRemark && <div className="flex items-center justify-end gap-1 mt-1"><MessageSquare className="w-3 h-3 text-emerald-200" /><span className="text-[9px] font-medium text-emerald-400/80 italic max-w-[150px] truncate">{entry.actualRemark}</span></div>}
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className={`text-sm font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>{(eff || 0).toFixed(0)}%</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-[11px] font-bold text-slate-400 uppercase font-mono">{entry.batchNo || '-'}</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-base font-black text-slate-800 dark:text-white font-mono">{(entry.manpower || 0).toFixed(2)}</span>
                                                </td>
                                                {hasPermission(['admin', 'manager', 'hod']) && (
                                                  <td className="px-8 py-5 text-center">
                                                      <div className="flex items-center justify-center gap-2">
                                                          <button onClick={() => handleEdit(entry)} className="p-1.5 text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition"><Pencil className="w-4 h-4" /></button>
                                                          <button onClick={() => handleDelete(entry.id)} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition"><Trash2 className="w-4 h-4" /></button>
                                                      </div>
                                                  </td>
                                                )}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                      )}
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType, ProductionStatus, OffDay } from '../../types';
import { X, Loader2, Palmtree, MessageSquare, Ban } from 'lucide-react';
import { getTodayISO, getDbTimestamp } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0.00');
  const [batchNo, setBatchNo] = useState('');
  const [planRemark, setPlanRemark] = useState('');
  const [actualRemark, setActualRemark] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const currentOffDay = useMemo(() => {
    const inputDate = (date || '').trim().split(' ')[0];
    return offDays.find((od: OffDay) => (od.date || '').trim().split(' ')[0] === inputDate);
  }, [date, offDays]);

  const isLocked = !editEntry && !!currentOffDay;

  const availableProcesses = useMemo(() => {
    // Encapsulation, Blister, and Capsules are exclusive to Healthcare
    if (category === 'Healthcare') return [...PROCESSES];
    return PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));
  }, [category]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (!availableProcesses.includes(process)) {
      setProcess(availableProcesses[0]);
    }
  }, [category, availableProcesses, process]);

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');

      if (editEntry.actualQuantity > 0) {
        setTab('Actual');
        setQuantity(editEntry.actualQuantity.toString());
      } else {
        setTab('Plan');
        setQuantity(editEntry.planQuantity.toString());
      }

      setManpower(editEntry.manpower ? Number(editEntry.manpower).toFixed(2) : '0.00');
      setBatchNo(editEntry.batchNo || '');
      setPlanRemark(editEntry.planRemark || '');
      setActualRemark(editEntry.actualRemark || '');
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const normalizedInputDate = (date || '').trim().split(' ')[0];
        const relevant = all.filter((p: ProductionEntry) => (p.date || '').trim().split(' ')[0] === normalizedInputDate);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isLocked) return;

    setIsSubmitting(true);
    const normalizedDate = (date || '').trim().split(' ')[0];
    const currentData = StorageService.getProductionData();
    const determinedStatus: ProductionStatus = tab === 'Actual' ? 'Completed' : 'In Progress';

    try {
        if (editEntry) {
            const updated = currentData.map((p: ProductionEntry) => {
                if (p.id === editEntry.id) {
                    const newQty = parseInt(quantity || '0');
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? newQty : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? newQty : p.actualQuantity,
                        batchNo, manpower: parseFloat(manpower || '0'),
                        planRemark,
                        actualRemark,
                        status: (tab === 'Actual' && newQty > 0 ? 'Completed' : p.status) as ProductionStatus,
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    } as ProductionEntry;
                }
                return p;
            });
            StorageService.saveProductionData(updated);
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, unit,
                    planQuantity: parseInt(quantity || '0'), actualQuantity: 0,
                    planRemark,
                    actualRemark: '',
                    status: 'In Progress',
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const updated = currentData.map((p: ProductionEntry) => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity || '0'), 
                            unit, batchNo, manpower: parseFloat(manpower || '0'),
                            actualRemark, status: 'Completed' as ProductionStatus,
                            lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                        } as ProductionEntry;
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: determinedStatus === 'Completed' ? 'PRODUCTION COMPLETED' : 'PLAN SAVED', type: 'success' } 
        }));
        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Operation failed', type: 'info' } }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative max-h-[90vh] flex flex-col">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-[60] flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Uploading to Cloud...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700 shrink-0">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        1. Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-50 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        2. Record Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 flex overflow-hidden">
                <button onClick={() => setTab('Plan')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600 bg-indigo-50/10' : 'border-transparent text-slate-400'}`}>
                    Plan Details
                </button>
                <button onClick={() => setTab('Actual')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Actual' ? 'border-emerald-50 text-emerald-600 bg-emerald-50/10' : 'border-transparent text-slate-400'}`}>
                    Actual Results
                </button>
              </div>
            )}
        </div>

        <div className="p-6 relative overflow-y-auto custom-scrollbar flex-1">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors z-20"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className={`mt-3 p-3 border rounded-xl flex items-center gap-3 shadow-sm ${
                        currentOffDay.type === 'Public Holiday' ? 'bg-rose-50 dark:bg-rose-900/20 border-rose-200 dark:border-rose-800' :
                        currentOffDay.type === 'Rest Day' ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-200 dark:border-indigo-800' :
                        'bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-800'
                      }`}>
                        <div className={`p-2 rounded-lg text-white ${
                            currentOffDay.type === 'Public Holiday' ? 'bg-rose-500' :
                            currentOffDay.type === 'Rest Day' ? 'bg-indigo-500' :
                            'bg-amber-500'
                        }`}>
                          <Ban className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className={`text-[10px] font-black uppercase tracking-widest leading-none mb-1 ${
                                currentOffDay.type === 'Public Holiday' ? 'text-rose-600 dark:text-rose-400' :
                                currentOffDay.type === 'Rest Day' ? 'text-indigo-600 dark:text-indigo-400' :
                                'text-amber-600 dark:text-amber-400'
                          }`}>{currentOffDay.type}</p>
                          <p className="text-xs font-black text-slate-900 dark:text-white leading-tight">{currentOffDay.description}</p>
                        </div>
                      </div>
                    )}
                </div>

                {tab === 'Plan' ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {availableProcesses.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value.toUpperCase())} className={inputClasses} placeholder="Enter product name..." />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="flex-1">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Target Plan Qty</label>
                                <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                            </div>
                            <div className="w-24">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                    {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5"><MessageSquare className="w-3 h-3" /> Plan Remark</label>
                            <textarea value={planRemark} onChange={e => setPlanRemark(e.target.value.toUpperCase())} className={`${inputClasses} h-20 resize-none font-medium text-xs`} placeholder="ADD PLANNING NOTES..." />
                        </div>
                    </>
                ) : (
                    <>
                        {!editEntry && (
                          <div className="mb-4">
                               <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Pending Job</label>
                               {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans found for this date.</div> : (
                                   <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                       {plans.map(p => (
                                           <div key={p.id} onClick={() => { setSelectedPlanId(p.id); setProductName(p.productName); setProcess(p.process); setCategory(p.category); }}
                                              className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                              <div className="font-black text-sm">{p.productName}</div>
                                              <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-emerald-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity} {p.unit || 'KG'}</div>
                                           </div>
                                       ))}
                                   </div>
                               )}
                          </div>
                        )}
                        {(selectedPlanId || editEntry) && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="flex-1">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Result Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div className="w-24">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                        <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                            {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                        </select>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                  </div>
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower Used</label>
                                    <input type="number" required step="0.01" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                  </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5"><MessageSquare className="w-3 h-3" /> Actual Remark</label>
                                    <textarea value={actualRemark} onChange={e => setActualRemark(e.target.value.toUpperCase())} className={`${inputClasses} h-20 resize-none font-medium text-xs`} placeholder="ADD ACTUAL NOTES..." />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button 
                    type="submit" 
                    disabled={isSubmitting || isLocked} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-4 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        isLocked ? 'bg-slate-400 dark:bg-slate-700' : tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600' : 'bg-emerald-600'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : isLocked ? 'Locked - Non Working Day' : (tab === 'Actual' ? 'Submit & Mark Completed' : 'Save Plan Entry')}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { ProductionEntry } from '../../types';
import { AlertCircle, CheckCircle2, Palmtree, MessageSquare } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const InputPlan: React.FC = () => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [formData, setFormData] = useState({
    date: getTodayISO(),
    category: CATEGORIES[0],
    process: PROCESSES[0],
    productName: '',
    quantity: '',
    unit: UNITS[0],
    planRemark: ''
  });
  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => offDays.find(od => od.date === formData.date), [formData.date, offDays]);

  useEffect(() => {
    if (currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `HOLIDAY ALERT: ${currentOffDay.description}`, type: 'info' } 
        }));
    }
  }, [currentOffDay]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentOffDay) {
      setMsg({ type: 'error', text: `Selected date is an Off Day: ${currentOffDay.description}.` });
      return;
    }

    if (!formData.productName || !formData.quantity) {
      setMsg({ type: 'error', text: 'Please fill all required fields.' });
      return;
    }

    try {
      const entries = StorageService.getProductionData();

      const newEntry: ProductionEntry = {
        id: Date.now().toString(),
        date: formData.date,
        category: formData.category as any,
        process: formData.process as any,
        productName: formData.productName,
        planQuantity: parseInt(formData.quantity),
        actualQuantity: 0,
        unit: formData.unit as any,
        planRemark: formData.planRemark,
        status: 'In Progress',
        lastUpdatedBy: user!.id,
        updatedAt: new Date().toISOString()
      };

      StorageService.saveProductionData([...entries, newEntry]);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'CREATE_PLAN',
        details: `Planned ${newEntry.planQuantity} ${newEntry.unit} for ${newEntry.productName} on ${newEntry.date}`
      });

      triggerRefresh();
      setMsg({ type: 'success', text: 'Plan entry added successfully.' });
      setFormData(prev => ({ ...prev, productName: '', quantity: '', planRemark: '' }));

      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'PRODUCTION PLAN SUBMITTED', type: 'success' } 
      }));
    } catch (err) {
      setMsg({ type: 'error', text: 'Failed to save data.' });
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 p-8">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Input Production Plan</h2>

        {msg && (
          <div className={`p-4 rounded-lg mb-6 flex items-center ${msg.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
            {msg.type === 'success' ? <CheckCircle2 className="w-5 h-5 mr-2" /> : <AlertCircle className="w-5 h-5 mr-2" />}
            {msg.text}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date</label>
              <input 
                type="date" 
                required
                className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                value={formData.date}
                onChange={e => setFormData({...formData, date: e.target.value})}
              />

              {currentOffDay && (
                <div className="mt-3 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-xl flex items-center gap-3">
                  <Palmtree className="w-5 h-5 text-amber-500 shrink-0" />
                  <div className="flex-1">
                    <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none mb-1">Public Holiday</p>
                    <p className="text-xs font-bold text-slate-700 dark:text-amber-100">{currentOffDay.description}</p>
                  </div>
                </div>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Category</label>
              <select 
                className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                value={formData.category}
                onChange={e => setFormData({...formData, category: e.target.value as any})}
              >
                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Process</label>
              <select 
                className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                value={formData.process}
                onChange={e => setFormData({...formData, process: e.target.value as any})}
              >
                {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Plan Quantity</label>
              <div className="flex gap-2">
                <input 
                  type="number" 
                  min="1"
                  required
                  className="flex-1 px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                  value={formData.quantity}
                  onChange={e => setFormData({...formData, quantity: e.target.value})}
                />
                <select 
                  className="w-24 px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                  value={formData.unit}
                  onChange={e => setFormData({...formData, unit: e.target.value as any})}
                >
                  {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Product Name</label>
            <input 
              type="text" 
              required
              placeholder="e.g. PAIN RELIEF GEL 50G"
              className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
              value={formData.productName}
              onChange={e => setFormData({...formData, productName: e.target.value.toUpperCase()})}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1 flex items-center gap-2">
              <MessageSquare className="w-4 h-4 text-slate-400" /> Plan Remark
            </label>
            <textarea 
              placeholder="Planning notes, requirements or urgency..."
              className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white h-24 resize-none"
              value={formData.planRemark}
              onChange={e => setFormData({...formData, planRemark: e.target.value.toUpperCase()})}
            />
          </div>

          <div className="pt-4">
            <button 
              type="submit"
              disabled={!!currentOffDay}
              className="w-full bg-brand-600 text-white font-semibold py-2.5 rounded-lg hover:bg-brand-700 transition-colors shadow-sm disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              {currentOffDay ? 'Off Day - Entry Locked' : 'Submit Plan'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, ProductionStatus } from '../../types';
import { Download, Filter, XCircle, Palmtree, MessageSquare, ArrowUpDown, Clock, CheckCircle, Coffee, Ban } from 'lucide-react';
import { getTodayISO, getWeeklyOffDayType } from '../../utils/dateUtils';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const ProductionLog: React.FC = () => {
  const { refreshKey } = useDashboard();
  const [data, setData] = useState<ProductionEntry[]>([]);
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);
  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');
  const [statusFilter, setStatusFilter] = useState('All');

  useEffect(() => {
    setData(StorageService.getProductionData());
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const filteredData = useMemo(() => {
    let result = data.filter(d => {
      if (!d) return false;
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStatus = statusFilter === 'All' || d.status === statusFilter;
      const matchStart = !dateRange.start || (d.date && d.date >= dateRange.start);
      const matchEnd = !dateRange.end || (d.date && d.date <= dateRange.end);
      return matchCat && matchProc && matchStatus && matchStart && matchEnd;
    });

    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    if (sortConfig) {
        result = [...result].sort((a, b) => {
            let aVal: any = a[sortConfig.key];
            let bVal: any = b[sortConfig.key];
            if (sortConfig.key === 'status') {
                aVal = statusWeight[a.status as ProductionStatus] || 0;
                bVal = statusWeight[b.status as ProductionStatus] || 0;
            } else {
                aVal = (aVal || '').toString();
                bVal = (bVal || '').toString();
            }
            if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
    } else {
        result.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    }

    return result;
  }, [data, dateRange, category, processType, statusFilter, sortConfig]);

  const calculateEfficiency = (actual: number, plan: number) => plan > 0 ? ((actual / plan) * 100).toFixed(1) : '0';

  const resetFilters = () => {
    setDateRange({ start: '', end: '' });
    setCategory('All');
    setProcessType('All');
    setStatusFilter('All');
    setSortConfig(null);
  };

  const downloadCSV = () => {
    const headers = ["Date", "Category", "Process", "Product", "Plan", "Actual", "Unit", "Efficiency %", "Batch No", "Manpower", "Status", "Plan Remark", "Actual Remark"];
    const rows = filteredData.map(d => [
        d.date, d.category, d.process, `"${d.productName}"`, d.planQuantity || 0, d.actualQuantity || 0, d.unit || 'KG',
        calculateEfficiency(d.actualQuantity || 0, d.planQuantity || 0), d.batchNo || '', (d.manpower || 0).toFixed(2), d.status || 'In Progress', 
        `"${(d.planRemark || '').replace(/"/g, '""')}"`, `"${(d.actualRemark || '').replace(/"/g, '""')}"`
    ]);
    const filename = `production_log_${getTodayISO()}.csv`;

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } 
    }));
  };

  const SortHeader = ({ label, sortKey, align = 'left' }: { label: string, sortKey: keyof ProductionEntry, align?: 'left' | 'right' | 'center' }) => (
    <th className={`px-8 py-5 cursor-pointer group text-${align}`} onClick={() => handleSort(sortKey)}>
        <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : ''}`}>
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-800 dark:text-white">Production Log</h2>
          <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Detailed operational history</p>
        </div>

        <button 
          onClick={downloadCSV} 
          className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-emerald-700 transition shadow-lg shadow-emerald-500/20"
        >
          <Download className="w-4 h-4" /> Export Report
        </button>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-slate-700 flex flex-wrap gap-6 items-end">
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Date From</label>
          <input type="date" value={dateRange.start} onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold" />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Date To</label>
          <input type="date" value={dateRange.end} onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold" />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Department</label>
          <select value={category} onChange={e => setCategory(e.target.value)} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold w-full md:w-auto">
            <option value="All">All Departments</option>
            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Process Stage</label>
          <select value={processType} onChange={e => setProcessType(e.target.value)} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold w-full md:w-auto">
            <option value="All">All Processes</option>
            {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Status</label>
          <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold w-full md:w-auto">
            <option value="All">All Statuses</option>
            <option value="In Progress">In Progress</option>
            <option value="Completed">Completed</option>
          </select>
        </div>
        <button onClick={resetFilters} className="flex items-center gap-1.5 px-4 py-2.5 text-[10px] font-black uppercase text-rose-500 hover:bg-rose-50 rounded-xl transition"><XCircle className="w-4 h-4" /> Reset</button>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-sm text-left border-collapse">
            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-slate-400 font-black uppercase text-[10px] tracking-widest border-b dark:border-slate-700">
                <tr>
                    <SortHeader label="Date / Status" sortKey="date" />
                    <SortHeader label="Dept" sortKey="category" align="center" />
                    <SortHeader label="Product" sortKey="productName" />
                    <th className="px-8 py-5 text-right font-black uppercase text-[10px] tracking-widest">Plan Data</th>
                    <th className="px-8 py-5 text-right font-black uppercase text-[10px] tracking-widest">Actual Data</th>
                    <th className="px-8 py-5 text-center font-black uppercase text-[10px] tracking-widest">Unit</th>
                    <th className="px-8 py-5 text-right font-black uppercase text-[10px] tracking-widest">Eff. %</th>
                    <SortHeader label="Batch No" sortKey="batchNo" align="center" />
                </tr>
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-slate-700/50">
                {filteredData.map(entry => {
                const eff = Number(calculateEfficiency(entry.actualQuantity || 0, entry.planQuantity || 0));
                const manualOffDay = offDays.find(od => od.date === entry.date);
                const autoOffType = getWeeklyOffDayType(entry.date || '');
                const labelType = manualOffDay?.type || autoOffType;
                const labelDesc = manualOffDay?.description || (autoOffType === 'Rest Day' ? 'Weekly Rest' : 'Weekly Off');

                return (
                    <tr key={entry.id} className={`hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition-colors ${labelType ? 'bg-amber-50/10' : ''}`}>
                    <td className="px-8 py-6">
                        <div className="font-black text-slate-800 dark:text-white font-mono text-xs mb-1.5">{entry.date}</div>
                        {labelType ? (
                            <span className={`flex items-center gap-1.5 text-[9px] font-black uppercase ${
                            labelType === 'Public Holiday' ? 'text-rose-500' : 
                            labelType === 'Rest Day' ? 'text-indigo-500' : 'text-amber-500'
                            }`}>
                            {labelType === 'Public Holiday' ? <Palmtree className="w-3 h-3" /> : 
                                labelType === 'Rest Day' ? <Coffee className="w-3 h-3" /> : <Ban className="w-3 h-3" />}
                            {labelDesc}
                            </span>
                        ) : (
                            <div className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[8px] font-black uppercase border ${entry.status === 'Completed' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-indigo-50 text-indigo-600 border-indigo-100'}`}>
                                {entry.status === 'Completed' ? <CheckCircle className="w-2.5 h-2.5" /> : <Clock className="w-2.5 h-2.5 animate-pulse" />} 
                                {entry.status}
                            </div>
                        )}
                    </td>
                    <td className="px-8 py-6 text-center">
                        <span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-900 text-slate-500 border dark:border-slate-800">{entry.category}</span>
                    </td>
                    <td className="px-8 py-6">
                        <div className="font-black text-slate-800 dark:text-white leading-tight mb-1">{entry.productName}</div>
                        <div className="text-[9px] font-black text-indigo-500 dark:text-indigo-400 uppercase tracking-widest">{entry.process}</div>
                    </td>
                    <td className="px-8 py-6 text-right font-black font-mono text-slate-700 dark:text-slate-200">
                        <div>{(entry.planQuantity || 0).toLocaleString()}</div>
                        {entry.planRemark && (
                            <div className="flex items-center justify-end gap-1 mt-1 opacity-60">
                            <MessageSquare className="w-2.5 h-2.5 text-indigo-500" />
                            <span className="text-[9px] font-medium italic truncate max-w-[120px]">{entry.planRemark}</span>
                            </div>
                        )}
                    </td>
                    <td className="px-8 py-6 text-right font-black font-mono text-emerald-500">
                        <div>{(entry.actualQuantity || 0).toLocaleString()}</div>
                        {entry.actualRemark && (
                            <div className="flex items-center justify-end gap-1 mt-1 opacity-60">
                            <MessageSquare className="w-2.5 h-2.5 text-emerald-500" />
                            <span className="text-[9px] font-medium italic truncate max-w-[120px]">{entry.actualRemark}</span>
                            </div>
                        )}
                    </td>
                    <td className="px-8 py-6 text-center">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{entry.unit || 'KG'}</span>
                    </td>
                    <td className="px-8 py-6 text-right font-black">
                        <span className={`${eff >= 90 ? 'text-emerald-500' : eff >= 70 ? 'text-amber-500' : 'text-rose-500'}`}>{eff}%</span>
                    </td>
                    <td className="px-8 py-6 text-center">
                        <span className="text-[11px] font-black text-slate-600 dark:text-slate-300 font-mono uppercase">
                            {entry.batchNo || '---'}
                        </span>
                    </td>
                    </tr>
                );
                })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { ProductionEntry, Category, ProcessType, UnitType } from '../../types';
import { AlertCircle, CheckCircle2, Palmtree, MessageSquare } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const InputPlan: React.FC = () => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [formData, setFormData] = useState({
    date: getTodayISO(),
    category: CATEGORIES[0],
    process: PROCESSES[0],
    productName: '',
    quantity: '',
    unit: UNITS[0],
    planRemark: ''
  });
  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => offDays.find(od => od.date === formData.date), [formData.date, offDays]);

  useEffect(() => {
    if (currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `HOLIDAY ALERT: ${currentOffDay.description}`, type: 'info' } 
        }));
    }
  }, [currentOffDay]);

  const availableProcesses = useMemo(() => {
    if (formData.category === 'Healthcare') return [...PROCESSES];
    return PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));
  }, [formData.category]);

  useEffect(() => {
    if (!availableProcesses.includes(formData.process)) {
      setFormData(prev => ({ ...prev, process: availableProcesses[0] }));
    }
  }, [availableProcesses, formData.process]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentOffDay) {
      setMsg({ type: 'error', text: `Selected date is an Off Day: ${currentOffDay.description}.` });
      return;
    }

    if (!formData.productName || !formData.quantity) {
      setMsg({ type: 'error', text: 'Please fill all required fields.' });
      return;
    }

    try {
      const entries = StorageService.getProductionData();

      const newEntry: ProductionEntry = {
        id: Date.now().toString(),
        date: formData.date,
        category: formData.category as Category,
        process: formData.process as ProcessType,
        productName: formData.productName,
        planQuantity: parseInt(formData.quantity),
        actualQuantity: 0,
        unit: formData.unit as UnitType,
        planRemark: formData.planRemark,
        status: 'In Progress',
        lastUpdatedBy: user!.id,
        updatedAt: new Date().toISOString()
      };

      StorageService.saveProductionData([...entries, newEntry]);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'CREATE_PLAN',
        details: `Planned ${newEntry.planQuantity} ${newEntry.unit} for ${newEntry.productName} on ${newEntry.date}`
      });

      triggerRefresh();
      setMsg({ type: 'success', text: 'Plan entry added successfully.' });
      setFormData(prev => ({ ...prev, productName: '', quantity: '', planRemark: '' }));

      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'PRODUCTION PLAN SUBMITTED', type: 'success' } 
      }));
    } catch (err) {
      setMsg({ type: 'error', text: 'Failed to save data.' });
    }
  };

  return (
    <div className="max-w-2xl mx-auto py-8">
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-gray-100 dark:border-slate-700 p-10 animate-in fade-in slide-in-from-bottom-4">
        <div className="flex items-center gap-4 mb-8">
          <div className="p-3 bg-indigo-100 dark:bg-indigo-900/40 rounded-2xl">
            <MessageSquare className="w-8 h-8 text-indigo-600 dark:text-indigo-400" />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-800 dark:text-white">New Production Plan</h2>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Initialize production targets</p>
          </div>
        </div>

        {msg && (
          <div className={`p-5 rounded-2xl mb-8 flex items-center gap-4 animate-pulse ${msg.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-rose-50 text-rose-700 border border-rose-100'}`}>
            {msg.type === 'success' ? <CheckCircle2 className="w-6 h-6" /> : <AlertCircle className="w-6 h-6" />}
            <span className="font-bold text-sm uppercase tracking-tight">{msg.text}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Production Date</label>
              <input 
                type="date" 
                required
                className="w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-indigo-500/20"
                value={formData.date}
                onChange={e => setFormData({...formData, date: e.target.value})}
              />

              {currentOffDay && (
                <div className="mt-4 p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-2xl flex items-center gap-4">
                  <Palmtree className="w-6 h-6 text-amber-500 shrink-0" />
                  <div className="flex-1">
                    <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none mb-1">Non-Working Day</p>
                    <p className="text-xs font-black text-slate-800 dark:text-amber-100">{currentOffDay.description}</p>
                  </div>
                </div>
              )}
            </div>

            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Department</label>
              <select 
                className="w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-indigo-500/20"
                value={formData.category}
                onChange={e => setFormData({...formData, category: e.target.value as Category})}
              >
                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Process Node</label>
              <select 
                className="w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-indigo-500/20"
                value={formData.process}
                onChange={e => setFormData({...formData, process: e.target.value as ProcessType})}
              >
                {availableProcesses.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>

            <div className="space-y-2">
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Planned Quantity</label>
              <div className="flex gap-2">
                <input 
                  type="number" 
                  min="1"
                  required
                  placeholder="0"
                  className="flex-1 p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-indigo-500/20"
                  value={formData.quantity}
                  onChange={e => setFormData({...formData, quantity: e.target.value})}
                />
                <select 
                  className="w-24 p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none"
                  value={formData.unit}
                  onChange={e => setFormData({...formData, unit: e.target.value as UnitType})}
                >
                  {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Product Description</label>
            <input 
              type="text" 
              required
              placeholder="E.G. TOOTHPASTE HERBAL 150G"
              className="w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-indigo-500/20"
              value={formData.productName}
              onChange={e => setFormData({...formData, productName: e.target.value.toUpperCase()})}
            />
          </div>

          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Planning Remark</label>
            <textarea 
              placeholder="OPTIONAL PLANNING NOTES..."
              className="w-full p-4 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white h-32 resize-none font-bold outline-none focus:ring-2 focus:ring-indigo-500/20"
              value={formData.planRemark}
              onChange={e => setFormData({...formData, planRemark: e.target.value.toUpperCase()})}
            />
          </div>

          <div className="pt-6">
            <button 
              type="submit"
              disabled={!!currentOffDay}
              className="w-full bg-slate-900 dark:bg-indigo-600 text-white font-black py-4 rounded-2xl hover:opacity-90 transition-all shadow-xl shadow-indigo-500/10 disabled:bg-slate-300 disabled:cursor-not-allowed uppercase tracking-[0.2em] text-sm"
            >
              {currentOffDay ? 'Locked - Non Working Day' : 'Secure Plan Entry'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { ProductionEntry } from '../../types';
import { AlertCircle, CheckCircle2, Palmtree, ClipboardCheck, Users } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const InputActual: React.FC = () => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [date, setDate] = useState(getTodayISO());

  const [pendingPlans, setPendingPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const [formData, setFormData] = useState({
    actualQty: '',
    manpower: '0.00',
    batchNo: '',
    actualRemark: ''
  });

  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => offDays.find(od => od.date === date), [date, offDays]);

  useEffect(() => {
    const all = StorageService.getProductionData();
    const forDate = all.filter(p => p.date === date);
    setPendingPlans(forDate);
    setSelectedPlanId('');
    setFormData({ actualQty: '', manpower: '0.00', batchNo: '', actualRemark: '' });
  }, [date]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentOffDay) {
      setMsg({ type: 'error', text: 'Operation restricted on non-working days.' });
      return;
    }

    if (!selectedPlanId) {
      setMsg({ type: 'error', text: 'Please select a job node to update.' });
      return;
    }

    try {
      const allData = StorageService.getProductionData();
      const updatedData = allData.map(entry => {
        if (entry.id === selectedPlanId) {
          return {
            ...entry,
            actualQuantity: parseInt(formData.actualQty || '0'),
            manpower: parseFloat(formData.manpower || '0'),
            batchNo: formData.batchNo,
            actualRemark: formData.actualRemark,
            status: 'Completed' as const,
            lastUpdatedBy: user!.id,
            updatedAt: new Date().toISOString()
          };
        }
        return entry;
      });

      StorageService.saveProductionData(updatedData);

      const target = allData.find(e => e.id === selectedPlanId);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'RECORD_ACTUAL',
        details: `Recorded output for ${target?.productName}: ${formData.actualQty} units with ${parseFloat(formData.manpower).toFixed(2)} manpower`
      });

      triggerRefresh();
      setMsg({ type: 'success', text: 'Production record updated and synchronized.' });

      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'ACTUAL PRODUCTION SYNCHRONIZED', type: 'success' } 
      }));

      // Refresh pending list
      setPendingPlans(updatedData.filter(p => p.date === date));
    } catch (err) {
      setMsg({ type: 'error', text: 'Error communicating with storage.' });
    }
  };

  const inputClasses = "w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-emerald-500/20";

  return (
    <div className="max-w-2xl mx-auto py-8">
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-gray-100 dark:border-slate-700 p-10 animate-in fade-in slide-in-from-bottom-4">
        <div className="flex items-center gap-4 mb-8">
          <div className="p-3 bg-emerald-100 dark:bg-emerald-900/40 rounded-2xl">
            <ClipboardCheck className="w-8 h-8 text-emerald-600 dark:text-emerald-400" />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-800 dark:text-white">Record Production</h2>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Verify floor output and resources</p>
          </div>
        </div>

        {msg && (
          <div className={`p-5 rounded-2xl mb-8 flex items-center gap-4 animate-pulse ${msg.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-rose-50 text-rose-700 border border-rose-100'}`}>
            {msg.type === 'success' ? <CheckCircle2 className="w-6 h-6" /> : <AlertCircle className="w-6 h-6" />}
            <span className="font-bold text-sm uppercase tracking-tight">{msg.text}</span>
          </div>
        )}

        <div className="mb-8">
          <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Review Date</label>
          <input 
            type="date" 
            className={inputClasses}
            value={date}
            onChange={e => setDate(e.target.value)}
          />

          {currentOffDay && (
            <div className="mt-4 p-5 bg-amber-50 dark:bg-amber-900/30 border border-amber-300 dark:border-amber-700 rounded-2xl flex items-center gap-4">
              <Palmtree className="w-8 h-8 text-amber-500 shrink-0" />
              <div>
                <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none mb-1">System Locked</p>
                <p className="text-sm font-black text-slate-900 dark:text-amber-50">Public Holiday: {currentOffDay.description}</p>
              </div>
            </div>
          )}
        </div>

        {!currentOffDay && (
          <>
            <div className="mb-8">
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Select Pending Job Node</label>
              {pendingPlans.length === 0 ? (
                <div className="text-sm text-slate-400 font-bold italic p-8 border-2 border-dashed border-slate-100 dark:border-slate-700 rounded-2xl text-center">
                  No active plans found for this date.
                </div>
              ) : (
                <div className="space-y-3 max-h-60 overflow-y-auto custom-scrollbar border border-slate-100 dark:border-slate-700 rounded-2xl p-3 bg-slate-50/50 dark:bg-slate-900/50">
                  {pendingPlans.map(plan => (
                    <div 
                      key={plan.id}
                      onClick={() => {
                        setSelectedPlanId(plan.id);
                        setFormData(prev => ({ 
                          ...prev, 
                          actualQty: plan.actualQuantity ? plan.actualQuantity.toString() : '',
                          manpower: plan.manpower ? plan.manpower.toFixed(2) : '0.00',
                          batchNo: plan.batchNo || '',
                          actualRemark: plan.actualRemark || ''
                        }));
                      }}
                      className={`p-4 rounded-xl cursor-pointer border-2 transition-all ${
                        selectedPlanId === plan.id 
                          ? 'bg-emerald-50 border-emerald-500 shadow-md ring-4 ring-emerald-500/10 dark:bg-emerald-900/20' 
                          : 'bg-white dark:bg-slate-800 border-transparent hover:border-slate-200 dark:hover:border-slate-600'
                      }`}
                    >
                      <div className="flex justify-between items-center mb-1">
                        <span className="font-black text-slate-800 dark:text-white uppercase tracking-tight">{plan.productName}</span>
                        <span className="text-[9px] font-black uppercase px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400">{plan.category}</span>
                      </div>
                      <div className="flex justify-between items-end">
                        <span className="text-[10px] font-bold text-indigo-500 dark:text-indigo-400 uppercase tracking-widest">{plan.process}</span>
                        <div className="text-[11px] font-black text-slate-400 uppercase">Target: <span className="text-slate-800 dark:text-white">{plan.planQuantity} {plan.unit}</span></div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {selectedPlanId && (
              <form onSubmit={handleSubmit} className="space-y-6 animate-in slide-in-from-top-4 duration-300">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Actual Yield Qty</label>
                    <input 
                      type="number" 
                      min="0"
                      required
                      className={inputClasses.replace('font-bold', 'font-black')}
                      value={formData.actualQty}
                      onChange={e => setFormData({...formData, actualQty: e.target.value})}
                    />
                  </div>

                  <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1 flex items-center gap-1.5">
                      <Users className="w-3 h-3" /> Manpower (2 Decimals)
                    </label>
                    <input 
                      type="number" 
                      step="0.01"
                      min="0"
                      required
                      className={inputClasses}
                      value={formData.manpower}
                      onBlur={() => setFormData(prev => ({...prev, manpower: parseFloat(prev.manpower || '0').toFixed(2)}))}
                      onChange={e => setFormData({...formData, manpower: e.target.value})}
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Official Batch Number</label>
                  <input 
                    type="text" 
                    required
                    placeholder="ENTER LOT / BATCH ID..."
                    className={inputClasses.replace('font-bold', 'font-black font-mono')}
                    value={formData.batchNo}
                    onChange={e => setFormData({...formData, batchNo: e.target.value.toUpperCase()})}
                  />
                </div>

                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Actual Result Remark</label>
                  <textarea 
                    placeholder="ENTER DISCREPANCIES OR FLOOR NOTES..."
                    className="w-full p-4 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white h-32 resize-none font-bold outline-none focus:ring-2 focus:ring-emerald-500/20"
                    value={formData.actualRemark}
                    onChange={e => setFormData({...formData, actualRemark: e.target.value.toUpperCase()})}
                  />
                </div>

                <button 
                  type="submit"
                  className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:opacity-90 transition-all shadow-xl shadow-emerald-500/20 uppercase tracking-[0.2em] text-sm"
                >
                  Verify & Synchronize Record
                </button>
              </form>
            )}
          </>
        )}
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay, ProductionStatus, OffDayType } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, List, Calendar, 
  Download, Pencil, Trash2, Layers,
  Palmtree, MessageSquare, ArrowUpDown, Coffee, Ban
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO, getWeeklyOffDayType } from '../../utils/dateUtils';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;
    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    const validProcesses = category === 'Healthcare' 
      ? [...PROCESSES] 
      : PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    validProcesses.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);
        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const dates = new Set<string>();

    filteredEntries.forEach(e => {
        if (e.date) dates.add(e.date.trim().substring(0, 10));
    });

    offDays.forEach(od => {
        if (od.date && od.date.trim().startsWith(selectedMonth)) {
            dates.add(od.date.trim().substring(0, 10));
        }
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));
    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    return sortedDates.map(dateKey => {
        let entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);

        if (sortConfig) {
            entriesForDate = [...entriesForDate].sort((a, b) => {
                let aValue: any = a[sortConfig.key];
                let bValue: any = b[sortConfig.key];
                if (sortConfig.key === 'status') {
                    aValue = statusWeight[a.status as ProductionStatus] || 0;
                    bValue = statusWeight[b.status as ProductionStatus] || 0;
                }
                if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });
        }

        let offDayInfo = offDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);

        if (!offDayInfo) {
           const autoType = getWeeklyOffDayType(dateKey);
           if (autoType) {
               offDayInfo = {
                   id: `auto-${dateKey}`,
                   date: dateKey,
                   type: autoType,
                   description: autoType === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off',
                   createdBy: 'System'
               };
           }
        }

        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            offDay: offDayInfo
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth, sortConfig]);

  const handleDelete = (id: string) => {
      if(!window.confirm("PERMANENTLY delete record?")) return;
      const { deletedItem } = StorageService.deleteProductionEntry(id);
      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id, userName: user!.name, action: 'DELETE_RECORD',
            details: `Deleted: ${deletedItem.productName} (${deletedItem.date})`
          });
          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED', type: 'info' } 
          }));
      }
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const getOffDayIcon = (type: string) => {
    switch(type) {
      case 'Public Holiday': return <Palmtree className="w-6 h-6 text-rose-500" />;
      case 'Rest Day': return <Coffee className="w-6 h-6 text-indigo-500" />;
      case 'Off Day': return <Ban className="w-6 h-6 text-amber-500" />;
      default: return <Calendar className="w-6 h-6 text-slate-400" />;
    }
  };

  const getOffDayBadgeStyle = (type: string) => {
    switch(type) {
      case 'Public Holiday': return 'bg-rose-500 text-white shadow-rose-500/20';
      case 'Rest Day': return 'bg-indigo-500 text-white shadow-indigo-500/20';
      case 'Off Day': return 'bg-amber-500 text-white shadow-amber-500/20';
      default: return 'bg-slate-400 text-white';
    }
  };

  const SortHeader = ({ label, sortKey }: { label: string, sortKey: keyof ProductionEntry }) => (
    <th className="px-8 py-4 cursor-pointer group" onClick={() => handleSort(sortKey)}>
        <div className="flex items-center gap-1">
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-8 pb-12">
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
            <Layers className="w-4 h-4 text-indigo-500" />
            <h3 className="text-[12px] font-black text-slate-400 uppercase tracking-[0.3em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-800 shadow-sm group hover:border-indigo-500/30 transition-all duration-300">
                        <div className="flex items-center justify-between mb-6">
                          <p className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{item.process}</p>
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse" />
                        </div>
                        <div className="space-y-5">
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Plan</span>
                                <span className="text-2xl font-black text-slate-800 dark:text-white font-mono">{(item.Plan || 0).toLocaleString()}</span>
                            </div>
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Actual</span>
                                <span className="text-2xl font-black text-emerald-500 font-mono">{(item.Actual || 0).toLocaleString()}</span>
                            </div>
                            <div className="pt-5 border-t border-gray-50 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Efficiency</span>
                                <span className={`text-xl font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(1)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">{selectedMonth} Operational granularity</p>
            </div>
            <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none" />
        </div>

        <div className="space-y-6">
            {dailyGroups.length === 0 ? (
                <div className="p-20 text-center glass-panel rounded-[2rem]">
                    <div className="inline-flex p-4 rounded-full bg-slate-50 dark:bg-slate-800 mb-4">
                        <ClipboardList className="w-10 h-10 text-slate-300" />
                    </div>
                    <p className="text-sm font-black text-slate-400 uppercase tracking-widest">No scheduled data for this month</p>
                </div>
            ) : dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');
                const isOff = !!group.offDay;

                const allCompleted = group.entries.length > 0 && group.entries.every(e => e.status === 'Completed');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-slate-850 rounded-[2rem] overflow-hidden shadow-sm border ${
                    isOff ? (
                        group.offDay?.type === 'Public Holiday' ? 'border-rose-400/30' :
                        group.offDay?.type === 'Rest Day' ? 'border-indigo-400/30' :
                        'border-amber-400/30'
                    ) : 'border-gray-100 dark:border-slate-800'
                  }`}>
                      <div className={`p-6 flex justify-between items-center border-b ${
                        isOff ? (
                            group.offDay?.type === 'Public Holiday' ? 'bg-rose-50/30 dark:bg-rose-900/10' :
                            group.offDay?.type === 'Rest Day' ? 'bg-indigo-50/30 dark:bg-indigo-900/10' :
                            'bg-amber-50/30 dark:bg-amber-900/10'
                        ) : 'bg-gray-50/50 dark:bg-slate-800/50'
                      }`}>
                          <div className="flex items-center gap-4">
                              {getOffDayIcon(group.offDay?.type || '')}
                              <div className="flex items-center gap-3">
                                <span className={`text-xl font-black text-slate-800 dark:text-white`}>{datePart}</span>
                                <span className="text-xl font-medium uppercase tracking-tight text-slate-400">{dayPart}</span>
                              </div>
