                  <p className="text-sm font-black text-slate-800 dark:text-white leading-none uppercase tracking-tighter">{user.name}</p>
                  <p className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.2em] mt-1">{user.role}</p>
