                <div className="relative group">
                    <button onClick={() => setShowAvatar(true)} className="w-12 h-12 rounded-2xl bg-indigo-50 dark:bg-slate-800 border-2 border-white dark:border-slate-700 overflow-hidden shadow-lg group-hover:border-indigo-500 transition-all">
                        {user.avatar ? (
