                    <div className="absolute top-full right-0 mt-3 w-48 py-2 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-gray-100 dark:border-slate-700 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all translate-y-2 group-hover:translate-y-0 z-50">
                        <button onClick={() => setShowPassword(true)} className="w-full px-5 py-3 text-left text-xs font-black text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-3 uppercase tracking-widest">
