              <button onClick={() => setShowLogin(true)} className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-indigo-500/20 hover:opacity-90 transition-all active:scale-95">
                <LogIn className="w-4 h-4" /> Sign In
              </button>
