      {/* Notifications */}
      {notification && (
        <div className="fixed bottom-8 right-8 z-[100] notification-animate">
            <div className={`px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 border border-white/20 backdrop-blur-xl ${notification.type === 'success' ? 'bg-emerald-500 text-white' : 'bg-indigo-600 text-white'}`}>
