import React, { ReactNode, useState, useEffect, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { Category } from '../../types';
import { CATEGORIES } from '../../constants';
import { LoginModal } from '../modals/LoginModal';
import { InputModal } from '../modals/InputModal';
import { OffDayModal } from '../modals/OffDayModal';
import { ChangePasswordModal } from '../modals/ChangePasswordModal';
import { AvatarModal } from '../modals/AvatarModal';
import { Link, useLocation } from 'react-router-dom';
import { 
  Menu, X, Moon, Sun, Plus, LogOut, Database,
  CalendarX, LayoutDashboard, RefreshCw, LogIn, 
  ClipboardList, History, Key, BarChart3, UserCircle,
  Calendar
} from 'lucide-react';

export const Layout: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user, logout, hasPermission } = useAuth();
  const { category, setCategory, isDarkMode, toggleDarkMode, triggerRefresh } = useDashboard();
  const location = useLocation();

  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [showInput, setShowInput] = useState(false);
  const [showOffDay, setShowOffDay] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showAvatar, setShowAvatar] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'info'} | null>(null);

  useEffect(() => {
    const handleNotify = (e: any) => {
        setNotification(e.detail);
        setTimeout(() => setNotification(null), 3000);
    };
    const handleEdit = () => setShowInput(true);

    window.addEventListener('app-notification', handleNotify);
    window.addEventListener('edit-production-entry', handleEdit);
    return () => {
        window.removeEventListener('app-notification', handleNotify);
        window.removeEventListener('edit-production-entry', handleEdit);
    };
  }, []);

  const handleSync = async () => {
    setIsSyncing(true);
    try {
      // Simulation of sync
      await new Promise(r => setTimeout(r, 800));
      triggerRefresh();
      window.dispatchEvent(new CustomEvent('app-notification', { 
          detail: { message: 'DATABASE SYNCHRONIZED', type: 'success' } 
      }));
    } finally {
      setIsSyncing(false);
    }
  };

  const navItems = [
    { label: 'Dashboard', icon: LayoutDashboard, path: '/', roles: ['admin', 'manager', 'hod', 'planner', 'operator'] },
    { label: 'Production Plan', icon: Calendar, path: '/calendar', roles: ['admin', 'manager', 'hod', 'planner', 'operator'] },
    { label: 'Input Plan', icon: Plus, path: '/plan', roles: ['admin', 'manager', 'planner'] },
    { label: 'Record Actual', icon: RefreshCw, path: '/actual', roles: ['admin', 'manager', 'operator'] },
    { label: 'Analytics', icon: BarChart3, path: '/process-analytics', roles: ['admin', 'manager', 'hod'] },
    { label: 'History Log', icon: ClipboardList, path: '/reports', roles: ['admin', 'manager', 'hod', 'planner', 'operator'] },
    { label: 'Audit Trail', icon: History, path: '/logs', roles: ['admin', 'manager', 'hod'] },
    { label: 'User Admin', icon: Database, path: '/users', roles: ['admin'] },
  ];

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-gray-50 dark:bg-slate-900 transition-colors duration-300">
      {/* Mobile Header */}
      <header className="lg:hidden flex items-center justify-between p-4 bg-white dark:bg-slate-800 border-b dark:border-slate-700 sticky top-0 z-40 shadow-sm">
        <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
                <Database className="w-6 h-6 text-white" />
            </div>
            <span className="font-black text-xl tracking-tighter dark:text-white uppercase">HALAGEL</span>
        </div>
        <button onClick={() => setSidebarOpen(true)} className="p-2 text-slate-600 dark:text-slate-300">
          <Menu className="w-6 h-6" />
        </button>
      </header>

      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 lg:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 w-80 bg-white dark:bg-slate-850 border-r border-gray-100 dark:border-slate-800 z-50 transition-transform duration-300 transform flex flex-col ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-500/20">
                <Database className="w-7 h-7 text-white" />
            </div>
            <div>
              <h1 className="font-black text-2xl tracking-tighter text-slate-800 dark:text-white leading-none uppercase">HALAGEL</h1>
              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mt-1 block">Production v2.0</span>
            </div>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2 text-slate-400">
            <X className="w-6 h-6" />
