import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { 
  Calendar as CalendarIcon, 
  ChevronLeft, 
  ChevronRight, 
  Palmtree,
  Coffee,
  Ban,
  Clock,
  CheckCircle2,
  Plus
} from 'lucide-react';
import { formatDisplayDate, getTodayISO, getWeeklyOffDayType } from '../../utils/dateUtils';

export const ProductionCalendar: React.FC = () => {
  const { category, refreshKey } = useDashboard();
  const [viewType, setViewType] = useState<'month' | 'week'>('month');
  const [baseDate, setBaseDate] = useState(getTodayISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  // Generate date range based on viewType
  const datesInRange = useMemo(() => {
    const dates = [];
    const curr = new Date(baseDate);

    if (viewType === 'month') {
      const year = curr.getFullYear();
      const month = curr.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);

      for (let d = new Date(firstDay); d <= lastDay; d.setDate(d.getDate() + 1)) {
        dates.push(new Date(d).toISOString().split('T')[0]);
      }
    } else {
      // Get current week (starting Sunday)
      const day = curr.getDay();
      const diff = curr.getDate() - day;
      const startOfWeek = new Date(curr.setDate(diff));

      for (let i = 0; i < 7; i++) {
        const d = new Date(startOfWeek);
        d.setDate(d.getDate() + i);
        dates.push(d.toISOString().split('T')[0]);
      }
    }
    return dates;
  }, [baseDate, viewType]);

  const filteredProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];
    return PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));
  }, [category]);

  const navigateDate = (direction: number) => {
    const d = new Date(baseDate);
    if (viewType === 'month') {
      d.setMonth(d.getMonth() + direction);
    } else {
      d.setDate(d.getDate() + (direction * 7));
    }
    setBaseDate(d.toISOString().split('T')[0]);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header & Controls */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-2 uppercase tracking-tight">
            <CalendarIcon className="w-7 h-7 text-indigo-600" />
            Production Plan
          </h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
            Visual Schedule • {category} Department
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="bg-white dark:bg-slate-800 p-1 rounded-xl border border-slate-200 dark:border-slate-700 flex shadow-sm">
            <button 
              onClick={() => setViewType('month')}
              className={`px-4 py-1.5 text-[10px] font-black uppercase rounded-lg transition-all ${viewType === 'month' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Monthly Matrix
            </button>
            <button 
              onClick={() => setViewType('week')}
              className={`px-4 py-1.5 text-[10px] font-black uppercase rounded-lg transition-all ${viewType === 'week' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Weekly Matrix
            </button>
          </div>

          <div className="flex items-center gap-2 bg-white dark:bg-slate-800 p-1 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
            <button onClick={() => navigateDate(-1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg text-slate-400 transition-colors">
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="text-[11px] font-black uppercase text-slate-700 dark:text-white px-3 tracking-widest min-w-[140px] text-center">
              {new Date(baseDate).toLocaleString('default', { month: 'long', year: 'numeric' })}
            </span>
            <button onClick={() => navigateDate(1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg text-slate-400 transition-colors">
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Matrix Table */}
      <div className="bg-white dark:bg-slate-850 rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-slate-800 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-900/50">
                <th className="sticky left-0 z-20 bg-slate-50 dark:bg-slate-900 p-5 text-left border-b border-r border-slate-200 dark:border-slate-700 min-w-[180px] shadow-[2px_0_5px_rgba(0,0,0,0.05)]">
                  <span className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">Timeline</span>
                </th>
                {filteredProcesses.map(proc => (
                  <th key={proc} className="p-5 text-center border-b border-slate-200 dark:border-slate-700 min-w-[180px]">
                    <span className="text-[10px] font-black uppercase text-indigo-600 dark:text-indigo-400 tracking-[0.15em]">{proc}</span>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {datesInRange.map(dateKey => {
                const displayStr = formatDisplayDate(dateKey);
                const [datePart, dayPart] = displayStr.split(' ');

                const manualOff = offDays.find(od => od.date === dateKey);
                const autoOff = getWeeklyOffDayType(dateKey);
                const offType = manualOff?.type || autoOff;
                const offDesc = manualOff?.description || (autoOff === 'Rest Day' ? 'Friday Rest' : 'Saturday Off');

                return (
                  <tr key={dateKey} className={`group ${offType ? 'bg-slate-50/40 dark:bg-slate-900/20' : 'hover:bg-indigo-50/10 dark:hover:bg-indigo-900/5'}`}>
                    <td className={`sticky left-0 z-10 p-5 border-b border-r border-slate-100 dark:border-slate-800 transition-colors shadow-[2px_0_5px_rgba(0,0,0,0.02)] ${offType ? 'bg-slate-50 dark:bg-slate-900' : 'bg-white dark:bg-slate-850 group-hover:bg-indigo-50/30'}`}>
                      <div className="flex items-center gap-3">
                        <div className="flex flex-col">
                          <span className="text-sm font-black text-slate-800 dark:text-white leading-none mb-1.5">{datePart}</span>
                          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{dayPart}</span>
                        </div>
                        {offType && (
                          <div className={`p-1.5 rounded-lg ${
                            offType === 'Public Holiday' ? 'text-rose-500 bg-rose-50 dark:bg-rose-900/30' :
                            offType === 'Rest Day' ? 'text-indigo-500 bg-indigo-50 dark:bg-indigo-900/30' :
                            'text-amber-500 bg-amber-50 dark:bg-amber-900/30'
                          }`}>
                            {offType === 'Public Holiday' ? <Palmtree className="w-3.5 h-3.5" /> : 
                             offType === 'Rest Day' ? <Coffee className="w-3.5 h-3.5" /> : <Ban className="w-3.5 h-3.5" />}
                          </div>
                        )}
                      </div>
                    </td>

                    {filteredProcesses.map(proc => {
                      const entries = productionData.filter(d => d.date === dateKey && d.process === proc && d.category === category);

                      return (
                        <td key={`${dateKey}-${proc}`} className="p-3 border-b border-slate-100 dark:border-slate-800 relative align-top">
                          {offType ? (
                             <div className="h-20 flex items-center justify-center opacity-10">
                                <span className="text-[10px] font-black uppercase tracking-[0.3em] -rotate-12 border-2 border-current px-3 py-1 rounded-lg">{offDesc}</span>
                             </div>
                          ) : entries.length > 0 ? (
                            <div className="space-y-2">
                                {entries.map(entry => (
                                    <div key={entry.id} className={`p-3 rounded-2xl border-2 transition-all group/cell ${
                                    entry.status === 'Completed' 
                                        ? 'bg-emerald-50/50 border-emerald-500/30 dark:bg-emerald-900/10' 
                                        : 'bg-white dark:bg-slate-800 border-indigo-100 dark:border-indigo-900/50 shadow-sm'
                                    }`}>
                                    <div className="flex justify-between items-start mb-2">
                                        <span className={`text-[8px] font-black uppercase px-1.5 py-0.5 rounded-md ${
                                        entry.status === 'Completed' ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900 dark:text-indigo-300'
                                        }`}>
                                        {entry.status === 'Completed' ? <CheckCircle2 className="w-2 h-2 inline mr-1"/> : <Clock className="w-2 h-2 inline mr-1"/>}
                                        {entry.status}
                                        </span>
                                        <span className="text-[9px] font-black font-mono text-slate-400">
                                        {entry.batchNo || '---'}
                                        </span>
                                    </div>
                                    <p className="text-xs font-black text-slate-800 dark:text-white leading-tight uppercase mb-2 truncate">
                                        {entry.productName}
                                    </p>
                                    <div className="flex justify-between items-end border-t border-slate-50 dark:border-slate-700/50 pt-2">
                                        <div className="text-[11px] font-black text-indigo-600 dark:text-indigo-400">
                                        {entry.planQuantity} <span className="text-[8px] opacity-60 uppercase">{entry.unit}</span>
                                        </div>
                                        {entry.actualQuantity > 0 && (
                                        <div className="text-[11px] font-black text-emerald-600 dark:text-emerald-400">
                                            <span className="text-[8px] opacity-50 mr-1 italic">ACT:</span>
                                            {entry.actualQuantity}
                                        </div>
                                        )}
                                    </div>
                                    </div>
                                ))}
                            </div>
                          ) : (
                            <div className="h-16 border-2 border-dashed border-slate-50 dark:border-slate-800/30 rounded-2xl flex items-center justify-center group-hover:border-slate-100 dark:group-hover:border-slate-700 transition-colors">
                               <Plus className="w-4 h-4 text-slate-50 dark:text-slate-800" />
                            </div>
                          )}
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Visual Legend */}
      <div className="flex flex-wrap items-center justify-center gap-8 py-6 bg-white/50 dark:bg-slate-900/50 rounded-3xl border border-dashed border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-3">
            <div className="w-3.5 h-3.5 rounded-full bg-indigo-500 shadow-lg shadow-indigo-500/20"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">Scheduled Target</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-3.5 h-3.5 rounded-full bg-emerald-500 shadow-lg shadow-emerald-500/20"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">Production Completed</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-3.5 h-3.5 rounded-full bg-rose-400 shadow-lg shadow-rose-400/20"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">Holiday Lock</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-3.5 h-3.5 rounded-full bg-slate-200 dark:bg-slate-700"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">Weekly Maintenance</span>
          </div>
      </div>
    </div>
  );
};

