import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { 
  Calendar as CalendarIcon, 
  ChevronLeft, 
  ChevronRight, 
  Palmtree,
  Coffee,
  Ban,
  Clock,
  CheckCircle2,
  Plus,
  LayoutGrid
} from 'lucide-react';
import { formatDisplayDate, getTodayISO, getWeeklyOffDayType } from '../../utils/dateUtils';

export const ProductionCalendar: React.FC = () => {
  const { category, refreshKey } = useDashboard();
  const [viewType, setViewType] = useState<'month' | 'week'>('month');
  const [baseDate, setBaseDate] = useState(getTodayISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  // Generate date range based on viewType
  const datesInRange = useMemo(() => {
    const dates = [];
    const curr = new Date(baseDate);

    if (viewType === 'month') {
      const year = curr.getFullYear();
      const month = curr.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);

      for (let d = new Date(firstDay); d <= lastDay; d.setDate(d.getDate() + 1)) {
        dates.push(new Date(d).toISOString().split('T')[0]);
      }
    } else {
      // Get current week (starting Sunday)
      const day = curr.getDay();
      const diff = curr.getDate() - day;
      const startOfWeek = new Date(curr.setDate(diff));

      for (let i = 0; i < 7; i++) {
        const d = new Date(startOfWeek);
        d.setDate(d.getDate() + i);
        dates.push(d.toISOString().split('T')[0]);
      }
    }
    return dates;
  }, [baseDate, viewType]);

  const filteredProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];
    return PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));
  }, [category]);

  const navigateDate = (direction: number) => {
    const d = new Date(baseDate);
    if (viewType === 'month') {
      d.setMonth(d.getMonth() + direction);
    } else {
      d.setDate(d.getDate() + (direction * 7));
    }
    setBaseDate(d.toISOString().split('T')[0]);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header & Controls */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-2 uppercase tracking-tight">
            <CalendarIcon className="w-7 h-7 text-indigo-600" />
            Production Schedule
          </h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
            Visual Matrix View • {category} Department
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="bg-white dark:bg-slate-850 p-1.5 rounded-2xl border border-slate-100 dark:border-slate-800 flex shadow-sm">
            <button 
              onClick={() => setViewType('month')}
              className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'month' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'}`}
            >
              Monthly Matrix
            </button>
            <button 
              onClick={() => setViewType('week')}
              className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'week' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'}`}
            >
              Weekly Matrix
            </button>
          </div>

          <div className="flex items-center gap-2 bg-white dark:bg-slate-850 p-1.5 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm">
            <button onClick={() => navigateDate(-1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400 transition-colors">
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="text-[11px] font-black uppercase text-slate-700 dark:text-white px-4 tracking-widest min-w-[160px] text-center">
              {new Date(baseDate).toLocaleString('default', { month: 'long', year: 'numeric' })}
              {viewType === 'week' && ` (W${Math.ceil(new Date(baseDate).getDate() / 7)})`}
            </span>
            <button onClick={() => navigateDate(1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400 transition-colors">
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Matrix Table */}
      <div className="bg-white dark:bg-slate-850 rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-slate-800 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-900/50">
                <th className="sticky left-0 z-20 bg-slate-50 dark:bg-slate-900 p-6 text-left border-b border-r border-slate-200 dark:border-slate-700 min-w-[180px] shadow-[2px_0_5px_rgba(0,0,0,0.05)]">
                  <span className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">Date / Day</span>
                </th>
                {filteredProcesses.map(proc => (
                  <th key={proc} className="p-6 text-center border-b border-slate-200 dark:border-slate-700 min-w-[200px]">
                    <span className="text-[10px] font-black uppercase text-indigo-600 dark:text-indigo-400 tracking-[0.15em]">{proc}</span>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {datesInRange.map(dateKey => {
                const displayStr = formatDisplayDate(dateKey);
                const [datePart, dayPart] = displayStr.split(' ');

                const manualOff = offDays.find(od => od.date === dateKey);
                const autoOff = getWeeklyOffDayType(dateKey);
                const offType = manualOff?.type || autoOff;
                const offDesc = manualOff?.description || (autoOff === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off');

                return (
                  <tr key={dateKey} className={`group ${offType ? 'bg-slate-50/40 dark:bg-slate-900/20' : 'hover:bg-indigo-50/10 dark:hover:bg-indigo-900/5'}`}>
                    {/* Row Header: Date and Day */}
                    <td className={`sticky left-0 z-10 p-6 border-b border-r border-slate-100 dark:border-slate-800 transition-colors shadow-[2px_0_5px_rgba(0,0,0,0.02)] ${offType ? 'bg-slate-50 dark:bg-slate-900' : 'bg-white dark:bg-slate-850 group-hover:bg-indigo-50/30'}`}>
                      <div className="flex items-center gap-3">
                        <div className="flex flex-col">
                          <span className="text-base font-black text-slate-800 dark:text-white leading-none mb-1.5">{datePart}</span>
                          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.1em]">{dayPart}</span>
                        </div>
                        {offType && (
                          <div className={`p-1.5 rounded-lg ${
                            offType === 'Public Holiday' ? 'text-rose-500 bg-rose-50 dark:bg-rose-900/30' :
                            offType === 'Rest Day' ? 'text-indigo-500 bg-indigo-50 dark:bg-indigo-900/30' :
                            'text-amber-500 bg-amber-50 dark:bg-amber-900/30'
                          }`}>
                            {offType === 'Public Holiday' ? <Palmtree className="w-4 h-4" /> : 
                             offType === 'Rest Day' ? <Coffee className="w-4 h-4" /> : <Ban className="w-4 h-4" />}
                          </div>
                        )}
                      </div>
                    </td>

                    {/* Columns: Processes */}
                    {filteredProcesses.map(proc => {
                      const entries = productionData.filter(d => d.date === dateKey && d.process === proc && d.category === category);

                      return (
                        <td key={`${dateKey}-${proc}`} className="p-3 border-b border-slate-100 dark:border-slate-800 relative align-top min-h-[100px]">
                          {offType ? (
                             <div className="h-full py-4 flex items-center justify-center opacity-10">
                                <span className="text-[10px] font-black uppercase tracking-[0.3em] -rotate-12 border-2 border-current px-3 py-1 rounded-lg text-center leading-tight">
                                  {offDesc}
                                </span>
                             </div>
                          ) : entries.length > 0 ? (
                            <div className="space-y-3">
                                {entries.map(entry => (
                                    <div key={entry.id} className={`p-4 rounded-3xl border-2 transition-all group/cell ${
                                    entry.status === 'Completed' 
                                        ? 'bg-emerald-50/50 border-emerald-500/30 dark:bg-emerald-900/10' 
                                        : 'bg-white dark:bg-slate-800 border-indigo-100 dark:border-indigo-900/50 shadow-sm'
                                    }`}>
                                    <div className="flex justify-between items-start mb-2.5">
                                        <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-md ${
                                        entry.status === 'Completed' ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900 dark:text-indigo-300'
                                        }`}>
                                        {entry.status === 'Completed' ? <CheckCircle2 className="w-2.5 h-2.5 inline mr-1"/> : <Clock className="w-2.5 h-2.5 inline mr-1"/>}
                                        {entry.status}
                                        </span>
                                        <span className="text-[9px] font-black font-mono text-slate-400">
                                        {entry.batchNo || 'PENDING'}
                                        </span>
                                    </div>
                                    <p className="text-xs font-black text-slate-800 dark:text-white leading-tight uppercase mb-3 break-words">
                                        {entry.productName}
                                    </p>
                                    <div className="flex justify-between items-end border-t border-slate-50 dark:border-slate-700/50 pt-3">
                                        <div className="text-[11px] font-black text-indigo-600 dark:text-indigo-400">
                                          {entry.planQuantity} <span className="text-[8px] opacity-60 uppercase font-bold">{entry.unit}</span>
                                        </div>
                                        {entry.actualQuantity > 0 && (
                                        <div className="text-[11px] font-black text-emerald-600 dark:text-emerald-400 flex flex-col items-end">
                                            <span className="text-[8px] opacity-50 uppercase tracking-tighter">Actual Yield</span>
                                            {entry.actualQuantity}
                                        </div>
                                        )}
                                    </div>
                                    </div>
                                ))}
                            </div>
                          ) : (
                            <div className="h-20 border-2 border-dashed border-slate-50 dark:border-slate-800/30 rounded-[1.5rem] flex items-center justify-center group-hover:border-slate-100 dark:group-hover:border-slate-700 transition-colors">
                               <Plus className="w-5 h-5 text-slate-100 dark:text-slate-800" />
                            </div>
                          )}
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Visual Legend */}
      <div className="flex flex-wrap items-center justify-center gap-8 py-6 bg-white/50 dark:bg-slate-900/50 rounded-[2.5rem] border border-dashed border-slate-200 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3">
            <div className="w-4 h-4 rounded-xl bg-indigo-500 shadow-lg shadow-indigo-500/20"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Planned Job</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-4 h-4 rounded-xl bg-emerald-500 shadow-lg shadow-emerald-500/20"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Finished Output</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-4 h-4 rounded-xl bg-rose-400 shadow-lg shadow-rose-400/20"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">National Holiday</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-4 h-4 rounded-xl bg-slate-200 dark:bg-slate-700"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Rest Day / Off</span>
          </div>
      </div>
    </div>
  );
};

