                          ) : (
                            <div className="h-24 border-2 border-dashed border-slate-100 dark:border-slate-800/50 rounded-[2rem] flex items-center justify-center group-hover:border-indigo-200 dark:group-hover:border-indigo-900 transition-colors">
                               <Plus className={`w-5 h-5 text-slate-100 dark:text-slate-800 group-hover:${colors.text}`} />
                            </div>
                          )}
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Visual Legend */}
      <div className="flex flex-wrap items-center justify-center gap-8 py-6 bg-white/50 dark:bg-slate-900/50 rounded-[2.5rem] border-2 border-dashed border-slate-200 dark:border-slate-700 shadow-sm">
          <div className="flex items-center gap-3">
            <div className="w-4 h-4 rounded-xl bg-indigo-500 shadow-lg shadow-indigo-500/20"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Planned Job</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-4 h-4 rounded-xl bg-emerald-500 shadow-lg shadow-emerald-500/20"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Finished Output</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-4 h-4 rounded-xl bg-rose-400 shadow-lg shadow-rose-400/20"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">National Holiday</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-4 h-4 rounded-xl bg-slate-200 dark:bg-slate-700"></div>
            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Rest Day / Off</span>
          </div>
      </div>
    </div>
  );
};

/**
 * HALAGEL DATE UTILITIES
 * Strictly enforces Malaysia Time (UTC+8) to prevent the "Yesterday Bug".
 */

import { OffDayType } from "../types";

/**
 * Returns YYYY-MM-DD based on Malaysia Timezone.
 * Safe for use in <input type="date">
 */
export const getTodayISO = (): string => {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(new Date());
};

/**
 * Helper to convert YYYY-MM-DD to DD-MM-YYYY for display
 */
export const formatDateToDMY = (dateStr: string): string => {
  if (!dateStr) return '';
  const clean = dateStr.split(' ')[0];
  const parts = clean.split('-');
  if (parts.length !== 3) return clean;
  return `${parts[2]}-${parts[1]}-${parts[0]}`;
};

/**
 * Checks if a given date string is a weekly rest day (Friday or Saturday).
 */
export const isWeeklyRestDay = (dateStr: string): boolean => {
  const parts = dateStr.split(' ')[0].split('-');
  if (parts.length !== 3) return false;
  // Use UTC-8 relative date construction
  const d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
  const day = d.getDay();
  return day === 5 || day === 6;
};

/**
 * Returns the automatic type for a day of the week.
 * Friday = Rest Day, Saturday = Off Day.
 */
export const getWeeklyOffDayType = (dateStr: string): OffDayType | null => {
  const parts = dateStr.split(' ')[0].split('-');
  if (parts.length !== 3) return null;
  const d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
  const day = d.getDay();
  if (day === 5) return 'Rest Day';
  if (day === 6) return 'Off Day';
  return null;
};

/**
 * Returns YYYY-MM based on Malaysia Timezone.
 */
export const getCurrentMonthISO = (): string => {
  return getTodayISO().substring(0, 7);
};

/**
 * Returns the current date and time in the format YYYY-MM-DD HH:mm:ss
 * tailored for database/sheet storage.
 */
export const getDbTimestamp = (): string => {
  const now = new Date();
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });

  const parts = formatter.formatToParts(now);
  const find = (type: string) => parts.find(p => p.type === type)?.value;

  return `${find('year')}-${find('month')}-${find('day')} ${find('hour')}:${find('minute')}:${find('second')}`;
};

/**
 * Formats ISO or DB timestamp string to DD-MM-YYYY HH:mm:ss in Malaysia Time.
 */
export const formatFullTimestamp = (isoStr: string): string => {
  if (!isoStr) return '';

  const date = new Date(isoStr.includes(' ') ? isoStr.replace(' ', 'T') : isoStr);
  if (isNaN(date.getTime())) return isoStr;

  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });

  const parts = formatter.formatToParts(date);
  const find = (type: string) => parts.find(p => p.type === type)?.value;

  return `${find('day')}-${find('month')}-${find('year')} ${find('hour')}:${find('minute')}:${find('second')}`;
};

/**
 * Formats YYYY-MM-DD for display (e.g., "28-12-2025 SUNDAY").
 */
export const formatDisplayDate = (dateStr: string): string => {
  if (!dateStr) return 'Invalid Date';

  const cleanDate = dateStr.split(' ')[0].split('T')[0];
  const parts = cleanDate.split('-');

  if (parts.length !== 3) return cleanDate;

  const year = parseInt(parts[0], 10);
  const month = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);

  const localDate = new Date(year, month - 1, day, 12, 0, 0);

  if (isNaN(localDate.getTime())) return cleanDate;

  const dayName = new Intl.DateTimeFormat('en-MY', { 
    weekday: 'long', 
    timeZone: 'Asia/Kuala_Lumpur' 
  }).format(localDate).toUpperCase();

  return `${day.toString().padStart(2, '0')}-${month.toString().padStart(2, '0')}-${year} ${dayName}`;
};

/**
 * Validates if a string is a valid YYYY-MM-DD format
 */
export const isValidISODate = (dateStr: string): boolean => {
  return /^\d{4}-\d{2}-\d{2}$/.test(dateStr);
};

import React, { useState, useMemo, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, ProductionStatus } from '../../types';
import { Download, Filter, XCircle, Palmtree, MessageSquare, ArrowUpDown, Clock, CheckCircle, Coffee, Ban } from 'lucide-react';
import { getTodayISO, getWeeklyOffDayType, formatDateToDMY } from '../../utils/dateUtils';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const ProductionLog: React.FC = () => {
  const { refreshKey } = useDashboard();
  const [data, setData] = useState<ProductionEntry[]>([]);
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);
  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');
  const [statusFilter, setStatusFilter] = useState('All');

  useEffect(() => {
    setData(StorageService.getProductionData());
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const filteredData = useMemo(() => {
    let result = data.filter(d => {
      if (!d) return false;
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStatus = statusFilter === 'All' || d.status === statusFilter;
      const matchStart = !dateRange.start || (d.date && d.date >= dateRange.start);
      const matchEnd = !dateRange.end || (d.date && d.date <= dateRange.end);
      return matchCat && matchProc && matchStatus && matchStart && matchEnd;
    });

    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    if (sortConfig) {
        result = [...result].sort((a, b) => {
            let aVal: any = a[sortConfig.key];
            let bVal: any = b[sortConfig.key];
            if (sortConfig.key === 'status') {
                aVal = statusWeight[a.status as ProductionStatus] || 0;
                bVal = statusWeight[b.status as ProductionStatus] || 0;
            } else {
                aVal = (aVal || '').toString();
                bVal = (bVal || '').toString();
            }
            if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
    } else {
        result.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    }

    return result;
  }, [data, dateRange, category, processType, statusFilter, sortConfig]);

  const calculateEfficiency = (actual: number, plan: number) => plan > 0 ? ((actual / plan) * 100).toFixed(1) : '0';

  const resetFilters = () => {
    setDateRange({ start: '', end: '' });
    setCategory('All');
    setProcessType('All');
    setStatusFilter('All');
    setSortConfig(null);
  };

  const downloadCSV = () => {
    const headers = ["Date", "Category", "Process", "Product", "Plan", "Actual", "Unit", "Efficiency %", "Batch No", "Manpower", "Status", "Plan Remark", "Actual Remark"];
    const rows = filteredData.map(d => [
        d.date, d.category, d.process, `"${d.productName}"`, d.planQuantity || 0, d.actualQuantity || 0, d.unit || 'KG',
        calculateEfficiency(d.actualQuantity || 0, d.planQuantity || 0), d.batchNo || '', (d.manpower || 0).toFixed(2), d.status || 'In Progress', 
        `"${(d.planRemark || '').replace(/"/g, '""')}"`, `"${(d.actualRemark || '').replace(/"/g, '""')}"`
    ]);
    const filename = `production_log_${getTodayISO()}.csv`;

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } 
    }));
  };

  const SortHeader = ({ label, sortKey, align = 'left' }: { label: string, sortKey: keyof ProductionEntry, align?: 'left' | 'right' | 'center' }) => (
    <th className={`px-8 py-5 cursor-pointer group text-${align}`} onClick={() => handleSort(sortKey)}>
        <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : ''}`}>
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-800 dark:text-white">Production Log</h2>
          <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Detailed operational history</p>
        </div>

        <button 
          onClick={downloadCSV} 
          className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-emerald-700 transition shadow-lg shadow-emerald-500/20"
        >
          <Download className="w-4 h-4" /> Export Report
        </button>
      </div>

