                                  {od.type}
                                </span>
                              </div>
                              <p className="text-[10px] font-mono text-slate-400 mt-0.5 font-bold">{formatDateToDMY(od.date)}</p>
                          </div>
                      </div>
                      <button onClick={() => handleRemove(od.id)} className="p-2 text-slate-300 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-xl transition-all">
                        <Trash2 className="w-4 h-4" />
                      </button>
                  </div>
                ))}
              </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { OffDay } from '../../types';
import { Trash2, Plus } from 'lucide-react';
import { formatDateToDMY } from '../../utils/dateUtils';

export const OffDays: React.FC = () => {
  const { user } = useAuth();
  const [offDays, setOffDays] = useState<OffDay[]>(StorageService.getOffDays());
  const [newDate, setNewDate] = useState('');
  const [description, setDescription] = useState('');

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDate) return;

    if (offDays.some(d => d.date === newDate)) {
        alert('Date already marked as off day');
        return;
    }

    const newOffDay: OffDay = {
        id: Date.now().toString(),
        date: newDate,
        description: description || 'Scheduled Off',
        type: 'Off Day',
        createdBy: user!.id
    };

    const updated = [...offDays, newOffDay].sort((a,b) => a.date.localeCompare(b.date));
    StorageService.saveOffDays(updated);
    setOffDays(updated);
    setNewDate('');
    setDescription('');
  };

  const handleRemove = (id: string) => {
    const updated = offDays.filter(d => d.id !== id);
    StorageService.saveOffDays(updated);
    setOffDays(updated);
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="md:col-span-1 bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-fit">
            <h3 className="text-lg font-bold text-gray-800 mb-4">Add Off Day</h3>
            <form onSubmit={handleAdd} className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
                    <input 
                        type="date" 
                        required
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg"
                        value={newDate}
                        onChange={e => setNewDate(e.target.value)}
                    />
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                    <input 
                        type="text" 
                        placeholder="e.g. National Holiday"
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg"
                        value={description}
                        onChange={e => setDescription(e.target.value)}
                    />
                </div>
                <button 
                    type="submit"
                    className="w-full bg-slate-800 text-white py-2 rounded-lg flex items-center justify-center gap-2 hover:bg-slate-700"
                >
                    <Plus className="w-4 h-4" /> Add Date
                </button>
            </form>
        </div>

        <div className="md:col-span-2 bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-6 border-b border-gray-100">
                <h3 className="text-lg font-bold text-gray-800">Scheduled Off Days</h3>
            </div>
            <ul className="divide-y divide-gray-100">
                {offDays.length === 0 ? (
                    <li className="p-6 text-gray-400 text-center">No off days scheduled.</li>
                ) : offDays.map(day => (
                    <li key={day.id} className="p-4 flex items-center justify-between hover:bg-gray-50">
                        <div className="flex items-center space-x-4">
                            <div className="bg-red-50 text-red-600 px-3 py-1 rounded-md font-mono text-sm font-bold">
                                {formatDateToDMY(day.date)}
                            </div>
                            <span className="text-gray-700 font-medium">{day.description}</span>
                        </div>
                        <button 
                            onClick={() => handleRemove(day.id)}
                            className="text-gray-400 hover:text-red-500 transition-colors"
                        >
                            <Trash2 className="w-5 h-5" />
                        </button>
                    </li>
                ))}
            </ul>
        </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { 
  Calendar as CalendarIcon, 
  ChevronLeft, 
  ChevronRight, 
  Palmtree,
  Coffee,
  Ban,
  Clock,
  CheckCircle2,
  Plus
} from 'lucide-react';
import { formatDisplayDate, getTodayISO, getWeeklyOffDayType } from '../../utils/dateUtils';

// Color map for process-specific aesthetics
const PROCESS_COLORS: Record<string, { bg: string, text: string, border: string, tint: string }> = {
  'Mixing': { bg: 'bg-blue-500', text: 'text-blue-600', border: 'border-blue-500', tint: 'bg-blue-50/50' },
  'Encapsulation': { bg: 'bg-purple-500', text: 'text-purple-600', border: 'border-purple-500', tint: 'bg-purple-50/50' },
  'Filling': { bg: 'bg-emerald-500', text: 'text-emerald-600', border: 'border-emerald-500', tint: 'bg-emerald-50/50' },
  'Sorting': { bg: 'bg-slate-500', text: 'text-slate-600', border: 'border-slate-500', tint: 'bg-slate-50/50' },
  'Packing': { bg: 'bg-rose-500', text: 'text-rose-600', border: 'border-rose-500', tint: 'bg-rose-50/50' },
  'Blister': { bg: 'bg-indigo-500', text: 'text-indigo-600', border: 'border-indigo-500', tint: 'bg-indigo-50/50' },
  'Capsules': { bg: 'bg-amber-400', text: 'text-amber-600', border: 'border-amber-400', tint: 'bg-amber-50/50' },
};

export const ProductionCalendar: React.FC = () => {
  const { category, refreshKey, isDarkMode } = useDashboard();
  const [viewType, setViewType] = useState<'month' | 'week'>('month');
  const [baseDate, setBaseDate] = useState(getTodayISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  // Generate date range based on viewType
  const datesInRange = useMemo(() => {
    const dates = [];
    const curr = new Date(baseDate);

    if (viewType === 'month') {
      const year = curr.getFullYear();
      const month = curr.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);

      for (let d = new Date(firstDay); d <= lastDay; d.setDate(d.getDate() + 1)) {
        dates.push(new Date(d).toISOString().split('T')[0]);
      }
    } else {
      const day = curr.getDay();
      const diff = curr.getDate() - day;
      const startOfWeek = new Date(curr.setDate(diff));

      for (let i = 0; i < 7; i++) {
        const d = new Date(startOfWeek);
        d.setDate(d.getDate() + i);
        dates.push(d.toISOString().split('T')[0]);
      }
    }
    return dates;
  }, [baseDate, viewType]);

  const filteredProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];
    return PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));
  }, [category]);

  const navigateDate = (direction: number) => {
    const d = new Date(baseDate);
    if (viewType === 'month') {
      d.setMonth(d.getMonth() + direction);
    } else {
      d.setDate(d.getDate() + (direction * 7));
    }
    setBaseDate(d.toISOString().split('T')[0]);
  };

  const handleAddNewAt = (date: string, process: string) => {
    // Open the InputModal pre-filled for the selected date and process
    window.dispatchEvent(new CustomEvent('edit-production-entry', { 
      detail: { 
        id: '', // New entry indicator
        date, 
        process, 
        category, 
        productName: '', 
        planQuantity: 0, 
        actualQuantity: 0, 
        unit: 'KG',
        status: 'In Progress'
      } 
    }));
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header & Controls */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
        <div>
