            <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Rest Day / Off</span>
          </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { 
  Calendar as CalendarIcon, 
  ChevronLeft, 
  ChevronRight, 
  Clock,
  CheckCircle2,
  Plus,
  Ban
} from 'lucide-react';
import { formatDisplayDate, getTodayISO, getWeeklyOffDayType } from '../../utils/dateUtils';

/**
 * PROCESS IDENTITY BRANDING CONFIGURATION
 * 
 * To add a new process (e.g., 'Labeling'), simply add a new key below.
 * - 'border': This is the thick vertical line (Anchor 1). Use 'border-[color]-[weight]'.
 * - 'bg': This is the horizontal bar (Anchor 2) and progress bars. Use 'bg-[color]-[weight]'.
 * - 'text': The label color. Use 'text-[color]-[weight]'.
 * - 'tint': Subtle cell background. Use 'bg-[color]-50/30'.
 */
const PROCESS_COLORS: Record<string, { bg: string, text: string, border: string, tint: string }> = {
  'Mixing': { bg: 'bg-blue-500', text: 'text-blue-600', border: 'border-blue-500', tint: 'bg-blue-50/30' },
  'Encapsulation': { bg: 'bg-purple-600', text: 'text-purple-700', border: 'border-purple-600', tint: 'bg-purple-50/30' },
  'Filling': { bg: 'bg-emerald-500', text: 'text-emerald-600', border: 'border-emerald-500', tint: 'bg-emerald-50/30' },

  // BRANDING FOR SORTING (Bold Slate Identity)
  'Sorting': { 
    bg: 'bg-slate-600', 
    text: 'text-slate-700', 
    border: 'border-slate-600', 
    tint: 'bg-slate-50/40' 
  },

  // BRANDING FOR PACKING (Vibrant Rose Identity)
  'Packing': { 
    bg: 'bg-rose-500', 
    text: 'text-rose-600', 
    border: 'border-rose-500', 
    tint: 'bg-rose-50/30' 
  },

  // BRANDING FOR BLISTER (Indigo Identity)
  'Blister': { bg: 'bg-indigo-600', text: 'text-indigo-700', border: 'border-indigo-600', tint: 'bg-indigo-50/30' },

  // BRANDING FOR CAPSULES (Amber Identity)
  'Capsules': { bg: 'bg-amber-400', text: 'text-amber-600', border: 'border-amber-400', tint: 'bg-amber-50/30' },
};

export const ProductionCalendar: React.FC = () => {
  const { category, refreshKey } = useDashboard();
  const [viewType, setViewType] = useState<'month' | 'week'>('month');
  const [baseDate, setBaseDate] = useState(getTodayISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const datesInRange = useMemo(() => {
    const dates = [];
    const curr = new Date(baseDate);
    if (viewType === 'month') {
      const year = curr.getFullYear();
      const month = curr.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);
      for (let d = new Date(firstDay); d <= lastDay; d.setDate(d.getDate() + 1)) {
        dates.push(new Date(d).toISOString().split('T')[0]);
      }
    } else {
      const day = curr.getDay();
      const diff = curr.getDate() - day;
      const startOfWeek = new Date(curr.setDate(diff));
      for (let i = 0; i < 7; i++) {
        const d = new Date(startOfWeek);
        d.setDate(d.getDate() + i);
        dates.push(d.toISOString().split('T')[0]);
      }
    }
    return dates;
  }, [baseDate, viewType]);

  const filteredProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];
    return PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));
  }, [category]);

  const navigateDate = (direction: number) => {
    const d = new Date(baseDate);
    if (viewType === 'month') d.setMonth(d.getMonth() + direction);
    else d.setDate(d.getDate() + (direction * 7));
    setBaseDate(d.toISOString().split('T')[0]);
  };

  const handleAddNewAt = (date: string, process: string) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { 
      detail: { 
        id: '', date, process, category, productName: '', 
        planQuantity: 0, actualQuantity: 0, unit: 'KG', status: 'In Progress'
      } 
    }));
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Matrix Controls */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-2 uppercase tracking-tight">
            <CalendarIcon className="w-7 h-7 text-indigo-600" />
            Scheduling Matrix
          </h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
            Manufacturing process flow • {category}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 flex shadow-sm">
            <button 
              onClick={() => setViewType('month')}
              className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'month' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Month View
            </button>
            <button 
              onClick={() => setViewType('week')}
              className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'week' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Week View
            </button>
          </div>

          <div className="flex items-center gap-2 bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 shadow-sm">
            <button onClick={() => navigateDate(-1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400 transition-colors">
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="text-[11px] font-black uppercase text-slate-700 dark:text-white px-4 tracking-widest min-w-[160px] text-center">
              {new Date(baseDate).toLocaleString('default', { month: 'long', year: 'numeric' })}
            </span>
            <button onClick={() => navigateDate(1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400 transition-colors">
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Main Matrix Board */}
      <div className="bg-white dark:bg-slate-850 rounded-[2.5rem] shadow-xl border-2 border-slate-200 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-900/50">
                <th className="sticky left-0 z-30 bg-slate-50 dark:bg-slate-900 p-6 text-left border-b-2 border-r-4 border-slate-200 dark:border-slate-700 min-w-[220px] shadow-[4px_0_10px_rgba(0,0,0,0.08)]">
                  <span className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">Process Identity</span>
                </th>
                {datesInRange.map(dateKey => {
                  const displayStr = formatDisplayDate(dateKey);
                  const [datePart, dayPart] = displayStr.split(' ');
                  const isOff = !!(getWeeklyOffDayType(dateKey) || offDays.find(od => od.date === dateKey));
                  return (
                    <th key={dateKey} className={`p-5 text-center border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 min-w-[240px] last:border-r-0 ${isOff ? 'bg-slate-100/50 dark:bg-slate-800/30' : ''}`}>
                      <div className="flex flex-col items-center">
                        <span className="text-sm font-black text-slate-800 dark:text-white mb-1">{datePart}</span>
                        <span className="text-[10px] font-bold text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{dayPart}</span>
                      </div>
                    </th>
                  );
                })}
              </tr>
            </thead>
            <tbody>
              {filteredProcesses.map(proc => {
                const colors = PROCESS_COLORS[proc] || PROCESS_COLORS['Mixing'];
                return (
                  <tr key={proc} className="group">
                    {/* BOLD PROCESS IDENTITY BRANDING ANCHORS */}
                    <td className={`sticky left-0 z-20 p-6 border-b-2 border-r-4 border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-850 group-hover:bg-slate-50 dark:group-hover:bg-slate-800 transition-colors shadow-[4px_0_10px_rgba(0,0,0,0.05)] border-l-[12px] ${colors.border}`}>
                      <div className="flex flex-col">
                        <span className={`text-[13px] font-black uppercase tracking-[0.1em] mb-2 ${colors.text}`}>{proc}</span>
                        {/* Horizontal Accent Bar Anchor */}
                        <div className={`w-12 h-2 rounded-full shadow-sm ${colors.bg}`}></div>
                      </div>
                    </td>

                    {/* Operational Cells */}
                    {datesInRange.map(dateKey => {
                      const entries = productionData.filter(d => d.date === dateKey && d.process === proc && d.category === category);
                      const manualOff = offDays.find(od => od.date === dateKey);
                      const autoOff = getWeeklyOffDayType(dateKey);
                      const offType = manualOff?.type || autoOff;
                      const offDesc = manualOff?.description || (autoOff === 'Rest Day' ? 'Friday Rest' : 'Saturday Off');

                      return (
                        <td key={`${dateKey}-${proc}`} className={`p-4 border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 relative align-top min-h-[140px] last:border-r-0 ${offType ? 'bg-slate-50/40 dark:bg-slate-900/20' : colors.tint}`}>
                          {offType ? (
                             <div className="h-full py-6 flex items-center justify-center opacity-10 min-h-[100px]">
                                <span className="text-[10px] font-black uppercase tracking-[0.3em] -rotate-12 border-2 border-current px-3 py-1 rounded-lg text-center leading-tight">
                                  {offDesc}
                                </span>
                             </div>
                          ) : entries.length > 0 ? (
                            <div className="space-y-4">
                                {entries.map(entry => (
                                    <div key={entry.id} className={`p-4 rounded-3xl border-2 transition-all relative overflow-hidden group/card ${
                                    entry.status === 'Completed' 
                                        ? 'bg-emerald-50/50 border-emerald-500/30 dark:bg-emerald-900/10' 
                                        : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700 shadow-sm'
                                    }`}>
                                    {entry.status !== 'Completed' && (
                                      <div className="absolute top-0 left-0 h-1 bg-indigo-500/10 w-full">
                                        <div className={`h-full ${colors.bg} w-1/3`}></div>
                                      </div>
                                    )}
                                    <div className="flex justify-between items-start mb-2.5">
                                        <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-md ${
                                        entry.status === 'Completed' ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900 dark:text-indigo-300'
                                        }`}>
                                        {entry.status === 'Completed' ? <CheckCircle2 className="w-2.5 h-2.5 inline mr-1"/> : <Clock className="w-2.5 h-2.5 inline mr-1"/>}
                                        {entry.status}
                                        </span>
                                        <span className="text-[9px] font-black font-mono text-slate-400">{entry.batchNo || 'PENDING'}</span>
                                    </div>
                                    <p className="text-xs font-black text-slate-800 dark:text-white leading-tight uppercase mb-3 break-words">{entry.productName}</p>
                                    <div className="flex justify-between items-end border-t border-slate-50 dark:border-slate-700/50 pt-3">
                                        <div className={`text-[11px] font-black ${colors.text}`}>
                                          {entry.planQuantity} <span className="text-[8px] opacity-60 uppercase font-bold">{entry.unit}</span>
                                        </div>
                                        {entry.actualQuantity > 0 && (
                                        <div className="text-[11px] font-black text-emerald-600 dark:text-emerald-400 flex flex-col items-end">
                                            <span className="text-[8px] opacity-50 uppercase tracking-tighter">Actual Yield</span>
                                            {entry.actualQuantity}
                                        </div>
                                        )}
                                    </div>
                                    </div>
                                ))}
                                <button 
                                  onClick={() => handleAddNewAt(dateKey, proc)}
                                  className={`w-full py-2 border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity hover:bg-white dark:hover:bg-slate-800/20 ${colors.text}`}
                                >
                                  <Plus className="w-3 h-3" />
                                </button>
                            </div>
                          ) : (
                            <div 
                              onClick={() => handleAddNewAt(dateKey, proc)}
                              className="h-24 border-2 border-dashed border-slate-100 dark:border-slate-800/50 rounded-[2rem] flex items-center justify-center hover:border-indigo-200 dark:hover:border-indigo-900 transition-colors cursor-pointer hover:bg-white dark:hover:bg-slate-800/50"
                            >
                               <Plus className={`w-5 h-5 text-slate-200 dark:text-slate-700 hover:${colors.text} transition-colors`} />
                            </div>
                          )}
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

