                  tick={{ fontSize: 10, fontWeight: 900, fill: '#94a3b8' }} 
                  domain={[0, 120]}
                />
                <Tooltip 
                  cursor={{ fill: isDarkMode ? '#1e293b' : '#f8fafc', opacity: 0.4 }}
                  contentStyle={{ 
                      backgroundColor: isDarkMode ? '#1e293b' : '#fff', 
                      borderRadius: '24px', 
