import React, { useMemo, useState, useRef, useEffect } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { 
  Calendar as CalendarIcon, 
  ChevronLeft, 
  ChevronRight, 
  Clock,
  CheckCircle2,
  Plus,
  Info,
  ArrowLeftCircle,
  ArrowRightCircle
} from 'lucide-react';
import { formatDisplayDate, getTodayISO, getWeeklyOffDayType, formatDateToDMY } from '../../utils/dateUtils';

/**
 * UNIFIED PROCESS IDENTITY SYSTEM
 */
const PROCESS_COLORS: Record<string, { bg: string, text: string, border: string, tint: string }> = {
  'Mixing': { bg: 'bg-blue-600', text: 'text-blue-700', border: 'border-blue-600', tint: 'bg-blue-50/20' },
  'Encapsulation': { bg: 'bg-purple-600', text: 'text-purple-700', border: 'border-purple-600', tint: 'bg-purple-50/20' },
  'Filling': { bg: 'bg-emerald-600', text: 'text-emerald-700', border: 'border-emerald-600', tint: 'bg-emerald-50/20' },
  'Sorting': { bg: 'bg-slate-700', text: 'text-slate-800', border: 'border-slate-700', tint: 'bg-slate-100/30' },
  'Packing': { bg: 'bg-rose-600', text: 'text-rose-700', border: 'border-rose-600', tint: 'bg-rose-50/20' },
  'Blister': { bg: 'bg-indigo-600', text: 'text-indigo-700', border: 'border-indigo-600', tint: 'bg-indigo-50/20' },
  'Capsules': { bg: 'bg-amber-500', text: 'text-amber-700', border: 'border-amber-500', tint: 'bg-amber-50/20' },
};

export const ProductionCalendar: React.FC = () => {
  const { category, refreshKey } = useDashboard();
  const [viewType, setViewType] = useState<'month' | 'week'>('month');
  const [baseDate, setBaseDate] = useState(getTodayISO());

  // Refs for Drag-to-Scroll
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  // DRAG-TO-SCROLL LOGIC
  const handleMouseDown = (e: React.MouseEvent) => {
    if (!scrollContainerRef.current) return;
    setIsDragging(true);
    setStartX(e.pageX - scrollContainerRef.current.offsetLeft);
    setScrollLeft(scrollContainerRef.current.scrollLeft);
  };

  const handleMouseLeave = () => setIsDragging(false);
  const handleMouseUp = () => setIsDragging(false);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !scrollContainerRef.current) return;
    e.preventDefault();
    const x = e.pageX - scrollContainerRef.current.offsetLeft;
    const walk = (x - startX) * 2; // Scroll multiplier
    scrollContainerRef.current.scrollLeft = scrollLeft - walk;
  };

  const scrollMatrix = (direction: 'left' | 'right') => {
    if (!scrollContainerRef.current) return;
    const offset = direction === 'left' ? -400 : 400;
    scrollContainerRef.current.scrollTo({
      left: scrollContainerRef.current.scrollLeft + offset,
      behavior: 'smooth'
    });
  };

  const columns = useMemo(() => {
    const cols = [];
    const curr = new Date(baseDate);

    if (viewType === 'month') {
      const year = curr.getFullYear();
      const month = curr.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);
      for (let d = new Date(firstDay); d <= lastDay; d.setDate(d.getDate() + 1)) {
        const dateKey = d.toISOString().split('T')[0];
        const display = formatDisplayDate(dateKey);
        cols.push({
          key: dateKey,
          label: display.split(' ')[0],
          subLabel: display.split(' ')[1],
          isAggregated: false,
          startDate: dateKey,
          endDate: dateKey
        });
      }
    } else {
      const day = curr.getDay();
      const diff = curr.getDate() - day;
      const startOfFirstWeek = new Date(curr.setDate(diff));

      for (let i = 0; i < 4; i++) {
        const start = new Date(startOfFirstWeek);
        start.setDate(start.getDate() + (i * 7));
        const end = new Date(start);
        end.setDate(end.getDate() + 6);

        cols.push({
          key: `week-${i + 1}`,
          label: `WEEK ${i + 1}`,
          subLabel: `${start.getDate()} ${start.toLocaleString('default', { month: 'short' })} - ${end.getDate()} ${end.toLocaleString('default', { month: 'short' })}`,
          isAggregated: true,
          startDate: start.toISOString().split('T')[0],
          endDate: end.toISOString().split('T')[0]
        });
      }
    }
    return cols;
  }, [baseDate, viewType]);

  const filteredProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];

    let filtered = PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    if (category === 'Rocksalt') {
      filtered = filtered.filter(p => p !== 'Mixing' && p !== 'Sorting');
    } else if (category === 'Toothpaste') {
      filtered = filtered.filter(p => p !== 'Filling' && p !== 'Sorting');
    } else if (category === 'Cosmetic') {
      filtered = filtered.filter(p => p !== 'Sorting');
    }

    return filtered;
  }, [category]);

  const navigateDate = (direction: number) => {
    const d = new Date(baseDate);
    if (viewType === 'month') d.setMonth(d.getMonth() + direction);
    else d.setDate(d.getDate() + (direction * 7));
    setBaseDate(d.toISOString().split('T')[0]);
  };

  const handleAddNewAt = (date: string, process: string) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { 
      detail: { 
        id: '', date, process, category, productName: '', 
        planQuantity: 0, actualQuantity: 0, unit: 'KG', status: 'In Progress'
      } 
    }));
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header UI */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-2 uppercase tracking-tight">
            <CalendarIcon className="w-7 h-7 text-indigo-600" />
            Scheduling Matrix
          </h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
            {viewType === 'week' ? '4-Week Strategic Horizon' : 'Execution Day Grid'} • {category}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 flex shadow-sm">
            <button onClick={() => setViewType('month')} className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'month' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>Day Grid</button>
            <button onClick={() => setViewType('week')} className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'week' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>Week 1-4</button>
          </div>

          <div className="flex items-center gap-2 bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 shadow-sm">
            <button onClick={() => navigateDate(-1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400"><ChevronLeft className="w-4 h-4" /></button>
            <span className="text-[11px] font-black uppercase text-slate-700 dark:text-white px-4 min-w-[160px] text-center">{new Date(baseDate).toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
            <button onClick={() => navigateDate(1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400"><ChevronRight className="w-4 h-4" /></button>
          </div>
        </div>
      </div>

      {/* MATRIX WRAPPER WITH CUSTOM NAV ARROWS */}
      <div className="relative group/matrix">
        {/* Left Scroll Overlay */}
        <button 
          onClick={() => scrollMatrix('left')}
          className="absolute left-[240px] top-1/2 -translate-y-1/2 z-40 p-3 bg-white/90 dark:bg-slate-800/90 rounded-full shadow-2xl border border-slate-200 dark:border-slate-700 opacity-0 group-hover/matrix:opacity-100 transition-opacity hidden md:flex items-center justify-center hover:scale-110 active:scale-95 text-indigo-600"
        >
          <ArrowLeftCircle className="w-8 h-8" />
        </button>

        {/* Right Scroll Overlay */}
        <button 
          onClick={() => scrollMatrix('right')}
          className="absolute right-4 top-1/2 -translate-y-1/2 z-40 p-3 bg-white/90 dark:bg-slate-800/90 rounded-full shadow-2xl border border-slate-200 dark:border-slate-700 opacity-0 group-hover/matrix:opacity-100 transition-opacity hidden md:flex items-center justify-center hover:scale-110 active:scale-95 text-indigo-600"
        >
          <ArrowRightCircle className="w-8 h-8" />
        </button>

        {/* Scrollable Container */}
        <div 
          ref={scrollContainerRef}
          onMouseDown={handleMouseDown}
          onMouseLeave={handleMouseLeave}
          onMouseUp={handleMouseUp}
          onMouseMove={handleMouseMove}
          className={`bg-white dark:bg-slate-850 rounded-[2.5rem] shadow-2xl border-2 border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar relative ${isDragging ? 'cursor-grabbing select-none' : 'cursor-default'}`}
        >
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-900/50">
                <th className="sticky left-0 z-30 bg-slate-50 dark:bg-slate-900 p-8 text-left border-b-2 border-r-4 border-slate-200 dark:border-slate-700 min-w-[220px] shadow-[6px_0_15px_rgba(0,0,0,0.1)]">
                  <span className="text-[11px] font-black uppercase text-slate-500 tracking-[0.2em]">Process Node</span>
                </th>
                {columns.map(col => {
                  const isOff = !col.isAggregated && !!(getWeeklyOffDayType(col.key) || offDays.find(od => od.date === col.key));
                  return (
                    <th key={col.key} className={`p-5 text-center border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 min-w-[280px] last:border-r-0 ${isOff ? 'bg-slate-100/50 dark:bg-slate-800/30' : ''}`}>
                      <div className="flex flex-col items-center">
                        <span className={`text-sm font-black text-slate-800 dark:text-white mb-1 ${col.isAggregated ? 'text-indigo-600' : ''}`}>
                          {col.label}
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{col.subLabel}</span>
                      </div>
                    </th>
                  );
                })}
              </tr>
            </thead>
            <tbody>
              {filteredProcesses.map(proc => {
                const colors = PROCESS_COLORS[proc] || PROCESS_COLORS['Mixing'];
                return (
                  <tr key={proc} className="group hover:bg-slate-50/50 transition-colors">
                    {/* STICKY UNIFIED IDENTITY ANCHOR */}
                    <td className={`sticky left-0 z-20 p-8 border-b-2 border-r-4 border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-850 group-hover:bg-slate-50 dark:group-hover:bg-slate-800 transition-colors shadow-[6px_0_15px_rgba(0,0,0,0.06)] border-l-[14px] ${colors.border}`}>
                      <div className="flex flex-col">
                        <span className={`text-[14px] font-black uppercase tracking-[0.1em] mb-3 ${colors.text}`}>
                          {proc}
                        </span>
                        <div className={`w-14 h-2.5 rounded-full shadow-sm ${colors.bg}`}></div>
                      </div>
                    </td>

                    {/* Cells */}
                    {columns.map(col => {
                      const entries = productionData.filter(d => 
                        d.process === proc && 
                        d.category === category && 
                        d.date >= col.startDate && 
                        d.date <= col.endDate
                      );

                      const manualOff = !col.isAggregated ? offDays.find(od => od.date === col.key) : null;
                      const autoOff = !col.isAggregated ? getWeeklyOffDayType(col.key) : null;
                      const offType = manualOff?.type || autoOff;
                      const holidaysInPeriod = col.isAggregated ? offDays.filter(od => od.date >= col.startDate && od.date <= col.endDate).length : 0;

                      return (
                        <td key={`${col.key}-${proc}`} className={`p-4 border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 relative align-top min-h-[160px] last:border-r-0 ${offType ? 'bg-slate-100/30 dark:bg-slate-900/30' : colors.tint}`}>
                          {offType ? (
                             <div className="h-full py-10 flex items-center justify-center opacity-10">
                                <span className="text-[11px] font-black uppercase tracking-[0.3em] -rotate-12 border-2 border-current px-4 py-1.5 rounded-xl text-center leading-tight">
                                  {manualOff?.description || (autoOff === 'Rest Day' ? 'Friday Rest' : 'Saturday Off')}
                                </span>
                             </div>
                          ) : (
                            <div className="space-y-4">
                                {col.isAggregated && holidaysInPeriod > 0 && (
                                  <div className="flex items-center gap-2 mb-2">
                                    <div className="flex -space-x-1">
                                      {[...Array(holidaysInPeriod)].map((_, i) => (
                                        <div key={i} className="w-2 h-2 rounded-full bg-rose-500 shadow-sm border border-white" />
                                      ))}
                                    </div>
                                    <span className="text-[8px] font-black text-rose-500 uppercase tracking-tighter">{holidaysInPeriod} Holiday(s)</span>
                                  </div>
                                )}

                                {entries.length > 0 ? (
                                    entries.map(entry => (
                                        <div key={entry.id} className={`p-4 rounded-[1.5rem] border-2 transition-all relative overflow-hidden group/card shadow-sm ${
                                        entry.status === 'Completed' 
                                            ? 'bg-emerald-50/50 border-emerald-500/30 dark:bg-emerald-900/10' 
                                            : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700'
                                        }`}>
                                        <div className="flex justify-between items-start mb-2">
                                            <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-md ${
                                            entry.status === 'Completed' ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900 dark:text-indigo-300'
                                            }`}>
                                              {col.isAggregated ? formatDateToDMY(entry.date).split('-')[0] : ''} {entry.status === 'Completed' ? 'DONE' : 'PLAN'}
                                            </span>
                                            <span className="text-[9px] font-black font-mono text-slate-400">{entry.batchNo || '---'}</span>
                                        </div>
                                        <p className="text-[11px] font-black text-slate-800 dark:text-white leading-tight uppercase mb-2 break-words">
                                          {entry.productName}
                                        </p>
                                        <div className="flex justify-between items-end border-t border-slate-50 dark:border-slate-700/50 pt-2">
                                            <div className={`text-[10px] font-black ${colors.text}`}>
                                              {entry.planQuantity} <span className="text-[8px] opacity-60 uppercase font-bold">{entry.unit}</span>
                                            </div>
                                            {entry.actualQuantity > 0 && (
                                              <div className="text-[10px] font-black text-emerald-600 dark:text-emerald-400 flex flex-col items-end leading-none">
                                                  <span className="text-[7px] opacity-50 uppercase mb-0.5">Yield</span>
                                                  {entry.actualQuantity}
                                              </div>
                                            )}
                                        </div>
                                        </div>
                                    ))
                                ) : (
                                  <div className="h-12 flex items-center justify-center opacity-5 group-hover:opacity-20 transition-opacity">
                                    <Info className="w-4 h-4 text-slate-400" />
                                  </div>
                                )}
                                <button 
                                  onClick={() => handleAddNewAt(col.startDate, proc)}
                                  className={`w-full py-2 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-xl flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all hover:bg-white dark:hover:bg-slate-800/40 ${colors.text}`}
                                >
                                  <Plus className="w-3 h-3" />
                                </button>
                            </div>
                          )}
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay, ProductionStatus, OffDayType } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, List, Calendar, 
  Download, Pencil, Trash2, Layers,
  Palmtree, MessageSquare, ArrowUpDown, Coffee, Ban
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO, getWeeklyOffDayType } from '../../utils/dateUtils';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;
    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    // STRICT PROCESS FILTERING FOR DASHBOARD CARDS
    let validProcesses: string[] = [...PROCESSES];
    if (category !== 'Healthcare') {
      // Base non-healthcare exclusions
      validProcesses = validProcesses.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

      // Department-specific exclusions
      if (category === 'Rocksalt') {
        validProcesses = validProcesses.filter(p => p !== 'Mixing' && p !== 'Sorting');
      } else if (category === 'Toothpaste') {
        validProcesses = validProcesses.filter(p => p !== 'Filling' && p !== 'Sorting');
      } else if (category === 'Cosmetic') {
        validProcesses = validProcesses.filter(p => p !== 'Sorting');
      }
    }

    validProcesses.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);
        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const dates = new Set<string>();

    filteredEntries.forEach(e => {
        if (e.date) dates.add(e.date.trim().substring(0, 10));
    });

    offDays.forEach(od => {
        if (od.date && od.date.trim().startsWith(selectedMonth)) {
            dates.add(od.date.trim().substring(0, 10));
        }
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));
    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    return sortedDates.map(dateKey => {
        let entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);

        if (sortConfig) {
            entriesForDate = [...entriesForDate].sort((a, b) => {
                let aValue: any = a[sortConfig.key];
                let bValue: any = b[sortConfig.key];
                if (sortConfig.key === 'status') {
                    aValue = statusWeight[a.status as ProductionStatus] || 0;
                    bValue = statusWeight[b.status as ProductionStatus] || 0;
                }
                if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });
        }

        let offDayInfo = offDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);

        if (!offDayInfo) {
           const autoType = getWeeklyOffDayType(dateKey);
           if (autoType) {
               offDayInfo = {
                   id: `auto-${dateKey}`,
                   date: dateKey,
                   type: autoType,
                   description: autoType === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off',
                   createdBy: 'System'
               };
           }
        }

        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            offDay: offDayInfo
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth, sortConfig]);

  const handleDelete = async (id: string) => {
      if(!window.confirm("PERMANENTLY delete record?")) return;

      const result = await StorageService.deleteProductionEntry(id);
      const { deletedItem } = result;

      if (deletedItem) {
          // Explicitly await log entry before refreshing UI
          await StorageService.addLog({
            userId: user!.id, userName: user!.name, action: 'DELETE_RECORD',
            details: `Deleted: ${deletedItem.productName} (${deletedItem.date})`
          });
          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED', type: 'success' } 
          }));
      }
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const getOffDayIcon = (type: string) => {
    switch(type) {
      case 'Public Holiday': return <Palmtree className="w-6 h-6 text-rose-500" />;
      case 'Rest Day': return <Coffee className="w-6 h-6 text-indigo-500" />;
      case 'Off Day': return <Ban className="w-6 h-6 text-amber-500" />;
      default: return <Calendar className="w-6 h-6 text-slate-400" />;
    }
  };

  const getOffDayBadgeStyle = (type: string) => {
    switch(type) {
      case 'Public Holiday': return 'bg-rose-500 text-white shadow-rose-500/20';
      case 'Rest Day': return 'bg-indigo-500 text-white shadow-indigo-500/20';
      case 'Off Day': return 'bg-amber-500 text-white shadow-amber-500/20';
      default: return 'bg-slate-400 text-white';
    }
  };

  const SortHeader = ({ label, sortKey, align = 'left' }: { label: string, sortKey: keyof ProductionEntry, align?: 'left' | 'right' | 'center' }) => (
    <th className={`px-8 py-4 cursor-pointer group text-${align}`} onClick={() => handleSort(sortKey)}>
        <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : ''}`}>
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-8 pb-12">
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
            <Layers className="w-4 h-4 text-indigo-500" />
            <h3 className="text-[12px] font-black text-slate-400 uppercase tracking-[0.3em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-800 shadow-sm group hover:border-indigo-500/30 transition-all duration-300">
                        <div className="flex items-center justify-between mb-6">
                          <p className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{item.process}</p>
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse" />
                        </div>
                        <div className="space-y-5">
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Plan</span>
                                <span className="text-2xl font-black text-slate-800 dark:text-white font-mono">{(item.Plan || 0).toLocaleString()}</span>
                            </div>
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Actual</span>
                                <span className="text-2xl font-black text-emerald-500 font-mono">{(item.Actual || 0).toLocaleString()}</span>
                            </div>
                            <div className="pt-5 border-t border-gray-50 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Efficiency</span>
                                <span className={`text-xl font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(1)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">{selectedMonth} Operational granularity</p>
            </div>
            <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none" />
        </div>

        <div className="space-y-6">
            {dailyGroups.length === 0 ? (
                <div className="p-20 text-center glass-panel rounded-[2rem]">
                    <div className="inline-flex p-4 rounded-full bg-slate-50 dark:bg-slate-800 mb-4">
                        <ClipboardList className="w-10 h-10 text-slate-300" />
                    </div>
                    <p className="text-sm font-black text-slate-400 uppercase tracking-widest">No scheduled data for this month</p>
                </div>
            ) : dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');
                const isOff = !!group.offDay;

                const allCompleted = group.entries.length > 0 && group.entries.every(e => e.status === 'Completed');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-slate-850 rounded-[2rem] overflow-hidden shadow-sm border ${
                    isOff ? (
                        group.offDay?.type === 'Public Holiday' ? 'border-rose-400/30' :
                        group.offDay?.type === 'Rest Day' ? 'border-indigo-400/30' :
                        'border-amber-400/30'
                    ) : 'border-gray-100 dark:border-slate-800'
                  }`}>
                      <div className={`p-6 flex justify-between items-center border-b ${
                        isOff ? (
                            group.offDay?.type === 'Public Holiday' ? 'bg-rose-50/30 dark:bg-rose-900/10' :
                            group.offDay?.type === 'Rest Day' ? 'bg-indigo-50/30 dark:bg-indigo-900/10' :
                            'bg-amber-50/30 dark:bg-amber-900/10'
                        ) : 'bg-gray-50/50 dark:bg-slate-800/50'
                      }`}>
                          <div className="flex items-center gap-4">
                              {getOffDayIcon(group.offDay?.type || '')}
                              <div className="flex items-center gap-3">
                                <span className={`text-xl font-black text-slate-800 dark:text-white`}>{datePart}</span>
                                <span className="text-xl font-medium uppercase tracking-tight text-slate-400">{dayPart}</span>
                              </div>
                              {isOff && (
                                <div className="flex items-center gap-2">
                                    <span className={`px-3 py-1 text-[9px] font-black uppercase rounded-full shadow-sm tracking-widest ${getOffDayBadgeStyle(group.offDay!.type)}`}>
                                        {group.offDay!.type}
                                    </span>
                                    <span className="text-xs font-bold text-slate-500 dark:text-slate-400 truncate max-w-[150px]">
                                        {group.offDay!.description}
                                    </span>
                                </div>
                              )}
                          </div>

                          <div className="flex flex-col items-end gap-1.5">
                            <div className="px-4 py-1.5 bg-white dark:bg-slate-900 rounded-xl border border-gray-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-black text-[11px] uppercase tracking-widest shadow-sm">
                              Actual: <span className="text-emerald-500 ml-1 font-mono">{(group.totalActualForDate || 0).toLocaleString()}</span>
                            </div>
                            {group.entries.length > 0 && (
                              <div className={`px-2.5 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-tighter border shadow-sm ${
                                allCompleted ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-amber-50 text-emerald-600 border-emerald-100'
                              }`}>
                                {allCompleted ? 'All Jobs Completed' : 'Production In Progress'}
                              </div>
                            )}
                          </div>
                      </div>

                      {group.entries.length > 0 && (
                        <div className="overflow-x-auto no-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-gray-50 dark:border-slate-800 text-[9px] font-black text-slate-400 uppercase tracking-widest bg-gray-50/30 dark:bg-slate-900/30">
                                        <SortHeader label="Process" sortKey="process" />
                                        <SortHeader label="Product Name" sortKey="productName" />
                                        <th className="px-8 py-4 text-right font-black uppercase text-[10px] tracking-widest">Plan Data</th>
                                        <th className="px-8 py-4 text-right font-black uppercase text-[10px] tracking-widest">Actual Data</th>
                                        <th className="px-8 py-4 text-center font-black uppercase text-[10px] tracking-widest">Efficiency</th>
                                        <th className="px-8 py-4 text-center font-black uppercase text-[10px] tracking-widest">Batch No</th>
                                        <th className="px-8 py-4 text-center font-black uppercase text-[10px] tracking-widest">Manpower</th>
                                        {hasPermission(['admin', 'manager', 'hod']) && <th className="px-8 py-4 text-center font-black uppercase text-[10px] tracking-widest">Action</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => {
                                        const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                        return (
                                            <tr key={entry.id} className="hover:bg-gray-50/50 dark:hover:bg-slate-800/30 transition-colors">
                                                <td className="px-8 py-5">
                                                    <span className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase bg-indigo-50 dark:bg-indigo-900/30 px-2 py-1 rounded-lg border border-indigo-100 dark:border-indigo-800">{entry.process}</span>
                                                </td>
                                                <td className="px-8 py-5">
                                                    <span className="text-sm font-black text-slate-800 dark:text-white uppercase">{entry.productName}</span>
                                                </td>
                                                <td className="px-8 py-5 text-right font-black font-mono text-indigo-600/80 dark:text-indigo-400/80 text-sm">
                                                    <div>{(entry.planQuantity || 0).toLocaleString()} <span className="text-[9px] ml-1 opacity-60 font-sans">{entry.unit}</span></div>
                                                    {entry.planRemark && <div className="flex items-center justify-end gap-1 mt-1 opacity-70"><MessageSquare className="w-3 h-3 text-slate-300" /><span className="text-[9px] font-medium text-slate-400 italic max-w-[150px] truncate">{entry.planRemark}</span></div>}
                                                </td>
                                                <td className="px-8 py-5 text-right font-black font-mono text-emerald-500 text-sm">
                                                    <div>{(entry.actualQuantity || 0).toLocaleString()} <span className="text-[9px] ml-1 opacity-60 font-sans">{entry.unit}</span></div>
                                                    {entry.actualRemark && <div className="flex items-center justify-end gap-1 mt-1 opacity-70"><MessageSquare className="w-3 h-3 text-emerald-200" /><span className="text-[9px] font-medium text-emerald-400/80 italic max-w-[150px] truncate">{entry.actualRemark}</span></div>}
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className={`text-sm font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>{(eff || 0).toFixed(0)}%</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-[11px] font-bold text-slate-400 uppercase font-mono">{entry.batchNo || '-'}</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-base font-black text-slate-800 dark:text-white font-mono">{(entry.manpower || 0).toFixed(2)}</span>
                                                </td>
                                                {hasPermission(['admin', 'manager', 'hod']) && (
                                                  <td className="px-8 py-5 text-center">
                                                      <div className="flex items-center justify-center gap-2">
                                                          <button onClick={() => handleEdit(entry)} className="p-1.5 text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition"><Pencil className="w-4 h-4" /></button>
                                                          <button onClick={() => handleDelete(entry.id)} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition"><Trash2 className="w-4 h-4" /></button>
                                                      </div>
                                                  </td>
                                                )}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                      )}
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, 
  ResponsiveContainer, LineChart, Line, AreaChart, Area, ComposedChart,
  Cell, ScatterChart, Scatter, ZAxis
} from 'recharts';
import { 
  BarChart3, Activity, Target, Zap, 
  Filter, Calendar, TrendingUp, ArrowUpRight, 
  AlertTriangle, Users, Gauge, Info,
  ChevronRight, Thermometer
} from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const ProcessAnalytics: React.FC = () => {
  const { refreshKey, isDarkMode } = useDashboard();
  const [dateRange, setDateRange] = useState({ 
    start: new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0], 
    end: getTodayISO() 
  });
  const [selectedCategory, setSelectedCategory] = useState('All');

  const productionData = useMemo(() => StorageService.getProductionData(), [refreshKey]);

  const filteredData = useMemo(() => {
    return productionData.filter(d => {
      const matchCat = selectedCategory === 'All' || d.category === selectedCategory;
      const matchStart = !dateRange.start || d.date >= dateRange.start;
      const matchEnd = !dateRange.end || d.date <= dateRange.end;
      return matchCat && matchStart && matchEnd;
    });
  }, [productionData, dateRange, selectedCategory]);

  const analytics = useMemo(() => {
    const metrics: Record<string, { 
        process: string, 
        plan: number, 
        actual: number, 
        manpower: number,
        entries: number 
    }> = {};

    // Filter valid processes based on department
    let validProcesses = [...PROCESSES] as string[];
    if (selectedCategory !== 'All' && selectedCategory !== 'Healthcare') {
      validProcesses = PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));
      if (selectedCategory === 'Rocksalt') validProcesses = validProcesses.filter(p => p !== 'Mixing' && p !== 'Sorting');
      else if (selectedCategory === 'Toothpaste') validProcesses = validProcesses.filter(p => p !== 'Filling' && p !== 'Sorting');
      else if (selectedCategory === 'Cosmetic') validProcesses = validProcesses.filter(p => p !== 'Sorting');
    }

    validProcesses.forEach(p => {
      metrics[p] = { process: p, plan: 0, actual: 0, manpower: 0, entries: 0 };
    });

    filteredData.forEach(d => {
      if (metrics[d.process]) {
        metrics[d.process].plan += (d.planQuantity || 0);
        metrics[d.process].actual += (d.actualQuantity || 0);
        metrics[d.process].manpower += (d.manpower || 0);
        metrics[d.process].entries++;
      }
    });

    const processed = Object.values(metrics).map(m => {
        const efficiency = m.plan > 0 ? (m.actual / m.plan) * 100 : 0;
        const gap = m.plan - m.actual;
        const yieldPerPerson = m.manpower > 0 ? (m.actual / m.manpower) : 0;
        return { ...m, efficiency, gap, yieldPerPerson };
    });

    // IDENTIFY BOTTLENECK: Largest Gap or Lowest Efficiency with high Plan volume
    const bottleneck = [...processed].sort((a, b) => b.gap - a.gap)[0];
    const topPerformer = [...processed].sort((a, b) => b.efficiency - a.efficiency)[0];

    return { 
        metrics: processed.sort((a, b) => b.gap - a.gap), 
        bottleneck, 
        topPerformer 
    };
  }, [filteredData, selectedCategory]);

  const dailyTrend = useMemo(() => {
    const daily: Record<string, { date: string, plan: number, actual: number }> = {};
    filteredData.forEach(d => {
      if (!daily[d.date]) daily[d.date] = { date: d.date, plan: 0, actual: 0 };
      daily[d.date].plan += d.planQuantity;
      daily[d.date].actual += d.actualQuantity;
    });
    return Object.values(daily).sort((a, b) => a.date.localeCompare(b.date));
  }, [filteredData]);

  return (
    <div className="space-y-8 pb-20 animate-in fade-in duration-700">
      {/* Header section remains similar but updated titles */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <div className="p-2 bg-indigo-600 rounded-lg shadow-lg shadow-indigo-500/20">
              <Gauge className="w-5 h-5 text-white" />
            </div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-600 dark:text-indigo-400">Operational Scan</span>
          </div>
          <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tight">
            Manufacturing <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-violet-500">Intelligence</span>
          </h2>
        </div>

        <div className="flex flex-wrap items-center gap-3 bg-white dark:bg-slate-800 p-2 rounded-2xl shadow-xl border border-gray-100 dark:border-slate-700 w-full md:w-auto">
          <div className="flex items-center gap-2 bg-gray-50 dark:bg-slate-900 px-4 py-2.5 rounded-xl border border-gray-100 dark:border-slate-700">
            <Filter className="w-4 h-4 text-slate-400" />
            <select 
              value={selectedCategory} 
              onChange={e => setSelectedCategory(e.target.value)}
              className="bg-transparent text-xs font-black text-slate-600 dark:text-slate-200 outline-none uppercase tracking-widest cursor-pointer"
            >
              <option value="All">Global Factory</option>
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="flex items-center gap-3 bg-gray-50 dark:bg-slate-900 px-4 py-2.5 rounded-xl border border-gray-100 dark:border-slate-700">
            <Calendar className="w-4 h-4 text-slate-400" />
            <input 
                type="date" 
                value={dateRange.start} 
                onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))}
                className="bg-transparent text-[10px] font-black text-slate-600 dark:text-slate-200 outline-none uppercase"
            />
            <span className="text-slate-300 text-[10px] font-black">TO</span>
            <input 
                type="date" 
                value={dateRange.end} 
                onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))}
                className="bg-transparent text-[10px] font-black text-slate-600 dark:text-slate-200 outline-none uppercase"
            />
          </div>
        </div>
      </div>

      {/* INTELLIGENCE CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* BOTTLENECK ALERT */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-[2.5rem] border-2 border-rose-500/20 shadow-lg relative overflow-hidden group">
            <div className="absolute -right-4 -top-4 p-8 opacity-10 group-hover:scale-110 transition-transform duration-500">
                <AlertTriangle className="w-16 h-16 text-rose-500" />
            </div>
            <div className="flex items-center gap-2 mb-4">
                <span className="w-2 h-2 rounded-full bg-rose-500 animate-ping" />
                <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest">Active Bottleneck</p>
            </div>
            <h3 className="text-2xl font-black text-slate-800 dark:text-white uppercase tracking-tighter">
                {analytics.bottleneck?.process || 'STABLE'}
            </h3>
            <p className="text-[11px] font-bold text-slate-400 mt-1 uppercase tracking-widest leading-none">
                Variance: <span className="text-rose-500">{analytics.bottleneck?.gap.toLocaleString()} Units</span>
            </p>
            <div className="mt-4 flex items-center gap-2">
                <span className="px-2 py-1 bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400 text-[9px] font-black rounded-lg border border-rose-100 dark:border-rose-800 uppercase">
                    Action required
                </span>
            </div>
