import React, { createContext, useContext, useState, useEffect, ReactNode, useRef } from 'react';
import { User, Role } from '../types';
import { StorageService } from '../services/storageService';
import { hashPassword } from '../utils/securityUtils';

interface AuthContextType {
  user: User | null;
  login: (username: string, pass: string) => Promise<boolean>;
  logout: () => void;
  hasPermission: (roles: Role[]) => boolean;
  loginAttempts: number;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const MAX_ATTEMPTS = 5;
const COOLDOWN_TIME = 30000; // 30 seconds

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lastAttemptTime, setLastAttemptTime] = useState(0);
  // Fix: Replacing NodeJS.Timeout with number for browser compatibility as per frontend engineering standards
  const cooldownRef = useRef<number | null>(null);

  useEffect(() => {
    const session = StorageService.getSession();
    if (session) {
      setUser(session);
    }
  }, []);

  const login = async (username: string, pass: string): Promise<boolean> => {
    const now = Date.now();

    // Brute Force Protection
    if (loginAttempts >= MAX_ATTEMPTS && (now - lastAttemptTime) < COOLDOWN_TIME) {
      window.dispatchEvent(new CustomEvent('app-notification', { 
          detail: { message: `Too many attempts. Wait ${Math.ceil((COOLDOWN_TIME - (now - lastAttemptTime))/1000)}s`, type: 'info' } 
      }));
      return false;
    }

    if ((now - lastAttemptTime) > COOLDOWN_TIME) {
        setLoginAttempts(0);
    }

    setLastAttemptTime(now);

    const storedUsers = StorageService.getUsers();
    const cleanUsername = username.trim().toLowerCase();
    const targetUser = storedUsers.find(u => u.username === cleanUsername);

    if (targetUser) {
      const incomingHash = await hashPassword(pass);
      const isInitialUserPlaintext = !targetUser.password.match(/^[a-f0-9]{64}$/);

      // Check either hash or plaintext (for legacy migration)
      if (targetUser.password === incomingHash || (isInitialUserPlaintext && targetUser.password === pass)) {
        // Upgrade legacy plaintext passwords to hash on login
        if (isInitialUserPlaintext) {
            targetUser.password = incomingHash;
            StorageService.saveUsers(storedUsers);
        }

        setUser(targetUser);
        StorageService.setSession(targetUser);
        setLoginAttempts(0);
        return true;
      }
    }

    setLoginAttempts(prev => prev + 1);
    return false;
  };

  const logout = () => {
    setUser(null);
    StorageService.setSession(null);
  };

  const hasPermission = (allowedRoles: Role[]) => {
    if (!user) return false;
    return allowedRoles.includes(user.role);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, hasPermission, loginAttempts }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

/**
 * HALAGEL SECURITY UTILITIES
 * Implements Hashing and Sanitization for Pentest Compliance.
 */

/**
 * Creates a SHA-256 hash of a string.
 * Used for storing/comparing passwords securely.
 */
export async function hashPassword(password: string): Promise<string> {
  const msgUint8 = new TextEncoder().encode(password);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Basic XSS Protection: Strips HTML tags and scriptable characters.
 * Casts input to string to prevent runtime errors if non-string data is passed.
 */
export const sanitizeInput = (input: any): string => {
  if (input === null || input === undefined) return '';

  const strValue = String(input);
  if (!strValue) return '';

  return strValue
    .replace(/[<>]/g, '') // Remove < and >
    .replace(/javascript:/gi, '') // Block protocol injection
    .replace(/on\w+=/gi, '') // Block event handlers
    .trim();
};

/**
 * Prevents Prototype Pollution from malicious cloud data objects.
 */
export const deepFreeze = (obj: any) => {
  Object.getOwnPropertyNames(obj).forEach(name => {
    const prop = obj[name];
    if (prop !== null && typeof prop === 'object') deepFreeze(prop);
  });
  return Object.freeze(obj);
};

import { User, ProductionEntry, OffDay, ActivityLog, UnitType, ProductionStatus, OffDayType } from '../types';
import { INITIAL_USERS, INITIAL_OFF_DAYS, UNITS } from '../constants';
import { GoogleSheetsService } from './googleSheetsService';
import { getDbTimestamp } from '../utils/dateUtils';
import { sanitizeInput, hashPassword } from '../utils/securityUtils';

const KEYS = {
  USERS: 'halagel_users',
  PRODUCTION: 'halagel_production',
  OFF_DAYS: 'halagel_off_days',
  LOGS: 'halagel_activity_logs',
  CURRENT_USER: 'halagel_current_user_session',
  LAST_WRITE: 'halagel_last_write_timestamp'
};

const normalizeUnit = (u: any): UnitType => {
  if (u === undefined || u === null || u === '') return 'KG';
  const upper = String(u).trim().toUpperCase();
  const validUnits = UNITS as unknown as string[];
  return validUnits.includes(upper) ? (upper as UnitType) : 'KG';
};

const normalizeProduction = (data: any): ProductionEntry => {
  if (!data) return {} as ProductionEntry;
  let entry: Partial<ProductionEntry> = {};
  if (Array.isArray(data)) {
    const actualQty = Number(data[6] || 0);
    entry = {
      id: String(data[0] || Date.now()),
      date: String(data[1] || '').split(' ')[0],
      category: String(data[2] || 'Healthcare') as any,
      process: String(data[3] || 'Mixing') as any,
      productName: sanitizeInput(String(data[4] || 'Unknown')),
      planQuantity: Number(data[5] || 0),
      actualQuantity: actualQty,
      unit: normalizeUnit(data[7]),
      batchNo: sanitizeInput(String(data[8] || '')),
      manpower: Number(data[9] || 0),
      lastUpdatedBy: String(data[10] || ''),
      updatedAt: String(data[11] || getDbTimestamp()),
      remark: sanitizeInput(String(data[12] || '')),
      planRemark: sanitizeInput(String(data[13] || '')),
      actualRemark: sanitizeInput(String(data[14] || '')),
      status: (data[15] as ProductionStatus) || (actualQty > 0 ? 'Completed' : 'In Progress')
    };
  } else {
    entry = {
      ...data,
      id: String(data.id || Date.now()),
      date: String(data.date || '').split(' ')[0],
      productName: sanitizeInput(String(data.productName || '')),
      batchNo: sanitizeInput(String(data.batchNo || '')),
      planQuantity: Number(data.planQuantity || 0),
      actualQuantity: Number(data.actualQuantity || 0),
      unit: normalizeUnit(data.unit),
      updatedAt: String(data.updatedAt || getDbTimestamp())
    };
  }
  return entry as ProductionEntry;
};

const normalizeUser = (u: any): User => ({
  id: String(u.id || ''),
  name: sanitizeInput(String(u.name || '')),
  username: sanitizeInput(String(u.username || '')).toLowerCase(),
  role: (u.role || 'operator') as any,
  password: String(u.password || ''), // This is the hash
  avatar: String(u.avatar || '')
});

const setWriteLock = () => {
  localStorage.setItem(KEYS.LAST_WRITE, Date.now().toString());
};

const isWriteLocked = () => {
  const lastWrite = parseInt(localStorage.getItem(KEYS.LAST_WRITE) || '0');
  return (Date.now() - lastWrite) < 45000; 
};

const mergeById = <T extends { id: string, updatedAt?: string }>(local: T[], cloud: T[]): T[] => {
  const map = new Map<string, T>();
  cloud.forEach(item => map.set(String(item.id), item));
  local.forEach(item => {
    const existing = map.get(String(item.id));
    if (!existing || (item.updatedAt && existing.updatedAt && item.updatedAt > existing.updatedAt)) {
      map.set(String(item.id), item);
    }
  });
  return Array.from(map.values());
};

export const StorageService = {
  getUsers: (): User[] => {
    try {
      const raw = localStorage.getItem(KEYS.USERS);
      let list: User[] = [];
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed) && parsed.length > 0) {
          list = parsed.map(normalizeUser);
        }
      }

      // FAIL-SAFE & Migration: Ensure admin exists and password is ready for hashing comparison
      if (!list.some(u => u.username === 'admin')) {
        return INITIAL_USERS;
      }

      return list;
    } catch { 
      return INITIAL_USERS; 
    }
  },

  saveUsers: async (users: User[]) => {
    setWriteLock();
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    return await GoogleSheetsService.saveData('saveUsers', users);
  },

  getProductionData: (): ProductionEntry[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]');
      return Array.isArray(data) ? data.map(normalizeProduction).filter(p => p.date) : [];
    } catch { return []; }
  },

  saveProductionData: async (data: ProductionEntry[]) => {
    setWriteLock();
    const cleaned = data.map(normalizeProduction).filter(p => p.date);
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
    return await GoogleSheetsService.saveData('saveProduction', cleaned);
  },

  deleteProductionEntry: async (id: string): Promise<{ updatedData: ProductionEntry[], deletedItem: ProductionEntry | null }> => {
    const data = StorageService.getProductionData();
    const targetItem = data.find(p => String(p.id) === String(id)) || null;
    const updatedData = data.filter(p => String(p.id) !== String(id));
    await StorageService.saveProductionData(updatedData);
    return { updatedData, deletedItem: targetItem };
  },

  getOffDays: (): OffDay[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]');
      return Array.isArray(data) && data.length > 0 ? data : INITIAL_OFF_DAYS;
    } catch { return INITIAL_OFF_DAYS; }
  },

  saveOffDays: async (days: OffDay[]) => {
    setWriteLock();
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(days));
    return await GoogleSheetsService.saveData('saveOffDays', days);
  },

  syncWithSheets: async () => {
    if (!GoogleSheetsService.isEnabled()) return;
    if (isWriteLocked()) return;

    try {
      const results = await Promise.all([
        GoogleSheetsService.fetchData<any[]>('getProduction'),
        GoogleSheetsService.fetchData<any[]>('getOffDays'),
        GoogleSheetsService.fetchData<User[]>('getUsers'),
        GoogleSheetsService.fetchData<any[]>('getLogs')
      ]);

      if (results[0] && Array.isArray(results[0])) {
        const cloudProduction = results[0].map(normalizeProduction);
        const merged = mergeById(StorageService.getProductionData(), cloudProduction);
        localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(merged));
      }

      if (results[2] && Array.isArray(results[2]) && results[2].length > 0) {
        const cloudUsers = results[2].map(normalizeUser);
        const mergedUsers = mergeById(StorageService.getUsers(), cloudUsers);
        localStorage.setItem(KEYS.USERS, JSON.stringify(mergedUsers));
      }

      if (results[1] && Array.isArray(results[1]) && results[1].length > 0) {
        localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(results[1]));
      }
    } catch (err) {
      console.error("Background Sync Failure:", err);
    }
  },

  getLogs: (): ActivityLog[] => {
    try {
      const logs = JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]');
      return Array.isArray(logs) ? logs : [];
    } catch { return []; }
  },

  addLog: async (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    setWriteLock();
    const logs = StorageService.getLogs();
    const newLog = { 
        ...log, 
        details: sanitizeInput(String(log.details || '')),
        id: Date.now().toString(), 
        timestamp: getDbTimestamp() 
    };
    logs.unshift(newLog);
    if (logs.length > 500) logs.pop();
    localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
    return await GoogleSheetsService.saveData('saveLogs', [newLog, ...logs.slice(0, 49)]);
  },

  getSession: (): User | null => {
    try {
      const session = localStorage.getItem(KEYS.CURRENT_USER);
      return session ? JSON.parse(session) : null;
    } catch { return null; }
  },

  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
  }
};

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { 
  Calendar as CalendarIcon, 
  ChevronLeft, 
  ChevronRight, 
  Clock,
  CheckCircle2,
  Plus,
  Info,
  ArrowLeftCircle,
  ArrowRightCircle,
  AlertCircle
} from 'lucide-react';
import { formatDisplayDate, getTodayISO, getWeeklyOffDayType, formatDateToDMY } from '../../utils/dateUtils';

/**
 * UNIFIED PROCESS IDENTITY SYSTEM
 */
const PROCESS_COLORS: Record<string, { bg: string, text: string, border: string, tint: string }> = {
  'Mixing': { bg: 'bg-blue-600', text: 'text-blue-700', border: 'border-blue-600', tint: 'bg-blue-50/20' },
  'Encapsulation': { bg: 'bg-purple-600', text: 'text-purple-700', border: 'border-purple-600', tint: 'bg-purple-50/20' },
  'Filling': { bg: 'bg-emerald-600', text: 'text-emerald-700', border: 'border-emerald-600', tint: 'bg-emerald-50/20' },
  'Sorting': { bg: 'bg-slate-700', text: 'text-slate-800', border: 'border-slate-700', tint: 'bg-slate-100/30' },
  'Packing': { bg: 'bg-rose-600', text: 'text-rose-700', border: 'border-rose-600', tint: 'bg-rose-50/20' },
  'Blister': { bg: 'bg-indigo-600', text: 'text-indigo-700', border: 'border-indigo-600', tint: 'bg-indigo-50/20' },
  'Capsules': { bg: 'bg-amber-500', text: 'text-amber-700', border: 'border-amber-500', tint: 'bg-amber-50/20' },
};

export const ProductionCalendar: React.FC = () => {
  const { category, refreshKey } = useDashboard();
  const [viewType, setViewType] = useState<'month' | 'week'>('month');
  const [baseDate, setBaseDate] = useState(getTodayISO());

  // Refs for Drag-to-Scroll
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  // DRAG-TO-SCROLL LOGIC
  const handleMouseDown = (e: React.MouseEvent) => {
    if (!scrollContainerRef.current) return;
    setIsDragging(true);
    setStartX(e.pageX - scrollContainerRef.current.offsetLeft);
    setScrollLeft(scrollContainerRef.current.scrollLeft);
  };

  const handleMouseLeave = () => setIsDragging(false);
  const handleMouseUp = () => setIsDragging(false);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !scrollContainerRef.current) return;
    e.preventDefault();
    const x = e.pageX - scrollContainerRef.current.offsetLeft;
    const walk = (x - startX) * 2; // Scroll multiplier
    scrollContainerRef.current.scrollLeft = scrollLeft - walk;
  };

  const scrollMatrix = (direction: 'left' | 'right') => {
    if (!scrollContainerRef.current) return;
    const offset = direction === 'left' ? -400 : 400;
    scrollContainerRef.current.scrollTo({
      left: scrollContainerRef.current.scrollLeft + offset,
      behavior: 'smooth'
    });
  };

  const columns = useMemo(() => {
    const cols = [];
    const curr = new Date(baseDate);

    if (viewType === 'month') {
      const year = curr.getFullYear();
      const month = curr.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);
      for (let d = new Date(firstDay); d <= lastDay; d.setDate(d.getDate() + 1)) {
        const dateKey = d.toISOString().split('T')[0];
        const display = formatDisplayDate(dateKey);
        cols.push({
          key: dateKey,
          label: display.split(' ')[0],
          subLabel: display.split(' ')[1],
          isAggregated: false,
          startDate: dateKey,
          endDate: dateKey
        });
      }
    } else {
      const day = curr.getDay();
      const diff = curr.getDate() - day;
      const startOfFirstWeek = new Date(curr.setDate(diff));

      for (let i = 0; i < 4; i++) {
        const start = new Date(startOfFirstWeek);
        start.setDate(start.getDate() + (i * 7));
        const end = new Date(start);
        end.setDate(end.getDate() + 6);

        cols.push({
          key: `week-${i + 1}`,
          label: `WEEK ${i + 1}`,
          subLabel: `${start.getDate()} ${start.toLocaleString('default', { month: 'short' })} - ${end.getDate()} ${end.toLocaleString('default', { month: 'short' })}`,
          isAggregated: true,
          startDate: start.toISOString().split('T')[0],
          endDate: end.toISOString().split('T')[0]
        });
      }
    }
    return cols;
  }, [baseDate, viewType]);

  const filteredProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];

    let filtered = PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    if (category === 'Rocksalt') {
      filtered = filtered.filter(p => p !== 'Mixing' && p !== 'Sorting');
    } else if (category === 'Toothpaste') {
      filtered = filtered.filter(p => p !== 'Filling' && p !== 'Sorting');
    } else if (category === 'Cosmetic') {
      filtered = filtered.filter(p => p !== 'Sorting');
    }

    return filtered;
  }, [category]);

  const navigateDate = (direction: number) => {
    const d = new Date(baseDate);
    if (viewType === 'month') d.setMonth(d.getMonth() + direction);
    else d.setDate(d.getDate() + (direction * 7));
    setBaseDate(d.toISOString().split('T')[0]);
  };

  const handleAddNewAt = (date: string, process: string) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { 
      detail: { 
        id: '', date, process, category, productName: '', 
        planQuantity: 0, actualQuantity: 0, unit: 'KG', status: 'In Progress'
      } 
    }));
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header UI */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-2 uppercase tracking-tight">
            <CalendarIcon className="w-7 h-7 text-indigo-600" />
            Scheduling Matrix
          </h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
            {viewType === 'week' ? '4-Week Strategic Horizon' : 'Execution Day Grid'} • {category}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 flex shadow-sm">
            <button onClick={() => setViewType('month')} className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'month' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>Day Grid</button>
            <button onClick={() => setViewType('week')} className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'week' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>Week 1-4</button>
          </div>

          <div className="flex items-center gap-2 bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 shadow-sm">
            <button onClick={() => navigateDate(-1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400"><ChevronLeft className="w-4 h-4" /></button>
            <span className="text-[11px] font-black uppercase text-slate-700 dark:text-white px-4 min-w-[160px] text-center">{new Date(baseDate).toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
            <button onClick={() => navigateDate(1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400"><ChevronRight className="w-4 h-4" /></button>
          </div>
        </div>
      </div>

      {/* MATRIX WRAPPER WITH CUSTOM NAV ARROWS */}
      <div className="relative group/matrix">
        {/* Left Scroll Overlay */}
        <button 
          onClick={() => scrollMatrix('left')}
          className="absolute left-[240px] top-1/2 -translate-y-1/2 z-40 p-3 bg-white/90 dark:bg-slate-800/90 rounded-full shadow-2xl border border-slate-200 dark:border-slate-700 opacity-0 group-hover/matrix:opacity-100 transition-opacity hidden md:flex items-center justify-center hover:scale-110 active:scale-95 text-indigo-600"
        >
          <ArrowLeftCircle className="w-8 h-8" />
        </button>

        {/* Right Scroll Overlay */}
        <button 
          onClick={() => scrollMatrix('right')}
          className="absolute right-4 top-1/2 -translate-y-1/2 z-40 p-3 bg-white/90 dark:bg-slate-800/90 rounded-full shadow-2xl border border-slate-200 dark:border-slate-700 opacity-0 group-hover/matrix:opacity-100 transition-opacity hidden md:flex items-center justify-center hover:scale-110 active:scale-95 text-indigo-600"
        >
          <ArrowRightCircle className="w-8 h-8" />
        </button>

        {/* Scrollable Container */}
        <div 
          ref={scrollContainerRef}
          onMouseDown={handleMouseDown}
          onMouseLeave={handleMouseLeave}
          onMouseUp={handleMouseUp}
          onMouseMove={handleMouseMove}
          className={`bg-white dark:bg-slate-850 rounded-[2.5rem] shadow-2xl border-2 border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar relative ${isDragging ? 'cursor-grabbing select-none' : 'cursor-default'}`}
        >
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-900/50">
                <th className="sticky left-0 z-30 bg-slate-50 dark:bg-slate-900 p-8 text-left border-b-2 border-r-4 border-slate-200 dark:border-slate-700 min-w-[220px] shadow-[6px_0_15px_rgba(0,0,0,0.1)]">
                  <span className="text-[11px] font-black uppercase text-slate-500 tracking-[0.2em]">Process Node</span>
                </th>
                {columns.map(col => {
                  const isOff = !col.isAggregated && !!(getWeeklyOffDayType(col.key) || offDays.find(od => od.date === col.key));
                  return (
                    <th key={col.key} className={`p-5 text-center border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 min-w-[280px] last:border-r-0 ${isOff ? 'bg-slate-100/50 dark:bg-slate-800/30' : ''}`}>
                      <div className="flex flex-col items-center">
                        <span className={`text-sm font-black text-slate-800 dark:text-white mb-1 ${col.isAggregated ? 'text-indigo-600' : ''}`}>
                          {col.label}
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{col.subLabel}</span>
                      </div>
                    </th>
                  );
                })}
              </tr>
            </thead>
            <tbody>
              {filteredProcesses.map(proc => {
                const colors = PROCESS_COLORS[proc] || PROCESS_COLORS['Mixing'];
                return (
                  <tr key={proc} className="group hover:bg-slate-50/50 transition-colors">
                    {/* STICKY UNIFIED IDENTITY ANCHOR */}
                    <td className={`sticky left-0 z-20 p-8 border-b-2 border-r-4 border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-850 group-hover:bg-slate-50 dark:group-hover:bg-slate-800 transition-colors shadow-[6px_0_15px_rgba(0,0,0,0.06)] border-l-[14px] ${colors.border}`}>
                      <div className="flex flex-col">
                        <span className={`text-[14px] font-black uppercase tracking-[0.1em] mb-3 ${colors.text}`}>
                          {proc}
                        </span>
                        <div className={`w-14 h-2.5 rounded-full shadow-sm ${colors.bg}`}></div>
                      </div>
                    </td>

                    {/* Cells */}
                    {columns.map(col => {
                      const entries = productionData.filter(d => 
                        d.process === proc && 
                        d.category === category && 
                        d.date >= col.startDate && 
                        d.date <= col.endDate
                      );

                      const manualOff = !col.isAggregated ? offDays.find(od => od.date === col.key) : null;
                      const autoOff = !col.isAggregated ? getWeeklyOffDayType(col.key) : null;
                      const offType = manualOff?.type || autoOff;
                      const holidaysInPeriod = col.isAggregated ? offDays.filter(od => od.date >= col.startDate && od.date <= col.endDate).length : 0;

                      return (
                        <td key={`${col.key}-${proc}`} className={`p-4 border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 relative align-top min-h-[160px] last:border-r-0 ${offType ? 'bg-slate-100/30 dark:bg-slate-900/30' : colors.tint}`}>
                          <div className="space-y-4 relative z-10">
                              {/* OFF-DAY WATERMARK (Subtle text in background) */}
                              {offType && (
                                <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03] dark:opacity-[0.08] select-none z-0">
                                   <span className="text-[18px] font-black uppercase tracking-[0.4em] -rotate-12 border-4 border-current px-6 py-2 rounded-2xl text-center leading-tight whitespace-nowrap">
                                     {manualOff?.description || (autoOff === 'Rest Day' ? 'Rest Day' : 'Off Day')}
                                   </span>
                                </div>
                              )}

                              {col.isAggregated && holidaysInPeriod > 0 && (
                                <div className="flex items-center gap-2 mb-2 relative z-10">
                                  <div className="flex -space-x-1">
                                    {[...Array(holidaysInPeriod)].map((_, i) => (
                                      <div key={i} className="w-2 h-2 rounded-full bg-rose-500 shadow-sm border border-white" />
                                    ))}
                                  </div>
                                  <span className="text-[8px] font-black text-rose-500 uppercase tracking-tighter">{holidaysInPeriod} Holiday(s)</span>
                                </div>
                              )}

                              {entries.length > 0 ? (
                                  <div className="space-y-3 relative z-10">
                                      {entries.map(entry => (
                                          <div key={entry.id} className={`p-4 rounded-[1.5rem] border-2 transition-all relative overflow-hidden group/card shadow-sm ${
                                          entry.status === 'Completed' 
                                              ? 'bg-emerald-50/50 border-emerald-500/30 dark:bg-emerald-900/10' 
                                              : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700'
                                          }`}>
                                          <div className="flex justify-between items-start mb-2">
                                              <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-md flex items-center gap-1 ${
                                              entry.status === 'Completed' ? 'bg-emerald-500 text-white' : 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900 dark:text-indigo-300'
                                              }`}>
                                                {offType && <AlertCircle className="w-2 h-2" />}
                                                {col.isAggregated ? formatDateToDMY(entry.date).split('-')[0] : ''} {entry.status === 'Completed' ? 'DONE' : 'PLAN'}
                                              </span>
                                              <span className="text-[9px] font-black font-mono text-slate-400">{entry.batchNo || '---'}</span>
                                          </div>
                                          <p className="text-[11px] font-black text-slate-800 dark:text-white leading-tight uppercase mb-2 break-words">
                                            {entry.productName}
                                          </p>
                                          <div className="flex justify-between items-end border-t border-slate-50 dark:border-slate-700/50 pt-2">
                                              <div className={`text-[10px] font-black ${colors.text}`}>
                                                {entry.planQuantity} <span className="text-[8px] opacity-60 uppercase font-bold">{entry.unit}</span>
                                              </div>
                                              {entry.actualQuantity > 0 && (
                                                <div className="text-[10px] font-black text-emerald-600 dark:text-emerald-400 flex flex-col items-end leading-none">
                                                    <span className="text-[7px] opacity-50 uppercase mb-0.5">Yield</span>
                                                    {entry.actualQuantity}
                                                </div>
                                              )}
                                          </div>
                                          </div>
                                      ))}
                                  </div>
                              ) : !offType ? (
                                <div className="h-12 flex items-center justify-center opacity-5 group-hover:opacity-20 transition-opacity">
                                  <Info className="w-4 h-4 text-slate-400" />
                                </div>
                              ) : null}

                              <button 
                                onClick={() => handleAddNewAt(col.startDate, proc)}
                                className={`w-full py-2 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-xl flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all hover:bg-white dark:hover:bg-slate-800/40 relative z-10 ${colors.text}`}
                              >
                                <Plus className="w-3 h-3" />
                              </button>
                          </div>
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType, ProductionStatus, OffDay } from '../../types';
import { X, Loader2, Palmtree, MessageSquare, Ban, AlertCircle } from 'lucide-react';
import { getTodayISO, getDbTimestamp, getWeeklyOffDayType } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0.00');
  const [batchNo, setBatchNo] = useState('');
  const [planRemark, setPlanRemark] = useState('');
  const [actualRemark, setActualRemark] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);

  // Detection for both manual and automatic (Fri/Sat) off days
  const holidayInfo = useMemo(() => {
    const inputDate = (date || '').trim().split(' ')[0];
    const manual = offDays.find((od: OffDay) => (od.date || '').trim().split(' ')[0] === inputDate);
    if (manual) return manual;

    const autoType = getWeeklyOffDayType(inputDate);
    if (autoType) {
        return {
            type: autoType,
            description: autoType === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off'
        };
    }
    return null;
  }, [date, offDays]);

  const availableProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];

    let filtered = PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    if (category === 'Rocksalt') {
      filtered = filtered.filter(p => p !== 'Mixing' && p !== 'Sorting');
    } else if (category === 'Toothpaste') {
      filtered = filtered.filter(p => p !== 'Filling' && p !== 'Sorting');
    } else if (category === 'Cosmetic') {
      filtered = filtered.filter(p => p !== 'Sorting');
    }

    return filtered as ProcessType[];
  }, [category]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (!availableProcesses.includes(process)) {
      setProcess(availableProcesses[0]);
    }
  }, [category, availableProcesses, process]);

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');

      if (editEntry.actualQuantity > 0) {
        setTab('Actual');
        setQuantity(editEntry.actualQuantity.toString());
      } else {
        setTab('Plan');
        setQuantity(editEntry.planQuantity.toString());
      }

      setManpower(editEntry.manpower ? Number(editEntry.manpower).toFixed(2) : '0.00');
      setBatchNo(editEntry.batchNo || '');
      setPlanRemark(editEntry.planRemark || '');
      setActualRemark(editEntry.actualRemark || '');
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const normalizedInputDate = (date || '').trim().split(' ')[0];
        const relevant = all.filter((p: ProductionEntry) => (p.date || '').trim().split(' ')[0] === normalizedInputDate);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const normalizedDate = (date || '').trim().split(' ')[0];
    const currentData = StorageService.getProductionData();

    try {
        if (editEntry) {
            const updated = currentData.map((p: ProductionEntry) => {
                if (p.id === editEntry.id) {
                    const newQty = parseInt(quantity || '0');
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? newQty : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? newQty : p.actualQuantity,
                        batchNo, manpower: parseFloat(manpower || '0'),
                        planRemark,
                        actualRemark,
                        status: (tab === 'Actual' && newQty > 0 ? 'Completed' : p.status) as ProductionStatus,
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    } as ProductionEntry;
                }
                return p;
            });
            await StorageService.saveProductionData(updated);
            await StorageService.addLog({
                userId: user!.id,
                userName: user!.name,
                action: 'EDIT_RECORD',
                details: `Modified record for ${productName} (${normalizedDate})`
            });
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, unit,
                    planQuantity: parseInt(quantity || '0'), actualQuantity: 0,
                    planRemark,
                    actualRemark: '',
                    status: 'In Progress',
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                await StorageService.saveProductionData([...currentData, newEntry]);
                await StorageService.addLog({
                    userId: user!.id,
                    userName: user!.name,
                    action: 'CREATE_PLAN',
                    details: `Planned ${newEntry.planQuantity} ${unit} for ${newEntry.productName}`
                });
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const updated = currentData.map((p: ProductionEntry) => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity || '0'), 
                            unit, batchNo, manpower: parseFloat(manpower || '0'),
                            actualRemark, status: 'Completed' as ProductionStatus,
                            lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                        } as ProductionEntry;
                    }
                    return p;
                });
                await StorageService.saveProductionData(updated);
                await StorageService.addLog({
                    userId: user!.id,
                    userName: user!.name,
                    action: 'RECORD_ACTUAL',
                    details: `Recorded ${quantity} ${unit} for ${productName} (Batch: ${batchNo})`
                });
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: tab === 'Actual' ? 'PRODUCTION COMPLETED' : 'PLAN SAVED', type: 'success' } 
        }));
        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Operation failed', type: 'info' } }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative max-h-[90vh] flex flex-col">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-[60] flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
