import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { ProductionEntry, Category, ProcessType, UnitType } from '../../types';
import { AlertCircle, CheckCircle2, Palmtree, MessageSquare } from 'lucide-react';
import { getTodayISO, getWeeklyOffDayType } from '../../utils/dateUtils';

interface PlanFormState {
  date: string;
  category: Category;
  process: ProcessType;
  productName: string;
  quantity: string;
  unit: UnitType;
  planRemark: string;
}

export const InputPlan: React.FC = () => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();

  const [formData, setFormData] = useState<PlanFormState>({
    date: getTodayISO(),
    category: CATEGORIES[0] as Category,
    process: PROCESSES[0] as ProcessType,
    productName: '',
    quantity: '',
    unit: UNITS[0] as UnitType,
    planRemark: ''
  });
  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => {
    const manual = offDays.find(od => od.date === formData.date);
    if (manual) return manual;
    const auto = getWeeklyOffDayType(formData.date);
    if (auto) return { type: auto, description: auto === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off' };
    return null;
  }, [formData.date, offDays]);

  useEffect(() => {
    if (currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `REST DAY ALERT: ${currentOffDay.description}`, type: 'info' } 
        }));
    }
  }, [currentOffDay]);

  const availableProcesses = useMemo(() => {
    if (formData.category === 'Healthcare') return [...PROCESSES] as ProcessType[];

    let filtered = PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    if (formData.category === 'Rocksalt') {
      filtered = filtered.filter(p => p !== 'Mixing' && p !== 'Sorting');
    } else if (formData.category === 'Toothpaste') {
      filtered = filtered.filter(p => p !== 'Filling' && p !== 'Sorting');
    } else if (formData.category === 'Cosmetic') {
      filtered = filtered.filter(p => p !== 'Sorting');
    }

    return filtered as ProcessType[];
  }, [formData.category]);

  useEffect(() => {
    if (!availableProcesses.includes(formData.process)) {
      setFormData(prev => ({ ...prev, process: availableProcesses[0] }));
    }
  }, [availableProcesses, formData.process]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.productName || !formData.quantity) {
      setMsg({ type: 'error', text: 'Please fill all required fields.' });
      return;
    }

    try {
      const entries = StorageService.getProductionData();

      const newEntry: ProductionEntry = {
        id: Date.now().toString(),
        date: formData.date,
        category: formData.category,
        process: formData.process,
        productName: formData.productName,
        planQuantity: parseInt(formData.quantity),
        actualQuantity: 0,
        unit: formData.unit,
        planRemark: formData.planRemark,
        status: 'In Progress',
        lastUpdatedBy: user!.id,
        updatedAt: new Date().toISOString()
      };

      StorageService.saveProductionData([...entries, newEntry]);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'CREATE_PLAN',
        details: `Planned ${newEntry.planQuantity} ${newEntry.unit} for ${newEntry.productName} on ${newEntry.date}`
      });

      triggerRefresh();
      setMsg({ type: 'success', text: 'Plan entry added successfully.' });
      setFormData(prev => ({ ...prev, productName: '', quantity: '', planRemark: '' }));

      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'PRODUCTION PLAN SUBMITTED', type: 'success' } 
      }));
    } catch (err) {
      setMsg({ type: 'error', text: 'Failed to save data.' });
    }
  };

  return (
    <div className="max-w-2xl mx-auto py-8">
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-gray-100 dark:border-slate-700 p-10 animate-in fade-in slide-in-from-bottom-4">
        <div className="flex items-center gap-4 mb-8">
          <div className="p-3 bg-indigo-100 dark:bg-indigo-900/40 rounded-2xl">
            <MessageSquare className="w-8 h-8 text-indigo-600 dark:text-indigo-400" />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-800 dark:text-white">New Production Plan</h2>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Initialize production targets</p>
          </div>
        </div>

        {msg && (
          <div className={`p-5 rounded-2xl mb-8 flex items-center gap-4 animate-pulse ${msg.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-rose-50 text-rose-700 border border-rose-100'}`}>
            {msg.type === 'success' ? <CheckCircle2 className="w-6 h-6" /> : <AlertCircle className="w-6 h-6" />}
            <span className="font-bold text-sm uppercase tracking-tight">{msg.text}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Production Date</label>
              <input 
                type="date" 
                required
                className="w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-indigo-500/20"
                value={formData.date}
                onChange={e => setFormData({...formData, date: e.target.value})}
              />

              {currentOffDay && (
                <div className="mt-4 p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-2xl flex items-center gap-4">
                  <Palmtree className="w-6 h-6 text-amber-500 shrink-0" />
                  <div className="flex-1">
                    <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none mb-1">{currentOffDay.type} Alert</p>
                    <p className="text-xs font-black text-slate-800 dark:text-amber-100">{currentOffDay.description}</p>
                  </div>
                </div>
              )}
            </div>

            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Department</label>
              <select 
                className="w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-indigo-500/20"
                value={formData.category}
                onChange={e => setFormData({...formData, category: e.target.value as Category})}
              >
                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Process Node</label>
              <select 
                className="w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-indigo-500/20"
                value={formData.process}
                onChange={e => setFormData({...formData, process: e.target.value as ProcessType})}
              >
                {availableProcesses.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>

            <div className="space-y-2">
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Planned Quantity</label>
              <div className="flex gap-2">
                <input 
                  type="number" 
                  min="1"
                  required
                  placeholder="0"
                  className="flex-1 p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-indigo-500/20"
                  value={formData.quantity}
                  onChange={e => setFormData({...formData, quantity: e.target.value})}
                />
                <select 
                  className="w-24 p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none"
                  value={formData.unit}
                  onChange={e => setFormData({...formData, unit: e.target.value as UnitType})}
                >
                  {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Product Description</label>
            <input 
              type="text" 
              required
              placeholder="E.G. TOOTHPASTE HERBAL 150G"
              className="w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-indigo-500/20"
              value={formData.productName}
              onChange={e => setFormData({...formData, productName: e.target.value.toUpperCase()})}
            />
          </div>

          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Planning Remark</label>
            <textarea 
              placeholder="OPTIONAL PLANNING NOTES..."
              className="w-full p-4 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white h-32 resize-none font-bold outline-none focus:ring-2 focus:ring-indigo-500/20"
              value={formData.planRemark}
              onChange={e => setFormData({...formData, planRemark: e.target.value.toUpperCase()})}
            />
          </div>

          <div className="pt-6">
            <button 
              type="submit"
              className="w-full bg-slate-900 dark:bg-indigo-600 text-white font-black py-4 rounded-2xl hover:opacity-90 transition-all shadow-xl shadow-indigo-500/10 uppercase tracking-[0.2em] text-sm"
            >
              Secure Plan Entry
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { ProductionEntry } from '../../types';
import { AlertCircle, CheckCircle2, Palmtree, ClipboardCheck, Users } from 'lucide-react';
import { getTodayISO, getWeeklyOffDayType } from '../../utils/dateUtils';

export const InputActual: React.FC = () => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [date, setDate] = useState(getTodayISO());

  const [pendingPlans, setPendingPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const [formData, setFormData] = useState({
    actualQty: '',
    manpower: '0.00',
    batchNo: '',
    actualRemark: ''
  });

  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => {
    const manual = offDays.find(od => od.date === date);
    if (manual) return manual;
    const auto = getWeeklyOffDayType(date);
    if (auto) return { type: auto, description: auto === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off' };
    return null;
  }, [date, offDays]);

  useEffect(() => {
    const all = StorageService.getProductionData();
    const forDate = all.filter(p => p.date === date);
    setPendingPlans(forDate);
    setSelectedPlanId('');
    setFormData({ actualQty: '', manpower: '0.00', batchNo: '', actualRemark: '' });
  }, [date]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedPlanId) {
      setMsg({ type: 'error', text: 'Please select a job node to update.' });
      return;
    }

    try {
      const allData = StorageService.getProductionData();
      const updatedData = allData.map(entry => {
        if (entry.id === selectedPlanId) {
          return {
            ...entry,
            actualQuantity: parseInt(formData.actualQty || '0'),
            manpower: parseFloat(formData.manpower || '0'),
            batchNo: formData.batchNo,
            actualRemark: formData.actualRemark,
            status: 'Completed' as const,
            lastUpdatedBy: user!.id,
            updatedAt: new Date().toISOString()
          };
        }
        return entry;
      });

      StorageService.saveProductionData(updatedData);

      const target = allData.find(e => e.id === selectedPlanId);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'RECORD_ACTUAL',
        details: `Recorded output for ${target?.productName}: ${formData.actualQty} units with ${parseFloat(formData.manpower).toFixed(2)} manpower`
      });

      triggerRefresh();
      setMsg({ type: 'success', text: 'Production record updated and synchronized.' });

      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'ACTUAL PRODUCTION SYNCHRONIZED', type: 'success' } 
      }));

      // Refresh pending list
      setPendingPlans(updatedData.filter(p => p.date === date));
    } catch (err) {
      setMsg({ type: 'error', text: 'Error communicating with storage.' });
    }
  };

  const inputClasses = "w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-emerald-500/20";

  return (
    <div className="max-w-2xl mx-auto py-8">
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-gray-100 dark:border-slate-700 p-10 animate-in fade-in slide-in-from-bottom-4">
        <div className="flex items-center gap-4 mb-8">
          <div className="p-3 bg-emerald-100 dark:bg-emerald-900/40 rounded-2xl">
            <ClipboardCheck className="w-8 h-8 text-emerald-600 dark:text-emerald-400" />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-800 dark:text-white">Record Production</h2>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Verify floor output and resources</p>
          </div>
        </div>

        {msg && (
          <div className={`p-5 rounded-2xl mb-8 flex items-center gap-4 animate-pulse ${msg.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-rose-50 text-rose-700 border border-rose-100'}`}>
            {msg.type === 'success' ? <CheckCircle2 className="w-6 h-6" /> : <AlertCircle className="w-6 h-6" />}
            <span className="font-bold text-sm uppercase tracking-tight">{msg.text}</span>
          </div>
        )}

        <div className="mb-8">
          <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Review Date</label>
          <input 
            type="date" 
            className={inputClasses}
            value={date}
            onChange={e => setDate(e.target.value)}
          />

          {currentOffDay && (
            <div className="mt-4 p-5 bg-amber-50 dark:bg-amber-900/30 border border-amber-300 dark:border-amber-700 rounded-2xl flex items-center gap-4">
              <Palmtree className="w-8 h-8 text-amber-500 shrink-0" />
              <div>
                <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none mb-1">{currentOffDay.type} Alert</p>
                <p className="text-sm font-black text-slate-900 dark:text-amber-50">{currentOffDay.description}</p>
              </div>
            </div>
          )}
        </div>

        <div className="mb-8">
          <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Select Pending Job Node</label>
          {pendingPlans.length === 0 ? (
            <div className="text-sm text-slate-400 font-bold italic p-8 border-2 border-dashed border-slate-100 dark:border-slate-700 rounded-2xl text-center">
              No active plans found for this date.
            </div>
          ) : (
            <div className="space-y-3 max-h-60 overflow-y-auto custom-scrollbar border border-slate-100 dark:border-slate-700 rounded-2xl p-3 bg-slate-50/50 dark:bg-slate-900/50">
              {pendingPlans.map(plan => (
                <div 
                  key={plan.id}
                  onClick={() => {
                    setSelectedPlanId(plan.id);
                    setFormData(prev => ({ 
                      ...prev, 
                      actualQty: plan.actualQuantity ? plan.actualQuantity.toString() : '',
                      manpower: plan.manpower ? plan.manpower.toFixed(2) : '0.00',
                      batchNo: plan.batchNo || '',
                      actualRemark: plan.actualRemark || ''
                    }));
                  }}
                  className={`p-4 rounded-xl cursor-pointer border-2 transition-all ${
                    selectedPlanId === plan.id 
                      ? 'bg-emerald-50 border-emerald-500 shadow-md ring-4 ring-emerald-500/10 dark:bg-emerald-900/20' 
                      : 'bg-white dark:bg-slate-800 border-transparent hover:border-slate-200 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="flex justify-between items-center mb-1">
                    <span className="font-black text-slate-800 dark:text-white uppercase tracking-tight">{plan.productName}</span>
                    <span className="text-[9px] font-black uppercase px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400">{plan.category}</span>
                  </div>
                  <div className="flex justify-between items-end">
                    <span className="text-[10px] font-bold text-indigo-500 dark:text-indigo-400 uppercase tracking-widest">{plan.process}</span>
                    <div className="text-[11px] font-black text-slate-400 uppercase">Target: <span className="text-slate-800 dark:text-white">{plan.planQuantity} {plan.unit}</span></div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {selectedPlanId && (
          <form onSubmit={handleSubmit} className="space-y-6 animate-in slide-in-from-top-4 duration-300">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Actual Yield Qty</label>
                <input 
                  type="number" 
                  min="0"
                  required
                  className={inputClasses.replace('font-bold', 'font-black')}
                  value={formData.actualQty}
                  onChange={e => setFormData({...formData, actualQty: e.target.value})}
                />
              </div>

              <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1 flex items-center gap-1.5">
                  <Users className="w-3 h-3" /> Manpower (2 Decimals)
                </label>
                <input 
                  type="number" 
                  step="0.01"
                  min="0"
                  required
                  className={inputClasses}
                  value={formData.manpower}
                  onBlur={() => setFormData(prev => ({...prev, manpower: parseFloat(prev.manpower || '0').toFixed(2)}))}
                  onChange={e => setFormData({...formData, manpower: e.target.value})}
                />
              </div>
            </div>

            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Official Batch Number</label>
              <input 
                type="text" 
                required
                placeholder="ENTER LOT / BATCH ID..."
                className={inputClasses.replace('font-bold', 'font-black font-mono')}
                value={formData.batchNo}
                onChange={e => setFormData({...formData, batchNo: e.target.value.toUpperCase()})}
              />
            </div>

            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Actual Result Remark</label>
              <textarea 
                placeholder="ENTER DISCREPANCIES OR FLOOR NOTES..."
                className="w-full p-4 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white h-32 resize-none font-bold outline-none focus:ring-2 focus:ring-emerald-500/20"
                value={formData.actualRemark}
                onChange={e => setFormData({...formData, actualRemark: e.target.value.toUpperCase()})}
              />
            </div>

            <button 
              type="submit"
              className="w-full bg-emerald-600 text-white font-black py-4 rounded-2xl hover:opacity-90 transition-all shadow-xl shadow-emerald-500/20 uppercase tracking-[0.2em] text-sm"
            >
              Verify & Synchronize Record
            </button>
          </form>
        )}
      </div>
    </div>
  );
};

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { 
  Calendar as CalendarIcon, 
  ChevronLeft, 
  ChevronRight, 
  Clock,
  CheckCircle2,
  Plus,
  Info,
  ArrowLeftCircle,
  ArrowRightCircle,
  AlertCircle
} from 'lucide-react';
import { formatDisplayDate, getTodayISO, getWeeklyOffDayType, formatDateToDMY } from '../../utils/dateUtils';

/**
 * UNIFIED PROCESS IDENTITY SYSTEM
 */
const PROCESS_COLORS: Record<string, { bg: string, text: string, border: string, tint: string }> = {
  'Mixing': { bg: 'bg-blue-600', text: 'text-blue-700', border: 'border-blue-600', tint: 'bg-blue-50/20' },
  'Encapsulation': { bg: 'bg-purple-600', text: 'text-purple-700', border: 'border-purple-600', tint: 'bg-purple-50/20' },
  'Filling': { bg: 'bg-emerald-600', text: 'text-emerald-700', border: 'border-emerald-600', tint: 'bg-emerald-50/20' },
  'Sorting': { bg: 'bg-slate-700', text: 'text-slate-800', border: 'border-slate-700', tint: 'bg-slate-100/30' },
  'Packing': { bg: 'bg-rose-600', text: 'text-rose-700', border: 'border-rose-600', tint: 'bg-rose-50/20' },
  'Blister': { bg: 'bg-indigo-600', text: 'text-indigo-700', border: 'border-indigo-600', tint: 'bg-indigo-50/20' },
  'Capsules': { bg: 'bg-amber-500', text: 'text-amber-700', border: 'border-amber-500', tint: 'bg-amber-50/20' },
};

export const ProductionCalendar: React.FC = () => {
  const { category, refreshKey } = useDashboard();
  const [viewType, setViewType] = useState<'month' | 'week'>('month');
  const [baseDate, setBaseDate] = useState(getTodayISO());

  // Refs for Drag-to-Scroll
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  // DRAG-TO-SCROLL LOGIC
  const handleMouseDown = (e: React.MouseEvent) => {
    if (!scrollContainerRef.current) return;
    setIsDragging(true);
    setStartX(e.pageX - scrollContainerRef.current.offsetLeft);
    setScrollLeft(scrollContainerRef.current.scrollLeft);
  };

  const handleMouseLeave = () => setIsDragging(false);
  const handleMouseUp = () => setIsDragging(false);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !scrollContainerRef.current) return;
    e.preventDefault();
    const x = e.pageX - scrollContainerRef.current.offsetLeft;
    const walk = (x - startX) * 2; // Scroll multiplier
    scrollContainerRef.current.scrollLeft = scrollLeft - walk;
  };

  const scrollMatrix = (direction: 'left' | 'right') => {
    if (!scrollContainerRef.current) return;
    const offset = direction === 'left' ? -400 : 400;
    scrollContainerRef.current.scrollTo({
      left: scrollContainerRef.current.scrollLeft + offset,
      behavior: 'smooth'
    });
  };

  const columns = useMemo(() => {
    const cols = [];
    const curr = new Date(baseDate);

    if (viewType === 'month') {
      const year = curr.getFullYear();
      const month = curr.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);
      for (let d = new Date(firstDay); d <= lastDay; d.setDate(d.getDate() + 1)) {
        const dateKey = d.toISOString().split('T')[0];
        const display = formatDisplayDate(dateKey);
        cols.push({
          key: dateKey,
          label: display.split(' ')[0],
          subLabel: display.split(' ')[1],
          isAggregated: false,
          startDate: dateKey,
          endDate: dateKey
        });
      }
    } else {
      const day = curr.getDay();
      const diff = curr.getDate() - day;
      const startOfFirstWeek = new Date(curr.setDate(diff));

      for (let i = 0; i < 4; i++) {
        const start = new Date(startOfFirstWeek);
        start.setDate(start.getDate() + (i * 7));
        const end = new Date(start);
        end.setDate(end.getDate() + 6);

        cols.push({
          key: `week-${i + 1}`,
          label: `WEEK ${i + 1}`,
          subLabel: `${start.getDate()} ${start.toLocaleString('default', { month: 'short' })} - ${end.getDate()} ${end.toLocaleString('default', { month: 'short' })}`,
          isAggregated: true,
          startDate: start.toISOString().split('T')[0],
          endDate: end.toISOString().split('T')[0]
        });
      }
    }
    return cols;
  }, [baseDate, viewType]);

  const filteredProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];

    let filtered = PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    if (category === 'Rocksalt') {
      filtered = filtered.filter(p => p !== 'Mixing' && p !== 'Sorting');
    } else if (category === 'Toothpaste') {
      filtered = filtered.filter(p => p !== 'Filling' && p !== 'Sorting');
    } else if (category === 'Cosmetic') {
      filtered = filtered.filter(p => p !== 'Sorting');
    }

    return filtered;
  }, [category]);

  const navigateDate = (direction: number) => {
    const d = new Date(baseDate);
    if (viewType === 'month') d.setMonth(d.getMonth() + direction);
    else d.setDate(d.getDate() + (direction * 7));
    setBaseDate(d.toISOString().split('T')[0]);
  };

  const handleAddNewAt = (date: string, process: string) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { 
      detail: { 
        id: '', date, process, category, productName: '', 
        planQuantity: 0, actualQuantity: 0, unit: 'KG', status: 'In Progress'
      } 
    }));
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header UI */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-2 uppercase tracking-tight">
            <CalendarIcon className="w-7 h-7 text-indigo-600" />
            Scheduling Matrix
          </h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
            {viewType === 'week' ? '4-Week Strategic Horizon' : 'Execution Day Grid'} • {category}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 flex shadow-sm">
            <button onClick={() => setViewType('month')} className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'month' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>Day Grid</button>
            <button onClick={() => setViewType('week')} className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'week' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>Week 1-4</button>
          </div>

          <div className="flex items-center gap-2 bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 shadow-sm">
            <button onClick={() => navigateDate(-1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400"><ChevronLeft className="w-4 h-4" /></button>
            <span className="text-[11px] font-black uppercase text-slate-700 dark:text-white px-4 min-w-[160px] text-center">{new Date(baseDate).toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
            <button onClick={() => navigateDate(1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400"><ChevronRight className="w-4 h-4" /></button>
          </div>
        </div>
      </div>

      {/* MATRIX WRAPPER WITH CUSTOM NAV ARROWS */}
      <div className="relative group/matrix">
        {/* Left Scroll Overlay */}
        <button 
          onClick={() => scrollMatrix('left')}
          className="absolute left-[240px] top-1/2 -translate-y-1/2 z-40 p-3 bg-white/90 dark:bg-slate-800/90 rounded-full shadow-2xl border border-slate-200 dark:border-slate-700 opacity-0 group-hover/matrix:opacity-100 transition-opacity hidden md:flex items-center justify-center hover:scale-110 active:scale-95 text-indigo-600"
        >
          <ArrowLeftCircle className="w-8 h-8" />
        </button>

        {/* Right Scroll Overlay */}
        <button 
          onClick={() => scrollMatrix('right')}
          className="absolute right-4 top-1/2 -translate-y-1/2 z-40 p-3 bg-white/90 dark:bg-slate-800/90 rounded-full shadow-2xl border border-slate-200 dark:border-slate-700 opacity-0 group-hover/matrix:opacity-100 transition-opacity hidden md:flex items-center justify-center hover:scale-110 active:scale-95 text-indigo-600"
        >
          <ArrowRightCircle className="w-8 h-8" />
        </button>

        {/* Scrollable Container */}
        <div 
          ref={scrollContainerRef}
          onMouseDown={handleMouseDown}
          onMouseLeave={handleMouseLeave}
          onMouseUp={handleMouseUp}
          onMouseMove={handleMouseMove}
          className={`bg-white dark:bg-slate-850 rounded-[2.5rem] shadow-2xl border-2 border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar relative ${isDragging ? 'cursor-grabbing select-none' : 'cursor-default'}`}
        >
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-900/50">
                <th className="sticky left-0 z-30 bg-slate-50 dark:bg-slate-900 p-8 text-left border-b-2 border-r-4 border-slate-200 dark:border-slate-700 min-w-[220px] shadow-[6px_0_15px_rgba(0,0,0,0.1)]">
                  <span className="text-[11px] font-black uppercase text-slate-500 tracking-[0.2em]">Process Node</span>
                </th>
                {columns.map(col => {
                  const isOff = !col.isAggregated && !!(getWeeklyOffDayType(col.key) || offDays.find(od => od.date === col.key));
                  return (
                    <th key={col.key} className={`p-5 text-center border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 min-w-[280px] last:border-r-0 ${isOff ? 'bg-slate-100/50 dark:bg-slate-800/30' : ''}`}>
                      <div className="flex flex-col items-center">
                        <span className={`text-sm font-black text-slate-800 dark:text-white mb-1 ${col.isAggregated ? 'text-indigo-600' : ''}`}>
                          {col.label}
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{col.subLabel}</span>
                      </div>
                    </th>
                  );
                })}
              </tr>
            </thead>
            <tbody>
              {filteredProcesses.map(proc => {
                const colors = PROCESS_COLORS[proc] || PROCESS_COLORS['Mixing'];
                return (
                  <tr key={proc} className="group hover:bg-slate-50/50 transition-colors">
                    {/* STICKY UNIFIED IDENTITY ANCHOR */}
                    <td className={`sticky left-0 z-20 p-8 border-b-2 border-r-4 border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-850 group-hover:bg-slate-50 dark:group-hover:bg-slate-800 transition-colors shadow-[6px_0_15px_rgba(0,0,0,0.06)] border-l-[14px] ${colors.border}`}>
                      <div className="flex flex-col">
                        <span className={`text-[14px] font-black uppercase tracking-[0.1em] mb-3 ${colors.text}`}>
                          {proc}
                        </span>
                        <div className={`w-14 h-2.5 rounded-full shadow-sm ${colors.bg}`}></div>
                      </div>
                    </td>

                    {/* Cells */}
                    {columns.map(col => {
                      const entries = productionData.filter(d => 
                        d.process === proc && 
                        d.category === category && 
                        d.date >= col.startDate && 
                        d.date <= col.endDate
                      );

                      const manualOff = !col.isAggregated ? offDays.find(od => od.date === col.key) : null;
                      const autoOff = !col.isAggregated ? getWeeklyOffDayType(col.key) : null;
                      const offType = manualOff?.type || autoOff;
                      const holidaysInPeriod = col.isAggregated ? offDays.filter(od => od.date >= col.startDate && od.date <= col.endDate).length : 0;

                      return (
                        <td key={`${col.key}-${proc}`} className={`p-4 border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 relative align-top min-h-[160px] last:border-r-0 ${offType ? 'bg-slate-100/30 dark:bg-slate-900/30' : colors.tint}`}>
                          <div className="space-y-4 relative z-10">
                              {/* OFF-DAY WATERMARK (Subtle text in background) */}
                              {offType && (
                                <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03] dark:opacity-[0.08] select-none z-0">
                                   <span className="text-[18px] font-black uppercase tracking-[0.4em] -rotate-12 border-4 border-current px-6 py-2 rounded-2xl text-center leading-tight whitespace-nowrap">
                                     {manualOff?.description || (autoOff === 'Rest Day' ? 'Rest Day' : 'Off Day')}
                                   </span>
                                </div>
                              )}

                              {col.isAggregated && holidaysInPeriod > 0 && (
                                <div className="flex items-center gap-2 mb-2 relative z-10">
                                  <div className="flex -space-x-1">
                                    {[...Array(holidaysInPeriod)].map((_, i) => (
                                      <div key={i} className="w-2 h-2 rounded-full bg-rose-500 shadow-sm border border-white" />
                                    ))}
                                  </div>
                                  <span className="text-[8px] font-black text-rose-500 uppercase tracking-tighter">{holidaysInPeriod} Holiday(s)</span>
                                </div>
                              )}

                              {entries.length > 0 ? (
                                  <div className="space-y-3 relative z-10">
                                      {entries.map(entry => {
                                          const entryOffType = col.isAggregated 
                                            ? (offDays.find(od => od.date === entry.date)?.type || getWeeklyOffDayType(entry.date))
                                            : offType;

                                          return (
                                              <div key={entry.id} className={`p-4 rounded-[1.5rem] border-2 transition-all relative overflow-hidden group/card shadow-sm ${
                                              entry.status === 'Completed' 
                                                  ? 'bg-emerald-50/50 border-emerald-500/30 dark:bg-emerald-900/10' 
                                                  : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700'
                                              }`}>
                                              <div className="flex justify-between items-start mb-2">
                                                  <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-md flex items-center gap-1 ${
                                                  entry.status === 'Completed' 
                                                    ? 'bg-emerald-500 text-white' 
                                                    : (entryOffType ? 'bg-amber-100 text-amber-700 border border-amber-200' : 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900 dark:text-indigo-300')
                                                  }`}>
                                                    {entryOffType && <AlertCircle className="w-2 h-2" />}
                                                    {col.isAggregated ? formatDateToDMY(entry.date).split('-')[0] : ''} {entryOffType ? 'OT ' : ''}{entry.status === 'Completed' ? 'DONE' : 'PLAN'}
                                                  </span>
                                                  <span className="text-[9px] font-black font-mono text-slate-400">{entry.batchNo || '---'}</span>
                                              </div>
                                              <p className="text-[11px] font-black text-slate-800 dark:text-white leading-tight uppercase mb-2 break-words">
                                                {entry.productName}
                                              </p>
                                              <div className="flex justify-between items-end border-t border-slate-50 dark:border-slate-700/50 pt-2">
                                                  <div className={`text-[10px] font-black ${colors.text}`}>
                                                    {entry.planQuantity} <span className="text-[8px] opacity-60 uppercase font-bold">{entry.unit}</span>
                                                  </div>
                                                  {entry.actualQuantity > 0 && (
                                                    <div className="text-[10px] font-black text-emerald-600 dark:text-emerald-400 flex flex-col items-end leading-none">
                                                        <span className="text-[7px] opacity-50 uppercase mb-0.5">Yield</span>
                                                        {entry.actualQuantity}
                                                    </div>
                                                  )}
                                              </div>
                                              </div>
                                          );
                                      })}
                                  </div>
                              ) : !offType ? (
                                <div className="h-12 flex items-center justify-center opacity-5 group-hover:opacity-20 transition-opacity">
                                  <Info className="w-4 h-4 text-slate-400" />
                                </div>
                              ) : null}

                              <button 
                                onClick={() => handleAddNewAt(col.startDate, proc)}
                                className={`w-full py-2 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-xl flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all hover:bg-white dark:hover:bg-slate-800/40 relative z-10 ${colors.text}`}
                              >
                                <Plus className="w-3 h-3" />
                              </button>
                          </div>
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { 
  Calendar as CalendarIcon, 
  ChevronLeft, 
  ChevronRight, 
  Clock,
  CheckCircle2,
  Plus,
  Info,
  ArrowLeftCircle,
  ArrowRightCircle,
  AlertCircle
} from 'lucide-react';
import { formatDisplayDate, getTodayISO, getWeeklyOffDayType, formatDateToDMY } from '../../utils/dateUtils';

/**
 * UNIFIED PROCESS IDENTITY SYSTEM
 */
const PROCESS_COLORS: Record<string, { bg: string, text: string, border: string, tint: string }> = {
  'Mixing': { bg: 'bg-blue-600', text: 'text-blue-700', border: 'border-blue-600', tint: 'bg-blue-50/20' },
  'Encapsulation': { bg: 'bg-purple-600', text: 'text-purple-700', border: 'border-purple-600', tint: 'bg-purple-50/20' },
  'Filling': { bg: 'bg-emerald-600', text: 'text-emerald-700', border: 'border-emerald-600', tint: 'bg-emerald-50/20' },
  'Sorting': { bg: 'bg-slate-700', text: 'text-slate-800', border: 'border-slate-700', tint: 'bg-slate-100/30' },
  'Packing': { bg: 'bg-rose-600', text: 'text-rose-700', border: 'border-rose-600', tint: 'bg-rose-50/20' },
  'Blister': { bg: 'bg-indigo-600', text: 'text-indigo-700', border: 'border-indigo-600', tint: 'bg-indigo-50/20' },
  'Capsules': { bg: 'bg-amber-500', text: 'text-amber-700', border: 'border-amber-500', tint: 'bg-amber-50/20' },
};

export const ProductionCalendar: React.FC = () => {
  const { category, refreshKey } = useDashboard();
  const [viewType, setViewType] = useState<'month' | 'week'>('month');
  const [baseDate, setBaseDate] = useState(getTodayISO());

  // Refs for Drag-to-Scroll
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  // DRAG-TO-SCROLL LOGIC
  const handleMouseDown = (e: React.MouseEvent) => {
    if (!scrollContainerRef.current) return;
    setIsDragging(true);
    setStartX(e.pageX - scrollContainerRef.current.offsetLeft);
    setScrollLeft(scrollContainerRef.current.scrollLeft);
  };

  const handleMouseLeave = () => setIsDragging(false);
  const handleMouseUp = () => setIsDragging(false);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !scrollContainerRef.current) return;
    e.preventDefault();
    const x = e.pageX - scrollContainerRef.current.offsetLeft;
    const walk = (x - startX) * 2; // Scroll multiplier
    scrollContainerRef.current.scrollLeft = scrollLeft - walk;
  };

  const scrollMatrix = (direction: 'left' | 'right') => {
    if (!scrollContainerRef.current) return;
    const offset = direction === 'left' ? -400 : 400;
    scrollContainerRef.current.scrollTo({
      left: scrollContainerRef.current.scrollLeft + offset,
      behavior: 'smooth'
    });
  };

  const columns = useMemo(() => {
    const cols = [];
    const curr = new Date(baseDate);

    if (viewType === 'month') {
      const year = curr.getFullYear();
      const month = curr.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);
      for (let d = new Date(firstDay); d <= lastDay; d.setDate(d.getDate() + 1)) {
        const dateKey = d.toISOString().split('T')[0];
        const display = formatDisplayDate(dateKey);
        cols.push({
          key: dateKey,
          label: display.split(' ')[0],
          subLabel: display.split(' ')[1],
          isAggregated: false,
          startDate: dateKey,
          endDate: dateKey
        });
      }
    } else {
      const day = curr.getDay();
      const diff = curr.getDate() - day;
      const startOfFirstWeek = new Date(curr.setDate(diff));

      for (let i = 0; i < 4; i++) {
        const start = new Date(startOfFirstWeek);
        start.setDate(start.getDate() + (i * 7));
        const end = new Date(start);
        end.setDate(end.getDate() + 6);

        cols.push({
          key: `week-${i + 1}`,
          label: `WEEK ${i + 1}`,
          subLabel: `${start.getDate()} ${start.toLocaleString('default', { month: 'short' })} - ${end.getDate()} ${end.toLocaleString('default', { month: 'short' })}`,
          isAggregated: true,
          startDate: start.toISOString().split('T')[0],
          endDate: end.toISOString().split('T')[0]
        });
      }
    }
    return cols;
  }, [baseDate, viewType]);

  const filteredProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];

    let filtered = PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    if (category === 'Rocksalt') {
      filtered = filtered.filter(p => p !== 'Mixing' && p !== 'Sorting');
    } else if (category === 'Toothpaste') {
      filtered = filtered.filter(p => p !== 'Filling' && p !== 'Sorting');
    } else if (category === 'Cosmetic') {
      filtered = filtered.filter(p => p !== 'Sorting');
    }

    return filtered;
  }, [category]);

  const navigateDate = (direction: number) => {
    const d = new Date(baseDate);
    if (viewType === 'month') d.setMonth(d.getMonth() + direction);
    else d.setDate(d.getDate() + (direction * 7));
    setBaseDate(d.toISOString().split('T')[0]);
  };

  const handleAddNewAt = (date: string, process: string) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { 
      detail: { 
        id: '', date, process, category, productName: '', 
        planQuantity: 0, actualQuantity: 0, unit: 'KG', status: 'In Progress'
      } 
    }));
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header UI */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-2 uppercase tracking-tight">
            <CalendarIcon className="w-7 h-7 text-indigo-600" />
            Scheduling Matrix
          </h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
            {viewType === 'week' ? '4-Week Strategic Horizon' : 'Execution Day Grid'} • {category}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 flex shadow-sm">
            <button onClick={() => setViewType('month')} className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'month' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>Day Grid</button>
            <button onClick={() => setViewType('week')} className={`px-5 py-2 text-[10px] font-black uppercase rounded-xl transition-all ${viewType === 'week' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>Week 1-4</button>
          </div>

          <div className="flex items-center gap-2 bg-white dark:bg-slate-850 p-1.5 rounded-2xl border-2 border-slate-100 dark:border-slate-800 shadow-sm">
            <button onClick={() => navigateDate(-1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400"><ChevronLeft className="w-4 h-4" /></button>
            <span className="text-[11px] font-black uppercase text-slate-700 dark:text-white px-4 min-w-[160px] text-center">{new Date(baseDate).toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
            <button onClick={() => navigateDate(1)} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl text-slate-400"><ChevronRight className="w-4 h-4" /></button>
          </div>
        </div>
      </div>

      {/* MATRIX WRAPPER WITH CUSTOM NAV ARROWS */}
      <div className="relative group/matrix">
        {/* Left Scroll Overlay */}
        <button 
          onClick={() => scrollMatrix('left')}
          className="absolute left-[240px] top-1/2 -translate-y-1/2 z-40 p-3 bg-white/90 dark:bg-slate-800/90 rounded-full shadow-2xl border border-slate-200 dark:border-slate-700 opacity-0 group-hover/matrix:opacity-100 transition-opacity hidden md:flex items-center justify-center hover:scale-110 active:scale-95 text-indigo-600"
        >
          <ArrowLeftCircle className="w-8 h-8" />
        </button>

        {/* Right Scroll Overlay */}
        <button 
          onClick={() => scrollMatrix('right')}
          className="absolute right-4 top-1/2 -translate-y-1/2 z-40 p-3 bg-white/90 dark:bg-slate-800/90 rounded-full shadow-2xl border border-slate-200 dark:border-slate-700 opacity-0 group-hover/matrix:opacity-100 transition-opacity hidden md:flex items-center justify-center hover:scale-110 active:scale-95 text-indigo-600"
        >
          <ArrowRightCircle className="w-8 h-8" />
        </button>

        {/* Scrollable Container */}
        <div 
          ref={scrollContainerRef}
          onMouseDown={handleMouseDown}
          onMouseLeave={handleMouseLeave}
          onMouseUp={handleMouseUp}
          onMouseMove={handleMouseMove}
          className={`bg-white dark:bg-slate-850 rounded-[2.5rem] shadow-2xl border-2 border-slate-200 dark:border-slate-700 overflow-x-auto custom-scrollbar relative ${isDragging ? 'cursor-grabbing select-none' : 'cursor-default'}`}
        >
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-900/50">
                <th className="sticky left-0 z-30 bg-slate-50 dark:bg-slate-900 p-8 text-left border-b-2 border-r-4 border-slate-200 dark:border-slate-700 min-w-[220px] shadow-[6px_0_15px_rgba(0,0,0,0.1)]">
                  <span className="text-[11px] font-black uppercase text-slate-500 tracking-[0.2em]">Process Node</span>
                </th>
                {columns.map(col => {
                  const isOff = !col.isAggregated && !!(getWeeklyOffDayType(col.key) || offDays.find(od => od.date === col.key));
                  return (
                    <th key={col.key} className={`p-5 text-center border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 min-w-[280px] last:border-r-0 ${isOff ? 'bg-slate-100/50 dark:bg-slate-800/30' : ''}`}>
                      <div className="flex flex-col items-center">
                        <span className={`text-sm font-black text-slate-800 dark:text-white mb-1 ${col.isAggregated ? 'text-indigo-600' : ''}`}>
                          {col.label}
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{col.subLabel}</span>
                      </div>
                    </th>
                  );
                })}
              </tr>
            </thead>
            <tbody>
              {filteredProcesses.map(proc => {
                const colors = PROCESS_COLORS[proc] || PROCESS_COLORS['Mixing'];
                return (
                  <tr key={proc} className="group hover:bg-slate-50/50 transition-colors">
                    {/* STICKY UNIFIED IDENTITY ANCHOR */}
                    <td className={`sticky left-0 z-20 p-8 border-b-2 border-r-4 border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-850 group-hover:bg-slate-50 dark:group-hover:bg-slate-800 transition-colors shadow-[6px_0_15px_rgba(0,0,0,0.06)] border-l-[14px] ${colors.border}`}>
                      <div className="flex flex-col">
                        <span className={`text-[14px] font-black uppercase tracking-[0.1em] mb-3 ${colors.text}`}>
                          {proc}
                        </span>
                        <div className={`w-14 h-2.5 rounded-full shadow-sm ${colors.bg}`}></div>
                      </div>
                    </td>

                    {/* Cells */}
                    {columns.map(col => {
                      const entries = productionData.filter(d => 
                        d.process === proc && 
                        d.category === category && 
                        d.date >= col.startDate && 
                        d.date <= col.endDate
                      );

                      const manualOff = !col.isAggregated ? offDays.find(od => od.date === col.key) : null;
                      const autoOff = !col.isAggregated ? getWeeklyOffDayType(col.key) : null;
                      const offType = manualOff?.type || autoOff;
                      const holidaysInPeriod = col.isAggregated ? offDays.filter(od => od.date >= col.startDate && od.date <= col.endDate).length : 0;

                      return (
                        <td key={`${col.key}-${proc}`} className={`p-4 border-b-2 border-r-[3px] border-slate-200 dark:border-slate-700 relative align-top min-h-[160px] last:border-r-0 ${offType ? 'bg-slate-100/30 dark:bg-slate-900/30' : colors.tint}`}>
                          <div className="space-y-4 relative z-10">
                              {/* OFF-DAY WATERMARK (Subtle text in background) */}
                              {offType && (
                                <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03] dark:opacity-[0.08] select-none z-0">
                                   <span className="text-[18px] font-black uppercase tracking-[0.4em] -rotate-12 border-4 border-current px-6 py-2 rounded-2xl text-center leading-tight whitespace-nowrap">
                                     {manualOff?.description || (autoOff === 'Rest Day' ? 'Rest Day' : 'Off Day')}
                                   </span>
                                </div>
                              )}

                              {col.isAggregated && holidaysInPeriod > 0 && (
                                <div className="flex items-center gap-2 mb-2 relative z-10">
                                  <div className="flex -space-x-1">
                                    {[...Array(holidaysInPeriod)].map((_, i) => (
                                      <div key={i} className="w-2 h-2 rounded-full bg-rose-500 shadow-sm border border-white" />
                                    ))}
                                  </div>
                                  <span className="text-[8px] font-black text-rose-500 uppercase tracking-tighter">{holidaysInPeriod} Holiday(s)</span>
                                </div>
                              )}

                              {entries.length > 0 ? (
                                  <div className="space-y-3 relative z-10">
                                      {entries.map(entry => {
                                          const entryOffType = col.isAggregated 
                                            ? (offDays.find(od => od.date === entry.date)?.type || getWeeklyOffDayType(entry.date))
                                            : offType;

                                          return (
                                              <div key={entry.id} className={`p-4 rounded-[1.5rem] border-2 transition-all relative overflow-hidden group/card shadow-sm ${
                                              entry.status === 'Completed' 
                                                  ? 'bg-emerald-50/50 border-emerald-500/30 dark:bg-emerald-900/10' 
                                                  : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700'
                                              }`}>
                                              <div className="flex justify-between items-start mb-2">
                                                  <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-md flex items-center gap-1 ${
                                                  entry.status === 'Completed' 
                                                    ? 'bg-emerald-500 text-white' 
                                                    : (entryOffType ? 'bg-amber-100 text-amber-700 border border-amber-200' : 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900 dark:text-indigo-300')
                                                  }`}>
                                                    {entryOffType && <AlertCircle className="w-2 h-2" />}
                                                    {col.isAggregated ? formatDateToDMY(entry.date).split('-')[0] : ''} {entryOffType ? 'OT ' : ''}{entry.status === 'Completed' ? 'DONE' : 'PLAN'}
                                                  </span>
                                                  <span className="text-[9px] font-black font-mono text-slate-400">{entry.batchNo || '---'}</span>
                                              </div>
                                              <p className="text-[11px] font-black text-slate-800 dark:text-white leading-tight uppercase mb-2 break-words">
                                                {entry.productName}
                                              </p>
                                              <div className="flex justify-between items-end border-t border-slate-50 dark:border-slate-700/50 pt-2">
                                                  <div className={`text-[10px] font-black ${colors.text}`}>
                                                    {entry.planQuantity} <span className="text-[8px] opacity-60 uppercase font-bold">{entry.unit}</span>
                                                  </div>
                                                  {entry.actualQuantity > 0 && (
                                                    <div className="text-[10px] font-black text-emerald-600 dark:text-emerald-400 flex flex-col items-end leading-none">
                                                        <span className="text-[7px] opacity-50 uppercase mb-0.5">Actual</span>
                                                        {entry.actualQuantity}
                                                    </div>
                                                  )}
                                              </div>
                                              </div>
                                          );
                                      })}
                                  </div>
                              ) : !offType ? (
                                <div className="h-12 flex items-center justify-center opacity-5 group-hover:opacity-20 transition-opacity">
                                  <Info className="w-4 h-4 text-slate-400" />
                                </div>
                              ) : null}

                              <button 
                                onClick={() => handleAddNewAt(col.startDate, proc)}
                                className={`w-full py-2 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-xl flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all hover:bg-white dark:hover:bg-slate-800/40 relative z-10 ${colors.text}`}
                              >
                                <Plus className="w-3 h-3" />
                              </button>
                          </div>
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType, ProductionStatus, OffDay } from '../../types';
import { X, Loader2, Palmtree, MessageSquare, Ban, AlertCircle, Building2 } from 'lucide-react';
import { getTodayISO, getDbTimestamp, getWeeklyOffDayType } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0.00');
  const [batchNo, setBatchNo] = useState('');
  const [planRemark, setPlanRemark] = useState('');
  const [actualRemark, setActualRemark] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);

  // Detection for both manual and automatic (Fri/Sat) off days
  const holidayInfo = useMemo(() => {
    const inputDate = (date || '').trim().split(' ')[0];
    const manual = offDays.find((od: OffDay) => (od.date || '').trim().split(' ')[0] === inputDate);
    if (manual) return manual;

    const autoType = getWeeklyOffDayType(inputDate);
    if (autoType) {
        return {
            type: autoType,
            description: autoType === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off'
        };
    }
    return null;
  }, [date, offDays]);

  const availableProcesses = useMemo(() => {
    if (category === 'Healthcare') return [...PROCESSES];

    let filtered = PROCESSES.filter(p => !['Encapsulation', 'Blister', 'Capsules'].includes(p));

    if (category === 'Rocksalt') {
      filtered = filtered.filter(p => p !== 'Mixing' && p !== 'Sorting');
    } else if (category === 'Toothpaste') {
      filtered = filtered.filter(p => p !== 'Filling' && p !== 'Sorting');
    } else if (category === 'Cosmetic') {
      filtered = filtered.filter(p => p !== 'Sorting');
    }

    return filtered as ProcessType[];
  }, [category]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (!availableProcesses.includes(process)) {
      setProcess(availableProcesses[0]);
    }
  }, [category, availableProcesses, process]);

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');

      if (editEntry.actualQuantity > 0) {
        setTab('Actual');
        setQuantity(editEntry.actualQuantity.toString());
      } else {
        setTab('Plan');
        setQuantity(editEntry.planQuantity.toString());
      }

      setManpower(editEntry.manpower ? Number(editEntry.manpower).toFixed(2) : '0.00');
      setBatchNo(editEntry.batchNo || '');
      setPlanRemark(editEntry.planRemark || '');
      setActualRemark(editEntry.actualRemark || '');
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const normalizedInputDate = (date || '').trim().split(' ')[0];
        const relevant = all.filter((p: ProductionEntry) => (p.date || '').trim().split(' ')[0] === normalizedInputDate);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  // Derived filtered list of plans based on selected category in Actual tab
  const filteredPlans = useMemo(() => {
    if (tab !== 'Actual') return [];
    return plans.filter(p => p.category === category);
  }, [plans, category, tab]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const normalizedDate = (date || '').trim().split(' ')[0];
    const currentData = StorageService.getProductionData();

    try {
        if (editEntry) {
            const updated = currentData.map((p: ProductionEntry) => {
                if (p.id === editEntry.id) {
                    const newQty = parseInt(quantity || '0');
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? newQty : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? newQty : p.actualQuantity,
                        batchNo, manpower: parseFloat(manpower || '0'),
                        planRemark,
                        actualRemark,
                        status: (tab === 'Actual' && newQty > 0 ? 'Completed' : p.status) as ProductionStatus,
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    } as ProductionEntry;
                }
                return p;
            });
            await StorageService.saveProductionData(updated);
            await StorageService.addLog({
                userId: user!.id,
                userName: user!.name,
                action: 'EDIT_RECORD',
                details: `Modified record for ${productName} (${normalizedDate})`
            });
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, unit,
                    planQuantity: parseInt(quantity || '0'), actualQuantity: 0,
                    planRemark,
                    actualRemark: '',
                    status: 'In Progress',
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                await StorageService.saveProductionData([...currentData, newEntry]);
                await StorageService.addLog({
                    userId: user!.id,
                    userName: user!.name,
                    action: 'CREATE_PLAN',
                    details: `Planned ${newEntry.planQuantity} ${unit} for ${newEntry.productName}`
                });
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const updated = currentData.map((p: ProductionEntry) => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity || '0'), 
                            unit, batchNo, manpower: parseFloat(manpower || '0'),
                            actualRemark, status: 'Completed' as ProductionStatus,
                            lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                        } as ProductionEntry;
                    }
                    return p;
                });
                await StorageService.saveProductionData(updated);
                await StorageService.addLog({
                    userId: user!.id,
                    userName: user!.name,
                    action: 'RECORD_ACTUAL',
                    details: `Recorded ${quantity} ${unit} for ${productName} (Batch: ${batchNo})`
                });
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: tab === 'Actual' ? 'PRODUCTION COMPLETED' : 'PLAN SAVED', type: 'success' } 
        }));
        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Operation failed', type: 'info' } }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative max-h-[90vh] flex flex-col">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-[60] flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Uploading to Cloud...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700 shrink-0">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        1. Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-50 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        2. Record Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 flex overflow-hidden">
                <button onClick={() => setTab('Plan')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600 bg-indigo-50/10' : 'border-transparent text-slate-400'}`}>
                    Plan Details
                </button>
                <button onClick={() => setTab('Actual')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Actual' ? 'border-emerald-50 text-emerald-600 bg-emerald-50/10' : 'border-transparent text-slate-400'}`}>
                    Actual Results
                </button>
              </div>
            )}
        </div>

        <div className="p-6 relative overflow-y-auto custom-scrollbar flex-1">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors z-20"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {holidayInfo && (
                      <div className={`mt-3 p-3 border rounded-xl flex items-center gap-3 shadow-sm ${
                        holidayInfo.type === 'Public Holiday' ? 'bg-rose-50 dark:bg-rose-900/20 border-rose-200 dark:border-rose-800' :
                        holidayInfo.type === 'Rest Day' ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-200 dark:border-indigo-800' :
                        'bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-800'
                      }`}>
                        <div className={`p-2 rounded-lg text-white ${
                            holidayInfo.type === 'Public Holiday' ? 'bg-rose-500' :
                            holidayInfo.type === 'Rest Day' ? 'bg-indigo-500' :
                            'bg-amber-500'
                        }`}>
                          <Ban className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className={`text-[10px] font-black uppercase tracking-widest leading-none mb-1 ${
                                holidayInfo.type === 'Public Holiday' ? 'text-rose-600 dark:text-rose-400' :
                                holidayInfo.type === 'Rest Day' ? 'text-indigo-600 dark:text-indigo-400' :
                                'text-amber-600 dark:text-amber-400'
                          }`}>{holidayInfo.type} Alert</p>
                          <p className="text-xs font-black text-slate-900 dark:text-white leading-tight">{holidayInfo.description}</p>
                        </div>
                      </div>
                    )}
                </div>

                {tab === 'Plan' ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {availableProcesses.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value.toUpperCase())} className={inputClasses} placeholder="Enter product name..." />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="flex-1">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Target Plan Qty</label>
                                <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                            </div>
                            <div className="w-24">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                    {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5"><MessageSquare className="w-3 h-3" /> Plan Remark</label>
                            <textarea value={planRemark} onChange={e => setPlanRemark(e.target.value.toUpperCase())} className={`${inputClasses} h-20 resize-none font-medium text-xs`} placeholder="ADD PLANNING NOTES..." />
                        </div>
                    </>
                ) : (
                    <>
                        {!editEntry && (
                          <div className="space-y-4">
                               <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Filter by Department</label>
                                    <select value={category} onChange={e => { setCategory(e.target.value as Category); setSelectedPlanId(''); }} className={inputClasses}>
                                        {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                    </select>
                               </div>

                               <div>
                                   <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Pending Job</label>
                                   {filteredPlans.length === 0 ? <div className="text-xs text-slate-400 font-bold italic text-center p-6 border-2 border-dashed rounded-xl bg-slate-50 dark:bg-slate-900/30">No {category} plans found for this date.</div> : (
                                       <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50 custom-scrollbar">
                                           {filteredPlans.map(p => (
                                               <div key={p.id} onClick={() => { setSelectedPlanId(p.id); setProductName(p.productName); setProcess(p.process); }}
                                                  className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                                  <div className="font-black text-sm uppercase leading-tight mb-1">{p.productName}</div>
                                                  <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-emerald-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity} {p.unit || 'KG'}</div>
                                               </div>
                                           ))}
                                       </div>
                                   )}
                               </div>
                          </div>
                        )}
                        {(selectedPlanId || editEntry) && (
                            <div className="space-y-4 mt-6 pt-6 border-t dark:border-slate-700 animate-in slide-in-from-top-2">
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="flex-1">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Result Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div className="w-24">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                        <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                            {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                        </select>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                  </div>
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower Used</label>
                                    <input type="number" required step="0.01" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                  </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5"><MessageSquare className="w-3 h-3" /> Actual Remark</label>
                                    <textarea value={actualRemark} onChange={e => setActualRemark(e.target.value.toUpperCase())} className={`${inputClasses} h-20 resize-none font-medium text-xs`} placeholder="ADD ACTUAL NOTES..." />
                                </div>
                            </div>
                        )}
                    </>
                )}

                <button 
                    type="submit" 
                    disabled={isSubmitting || (tab === 'Actual' && !selectedPlanId && !editEntry)} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-4 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600' : 'bg-emerald-600'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : (tab === 'Actual' ? 'Submit & Mark Completed' : 'Save Plan Entry')}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { ProductionEntry, Category } from '../../types';
import { CATEGORIES } from '../../constants';
import { AlertCircle, CheckCircle2, Palmtree, ClipboardCheck, Users, Building2, Filter } from 'lucide-react';
import { getTodayISO, getWeeklyOffDayType } from '../../utils/dateUtils';

export const InputActual: React.FC = () => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [date, setDate] = useState(getTodayISO());
  const [selectedDept, setSelectedDept] = useState<Category>(CATEGORIES[0]);

  const [pendingPlans, setPendingPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const [formData, setFormData] = useState({
    actualQty: '',
    manpower: '0.00',
    batchNo: '',
    actualRemark: ''
  });

  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => {
    const manual = offDays.find(od => od.date === date);
    if (manual) return manual;
    const auto = getWeeklyOffDayType(date);
    if (auto) return { type: auto, description: auto === 'Rest Day' ? 'Friday Weekly Rest' : 'Saturday Weekly Off' };
    return null;
  }, [date, offDays]);

  useEffect(() => {
    const all = StorageService.getProductionData();
    const forDate = all.filter(p => p.date === date && p.category === selectedDept);
    setPendingPlans(forDate);
    setSelectedPlanId('');
    setFormData({ actualQty: '', manpower: '0.00', batchNo: '', actualRemark: '' });
  }, [date, selectedDept]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedPlanId) {
      setMsg({ type: 'error', text: 'Please select a job node to update.' });
      return;
    }

    try {
      const allData = StorageService.getProductionData();
      const updatedData = allData.map(entry => {
        if (entry.id === selectedPlanId) {
          return {
            ...entry,
            actualQuantity: parseInt(formData.actualQty || '0'),
            manpower: parseFloat(formData.manpower || '0'),
            batchNo: formData.batchNo,
            actualRemark: formData.actualRemark,
            status: 'Completed' as const,
            lastUpdatedBy: user!.id,
            updatedAt: new Date().toISOString()
          };
        }
        return entry;
      });

      StorageService.saveProductionData(updatedData);

      const target = allData.find(e => e.id === selectedPlanId);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'RECORD_ACTUAL',
        details: `Recorded output for ${target?.productName}: ${formData.actualQty} units with ${parseFloat(formData.manpower).toFixed(2)} manpower`
      });

      triggerRefresh();
      setMsg({ type: 'success', text: 'Production record updated and synchronized.' });

      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'ACTUAL PRODUCTION SYNCHRONIZED', type: 'success' } 
      }));

      // Refresh pending list
      setPendingPlans(updatedData.filter(p => p.date === date && p.category === selectedDept));
    } catch (err) {
      setMsg({ type: 'error', text: 'Error communicating with storage.' });
    }
  };

  const inputClasses = "w-full p-3.5 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-emerald-500/20";

  return (
    <div className="max-w-2xl mx-auto py-8">
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-gray-100 dark:border-slate-700 p-10 animate-in fade-in slide-in-from-bottom-4">
        <div className="flex items-center gap-4 mb-8">
          <div className="p-3 bg-emerald-100 dark:bg-emerald-900/40 rounded-2xl">
            <ClipboardCheck className="w-8 h-8 text-emerald-600 dark:text-emerald-400" />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-800 dark:text-white">Record Production</h2>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Verify floor output and resources</p>
          </div>
        </div>

        {msg && (
          <div className={`p-5 rounded-2xl mb-8 flex items-center gap-4 animate-pulse ${msg.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-rose-50 text-rose-700 border border-rose-100'}`}>
            {msg.type === 'success' ? <CheckCircle2 className="w-6 h-6" /> : <AlertCircle className="w-6 h-6" />}
            <span className="font-bold text-sm uppercase tracking-tight">{msg.text}</span>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Review Date</label>
            <input 
              type="date" 
              className={inputClasses}
              value={date}
              onChange={e => setDate(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1 flex items-center gap-1.5"><Building2 className="w-3 h-3"/> Choose Department</label>
            <select 
              value={selectedDept} 
              onChange={e => setSelectedDept(e.target.value as Category)}
              className={inputClasses}
            >
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          {currentOffDay && (
            <div className="md:col-span-2 mt-2 p-5 bg-amber-50 dark:bg-amber-900/30 border border-amber-300 dark:border-amber-700 rounded-2xl flex items-center gap-4">
              <Palmtree className="w-8 h-8 text-amber-500 shrink-0" />
              <div>
                <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none mb-1">{currentOffDay.type} Alert</p>
                <p className="text-sm font-black text-slate-900 dark:text-amber-50">{currentOffDay.description}</p>
              </div>
            </div>
          )}
        </div>

        <div className="mb-8">
          <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Select Pending {selectedDept} Job Node</label>
          {pendingPlans.length === 0 ? (
            <div className="text-sm text-slate-400 font-bold italic p-8 border-2 border-dashed border-slate-100 dark:border-slate-700 rounded-2xl text-center bg-slate-50/50 dark:bg-slate-900/20">
              No active {selectedDept} plans found for this date.
            </div>
          ) : (
            <div className="space-y-3 max-h-60 overflow-y-auto custom-scrollbar border border-slate-100 dark:border-slate-700 rounded-2xl p-3 bg-slate-50/50 dark:bg-slate-900/50">
              {pendingPlans.map(plan => (
                <div 
                  key={plan.id}
                  onClick={() => {
                    setSelectedPlanId(plan.id);
                    setFormData(prev => ({ 
                      ...prev, 
                      actualQty: plan.actualQuantity ? plan.actualQuantity.toString() : '',
                      manpower: plan.manpower ? plan.manpower.toFixed(2) : '0.00',
                      batchNo: plan.batchNo || '',
                      actualRemark: plan.actualRemark || ''
                    }));
                  }}
                  className={`p-4 rounded-xl cursor-pointer border-2 transition-all ${
                    selectedPlanId === plan.id 
                      ? 'bg-emerald-50 border-emerald-500 shadow-md ring-4 ring-emerald-500/10 dark:bg-emerald-900/20' 
                      : 'bg-white dark:bg-slate-800 border-transparent hover:border-slate-200 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="flex justify-between items-center mb-1">
                    <span className="font-black text-slate-800 dark:text-white uppercase tracking-tight">{plan.productName}</span>
                    <span className="text-[9px] font-black uppercase px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400">{plan.category}</span>
                  </div>
                  <div className="flex justify-between items-end">
                    <span className="text-[10px] font-bold text-indigo-500 dark:text-indigo-400 uppercase tracking-widest">{plan.process}</span>
                    <div className="text-[11px] font-black text-slate-400 uppercase">Target: <span className="text-slate-800 dark:text-white">{plan.planQuantity} {plan.unit}</span></div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {selectedPlanId && (
          <form onSubmit={handleSubmit} className="space-y-6 animate-in slide-in-from-top-4 duration-300">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Actual Yield Qty</label>
                <input 
                  type="number" 
                  min="0"
                  required
                  className={inputClasses.replace('font-bold', 'font-black')}
                  value={formData.actualQty}
                  onChange={e => setFormData({...formData, actualQty: e.target.value})}
                />
              </div>

              <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1 flex items-center gap-1.5">
                  <Users className="w-3 h-3" /> Manpower (2 Decimals)
                </label>
                <input 
                  type="number" 
                  step="0.01"
                  min="0"
                  required
                  className={inputClasses}
                  value={formData.manpower}
                  onBlur={() => setFormData(prev => ({...prev, manpower: parseFloat(prev.manpower || '0').toFixed(2)}))}
                  onChange={e => setFormData({...formData, manpower: e.target.value})}
                />
              </div>
            </div>

            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 ml-1">Official Batch Number</label>
              <input 
                type="text" 
                required
                placeholder="ENTER LOT / BATCH ID..."
                className={inputClasses.replace('font-bold', 'font-black font-mono')}
                value={formData.batchNo}
                onChange={e => setFormData({...formData, batchNo: e.target.value.toUpperCase()})}
              />
            </div>

            <div>
