};

const isWriteLocked = () => {
  const lastWrite = parseInt(localStorage.getItem(KEYS.LAST_WRITE) || '0');
  // 60 second lock to support slower older computers
  return (Date.now() - lastWrite) < 60000; 
};

/**
 * RECONCILIATION LOGIC
 * Solves the 'Ghost Data' problem where deleted records reappear on other computers.
 */
const reconcileData = <T extends { id: string, updatedAt?: string }>(local: T[], cloud: T[]): T[] => {
  const cloudMap = new Map<string, T>();
  cloud.forEach(item => cloudMap.set(String(item.id), item));

  const now = Date.now();
  const result: T[] = [];

  // 1. All cloud items are authoritative for existence
  cloud.forEach(cloudItem => {
    const localItem = local.find(l => String(l.id) === String(cloudItem.id));
    if (localItem && localItem.updatedAt && cloudItem.updatedAt && localItem.updatedAt > cloudItem.updatedAt) {
      result.push(localItem); // Local has a newer edit
    } else {
      result.push(cloudItem); // Cloud is truth
    }
  });

  // 2. Handle items that exist ONLY locally
  local.forEach(localItem => {
    if (!cloudMap.has(String(localItem.id))) {
      const updatedAtStr = localItem.updatedAt || '';
      const updatedAtTime = updatedAtStr.includes(' ') 
        ? new Date(updatedAtStr.replace(' ', 'T')).getTime() 
        : new Date(updatedAtStr).getTime();

      const ageInMinutes = isNaN(updatedAtTime) ? 999 : (now - updatedAtTime) / (1000 * 60);

      // If the item is old (>10 mins) and not in the cloud, it was deleted elsewhere.
      // If it is new (<10 mins), it's a new entry waiting to sync up.
      if (ageInMinutes < 10) {
        result.push(localItem);
      }
    }
  });

  return result;
};

