  local.forEach(localItem => {
    if (!cloudMap.has(String(localItem.id))) {
      // Use updatedAt or timestamp if available
      const updatedAtStr = localItem.updatedAt || (localItem as any).timestamp || '';
      const updatedAtTime = updatedAtStr.includes(' ') 
