import React, { createContext, useContext, useState, useEffect, ReactNode, useRef } from 'react';
import { User, Role } from '../types';
import { StorageService } from '../services/storageService';
import { hashPassword } from '../utils/securityUtils';

interface AuthContextType {
  user: User | null;
  login: (username: string, pass: string) => Promise<boolean>;
  logout: () => void;
  hasPermission: (roles: Role[]) => boolean;
  loginAttempts: number;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const MAX_ATTEMPTS = 5;
const COOLDOWN_TIME = 30000;

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lastAttemptTime, setLastAttemptTime] = useState(0);

  useEffect(() => {
    const session = StorageService.getSession();
    if (session) {
      setUser(session);
    }
  }, []);

  const login = async (username: string, pass: string): Promise<boolean> => {
    const now = Date.now();

    if (loginAttempts >= MAX_ATTEMPTS && (now - lastAttemptTime) < COOLDOWN_TIME) {
      return false;
    }

    // Ambil user terkini dari local (yang telah di-sync dari DB)
    const storedUsers = StorageService.getUsers();
    const cleanUsername = username.trim().toLowerCase();

    console.log(`[Login] Mencuba akses untuk: ${cleanUsername}`);

    const targetUser = storedUsers.find(u => u.username.toLowerCase() === cleanUsername);

    if (targetUser) {
      const incomingHash = await hashPassword(pass);

      console.log(`[Login] User dijumpai. Membandingkan password...`);
      console.log(`[Debug] Hash input: ${incomingHash}`);
      console.log(`[Debug] Hash di DB: ${targetUser.password}`);

      // Semak jika password sepadan (Sama ada hash atau plaintext untuk admin lama)
      if (targetUser.password === incomingHash || targetUser.password === pass) {
        console.log(`[Login] Berjaya!`);
        setUser(targetUser);
        StorageService.setSession(targetUser);
        setLoginAttempts(0);
        return true;
      } else {
        console.warn(`[Login] Password salah.`);
      }
    } else {
      console.warn(`[Login] Username tidak wujud dalam sistem.`);
    }

    setLoginAttempts(prev => prev + 1);
    setLastAttemptTime(now);
    return false;
  };

  const logout = () => {
    setUser(null);
    StorageService.setSession(null);
  };

  const hasPermission = (allowedRoles: Role[]) => {
    if (!user) return false;
    return allowedRoles.includes(user.role);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, hasPermission, loginAttempts }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

